def _shipped_default_venue_profile() -> dict:
    """The default profile's SINGLE SOURCE OF TRUTH.

    `add-venue` can update the shipped `venue_profiles/<default>.json` with
    numbers verified against the journal's own pages and new article types.
    A normal checkout always reads the shipped file (the single source of
    truth); the embedded literal below is only the fallback for a STRIPPED
    deployment (script only, no venue_profiles/). That fallback is the
    pipeline's original pre-venue requirement set, so it deliberately carries
    FEWER article types (8, Article-only numbers) than the shipped profile --
    a stripped deployment runs the legacy rule set, not a mirrored copy of the
    curated one.
    """
    try:
        p = (Path(__file__).resolve().parent / VENUE_PROFILES_DIRNAME
             / f"{DEFAULT_VENUE}{VENUE_PROFILE_SUFFIX}")
        data = json.loads(p.read_text(encoding="utf-8"))
        if isinstance(data, dict) \
                and str(data.get("id") or "").strip().lower() == DEFAULT_VENUE:
            return data
    except (OSError, ValueError, NameError):
        pass
    return copy.deepcopy(_DEFAULT_VENUE_PROFILE)


BUILTIN_VENUE_PROFILES = {
    DEFAULT_VENUE: _shipped_default_venue_profile(),
    _GENERIC_VENUE_PROFILE["id"]: _GENERIC_VENUE_PROFILE,
}


def _profile_int(value, field: str, problems: list, *, minimum=None, allow_none=True):
    """An optional non-negative integer profile field."""
    if value is None:
        if allow_none:
            return None
        problems.append(f"{field} is required")
        return None
    if isinstance(value, bool) or not isinstance(value, int):
        problems.append(f"{field} must be an integer (got {value!r})")
        return None
    if minimum is not None and value < minimum:
        problems.append(f"{field} must be >= {minimum} (got {value})")
        return None
    return value


def _profile_str_list(value, field: str, problems: list) -> list:
    if value is None:
        return []
    if not isinstance(value, (list, tuple)):
        problems.append(f"{field} must be a list of strings")
        return []
    out = []
    for item in value:
        if not isinstance(item, str) or not item.strip():
            problems.append(f"{field} must hold non-empty strings (got {item!r})")
            continue
        out.append(item.strip())
    return out


def _slugify_article_type(label: str) -> str:
    """`Brief Communication` -> `brief-communication` (an id from a label)."""
    slug = re.sub(r"[^a-z0-9]+", "-", str(label or "").strip().lower()).strip("-")
    return slug or "default"


def _clean_length_limits(limits, prefix: str, problems: list):
    """Validate ONE `length_limits` block (the venue's or an article type's).

    `None` means "this profile carries no numbers here". That is deliberately
    NOT the same as inheriting another article type's numbers: a Brief
    Communication must never be measured against the Article caps, so a type
    without numbers is reported as counts-only and the stage names the limit
    the venue's own table states.
    """
    if limits is None:
        return None
    if not isinstance(limits, dict):
        problems.append(f"{prefix} must be an object, or null for \"no numbers carried\" "
                        f"(got {type(limits).__name__})")
        return None
    clean = {"source": str(limits.get("source") or "").strip()}
    for key in ("abstract", "main_text"):
        spec = limits.get(key)
        if spec is None:
            spec = {}
        if isinstance(spec, (int, float)) and not isinstance(spec, bool):
            spec = {"base": spec}          # a bare number = base words, no relaxation
        if not isinstance(spec, dict):
            problems.append(f"{prefix}.{key} must be an object with 'base' and "
                            f"'relaxation' (or null for both)")
            spec = {}
        base = spec.get("base")
        relaxation = spec.get("relaxation")
        if base is None and relaxation is None:
            clean[key] = {"base": None, "relaxation": None}
            continue
        pairing_error = (base is None) != (relaxation is None)
        base = _profile_int(base, f"{prefix}.{key}.base", problems, minimum=1)
        try:
            relaxation = float(relaxation) if relaxation is not None else None
        except (TypeError, ValueError):
            problems.append(f"{prefix}.{key}.relaxation must be a number >= 1.0 "
                            f"(got {relaxation!r})")
            relaxation = None
        if relaxation is not None and relaxation < 1.0:
            problems.append(f"{prefix}.{key}.relaxation must be >= 1.0 (got "
                            f"{relaxation:g}); the pipeline only relaxes a limit, never "
                            f"tightens it")
            relaxation = None
        if pairing_error:
            problems.append(f"{prefix}.{key}: 'base' and 'relaxation' must be given "
                            f"together (or both null)")
        clean[key] = {"base": base, "relaxation": relaxation}
    # Distinguish "this type states no cover letter at all" (inherit the
    # default type's, handled in length_limits()) from "this type explicitly
    # states no preference" (min/max null): the README documents the latter as
    # none, so the block must survive normalization with its source intact.
    cover_stated = isinstance(limits.get("cover_letter"), dict)
    cover = limits.get("cover_letter") or {}
    if not isinstance(cover, dict):
        problems.append(f"{prefix}.cover_letter must be an object with 'min' and 'max' "
                        f"(or null for both)")
        cover = {}
    cover_min = _profile_int(cover.get("min"), f"{prefix}.cover_letter.min", problems,
                             minimum=0)
    cover_max = _profile_int(cover.get("max"), f"{prefix}.cover_letter.max", problems,
                             minimum=0)
    if cover_min is not None and cover_max is not None and cover_min > cover_max:
        problems.append(f"{prefix}.cover_letter.min ({cover_min}) must not exceed "
                        f"max ({cover_max})")
    cover_total = _profile_int(cover.get("total_max"), f"{prefix}.cover_letter.total_max",
                               problems, minimum=1)
    if cover_total is not None and cover_max is not None and cover_total < cover_max:
        problems.append(f"{prefix}.cover_letter.total_max ({cover_total}) must not be below "
                        f"the persuading-part max ({cover_max})")
    if cover_stated:
        clean["cover_letter"] = {"min": cover_min, "max": cover_max,
                                 "total_max": cover_total,
                                 "source": str(cover.get("source") or "").strip()}
    return clean


def _clean_captions(captions, prefix: str, problems: list):
    """Validate one legend policy block; None means "inherit the venue's"."""
    if captions is None:
        return None
    if not isinstance(captions, dict):
        problems.append(f"{prefix} must be an object, or null to inherit the venue's legend "
                        f"policy (got {type(captions).__name__})")
        return None
    clean = {
        "published_limit": _profile_int(captions.get("published_limit"),
                                        f"{prefix}.published_limit", problems, minimum=0),
        "default_cap": _profile_int(captions.get("default_cap", 0), f"{prefix}.default_cap",
                                    problems, minimum=0, allow_none=False) or 0,
        "source": str(captions.get("source") or "").strip(),
    }
    if clean["published_limit"] is not None and clean["default_cap"] == 0:
        clean["default_cap"] = clean["published_limit"]
    return clean


EMPTY_LENGTH_LIMITS = {"source": "", "abstract": {"base": None, "relaxation": None},
                       "main_text": {"base": None, "relaxation": None},
                       "cover_letter": {"min": None, "max": None, "total_max": None, "source": ""}}
EMPTY_CAPTIONS = {"published_limit": None, "default_cap": 0, "source": ""}
# The venue's DISPLAY-ITEM rules (the formatter's `policy["tables"]` and
# `policy["figures"]`, rules FMT-TB1..3 / FMT-FG1..3): where a table or a figure
# belongs, which side of it carries its caption, and the items the venue itself
# treats differently. An EMPTY block means "this profile declares no rule for
# that kind" -- the scan then reports none, and no stage is gated on one (a rule
# no level of the authority chain states is never invented). The two blocks have
# the SAME schema, so they share one validator.
DISPLAY_PLACEMENTS = ("end", "inline", "any")
DISPLAY_CAPTION_SIDES = ("before", "after", "any")
EMPTY_TABLES = {"source": "", "note": "", "placement": "", "caption": "", "special": []}
EMPTY_FIGURES = {"source": "", "note": "", "placement": "", "caption": "", "special": []}


def _declares_display_rule(block: dict) -> bool:
    """Does a `tables`/`figures` block state a rule (not just a source/note)?

    A block that carries only a `source`/`note` states no rule, so nothing is
    checked or gated on it; a `placement` or a `caption` value (or a
    special-item entry) is a rule the stages enforce.
    """
    return bool((block or {}).get("placement") or (block or {}).get("caption")
                or (block or {}).get("special"))


def _clean_display_rules(raw, prefix: str, problems: list):
    """Validate one venue TABLE/FIGURE policy block; None means "declares none".

    The block is DATA, exactly like the caption policy: the pipeline renders it
    into the prompts and hands it to the formatter as `policy["tables"]` /
    `policy["figures"]`, and the formatter checks exactly what it states.
    `special` entries exist for the items a publisher genuinely treats
    differently (a Cell Press-style key-resources table that lives inside the
    methods and carries no "Table N." label; a front-matter figure such as a
    graphical abstract that is not part of the numbered figure sequence); each
    entry overrides only the fields it sets.
    """
    if raw is None:
        return None
    if not isinstance(raw, dict):
        problems.append(f"{prefix} must be an object, or null when the venue profile declares "
                        f"no rule for that kind (got {type(raw).__name__})")
        return None
    placement = str(raw.get("placement") or "").strip().lower()
    if placement and placement not in DISPLAY_PLACEMENTS:
        problems.append(f"{prefix}.placement {placement!r} is not one of "
                        f"{', '.join(DISPLAY_PLACEMENTS)}")
    caption = str(raw.get("caption") or "").strip().lower()
    if caption and caption not in DISPLAY_CAPTION_SIDES:
        problems.append(f"{prefix}.caption {caption!r} is not one of "
                        f"{', '.join(DISPLAY_CAPTION_SIDES)}")
    specials, seen = [], set()
    for i, entry in enumerate(raw.get("special") or []):
        if not isinstance(entry, dict):
            problems.append(f"{prefix}.special[{i}] must be an object")
            continue
        match = str(entry.get("match") or "").strip()
        if not match:
            problems.append(f"{prefix}.special[{i}].match is required (a regular expression "
                            f"over the item's context: the text above it, its section heading "
                            f"or, for a table, its first-row header)")
            continue
        try:
            re.compile(match)
        except re.error as e:
            problems.append(f"{prefix}.special[{i}].match {match!r} is not a regular "
                            f"expression: {e}")
        if match.lower() in seen:
            problems.append(f"{prefix}.special: duplicate match {match!r}")
        seen.add(match.lower())
        s_placement = str(entry.get("placement") or "").strip().lower()
        if s_placement and s_placement not in DISPLAY_PLACEMENTS:
            problems.append(f"{prefix}.special[{i}].placement {s_placement!r} is not one of "
                            f"{', '.join(DISPLAY_PLACEMENTS)}")
        s_caption = str(entry.get("caption") or "").strip().lower()
        if s_caption and s_caption not in DISPLAY_CAPTION_SIDES + ("none",):
            problems.append(f"{prefix}.special[{i}].caption {s_caption!r} is not one of "
                            f"{', '.join(DISPLAY_CAPTION_SIDES + ('none',))}")
        specials.append({"match": match, "placement": s_placement, "caption": s_caption,
                         "source": str(entry.get("source") or "").strip(),
                         "note": str(entry.get("note") or "").strip()})
    return {"source": str(raw.get("source") or "").strip(),
            "note": str(raw.get("note") or "").strip(),
            "placement": placement if placement in DISPLAY_PLACEMENTS else "",
            "caption": caption if caption in DISPLAY_CAPTION_SIDES else "",
            "special": specials}


def normalize_venue_profile(data, origin: str = "<builtin>") -> dict:
    """Validate a venue profile and fill its defaults, or raise VenueProfileError.

    The schema is documented in `venue_profiles/README.md`. Everything the
    pipeline reads is validated here, once, at the boundary: a profile that
    passes is safe for every stage to consume, and a profile that does not is
    reported with every problem it has (not just the first one).
    """
    if not isinstance(data, dict):
        raise VenueProfileError(f"{origin}: a venue profile must be a JSON object "
                                f"(got {type(data).__name__})")
    problems: list = []
    out = copy.deepcopy(data)

    venue_id = str(out.get("id") or "").strip().lower()
    if not venue_id:
        problems.append("'id' is required (a short slug, e.g. \"nature-biotechnology\")")
    elif not VENUE_ID_RE.match(venue_id):
        problems.append(f"'id' {venue_id!r} is not a slug: letters, digits, '.', '_', '+', "
                        f"'-' only")
    label = str(out.get("label") or "").strip()
    if not label:
        label = venue_id or "(unnamed venue)"
    short = str(out.get("short") or "").strip() or label
    article_type = str(out.get("article_type") or "").strip() or "Article"

    # ---- the venue's ARTICLE TYPES -------------------------------------
    # A venue publishes several content types, each with its own limits
    # (Article, Brief Communication, Review, Resource, Analysis, Matters
    # Arising, ...). The profile carries them as a table; a submission selects
    # one (`setup --article-type`, `set-article-type`), and a type whose numbers
    # the profile does not carry is reported as counts-only rather than being
    # measured against another type's caps. A profile written in the older,
    # single-type shape (top-level `article_type`/`length_limits`/`captions`)
    # is read as a one-entry table, so it keeps exactly its old behaviour.
    types_raw = out.get("article_types")
    if types_raw is None:
        types_raw = [{"id": _slugify_article_type(article_type), "label": article_type,
                      "length_limits": out.get("length_limits"),
                      "captions": out.get("captions")}]
    elif not isinstance(types_raw, list) or not types_raw:
        problems.append("'article_types' must be a non-empty list of objects "
                        "(or absent for a single-type profile)")
        types_raw = [{"id": "default", "label": article_type}]
    clean_types = []
    seen_types = set()
    for i, entry in enumerate(types_raw):
        if not isinstance(entry, dict):
            problems.append(f"article_types[{i}] must be an object")
            continue
        entry_label = str(entry.get("label") or "").strip()
        type_id = (str(entry.get("id") or "").strip().lower()
                   or _slugify_article_type(entry_label))
        if not VENUE_ID_RE.match(type_id):
            problems.append(f"article_types[{i}].id {type_id!r} is not a slug: letters, "
                            f"digits, '.', '_', '+', '-' only")
        if type_id in seen_types:
            problems.append(f"article_types: duplicate id {type_id!r}")
        seen_types.add(type_id)
        clean_types.append({
            "id": type_id,
            "label": entry_label or type_id,
            "source": str(entry.get("source") or "").strip(),
            "length_limits": _clean_length_limits(entry.get("length_limits"),
                                                  f"article_types[{type_id}].length_limits",
                                                  problems),
            "captions": _clean_captions(entry.get("captions"),
                                        f"article_types[{type_id}].captions", problems),
        })
    if not clean_types:
        clean_types = [{"id": "default", "label": article_type, "source": "",
                        "length_limits": None, "captions": None}]
    default_type_id = (str(out.get("default_article_type") or "").strip().lower()
                       or clean_types[0]["id"])
    type_ids = [t["id"] for t in clean_types]
    if default_type_id not in type_ids:
        problems.append(f"default_article_type {default_type_id!r} is not one of the article "
                        f"types ({', '.join(type_ids)})")
        default_type_id = clean_types[0]["id"]
    default_entry = next(t for t in clean_types if t["id"] == default_type_id)
    # The top-level fields stay the DEFAULT type's data: a reader that only knows
    # the pre-article-type shape (an older tool, a hand-written config) sees
    # exactly what it saw before, and `set-article-type` re-points the accessors.
    clean_limits = (copy.deepcopy(default_entry["length_limits"])
                    if default_entry["length_limits"] is not None
                    else copy.deepcopy(EMPTY_LENGTH_LIMITS))
    clean_captions = (copy.deepcopy(default_entry["captions"])
                      if default_entry["captions"] is not None
                      else copy.deepcopy(EMPTY_CAPTIONS))

    journals = _profile_str_list(out.get("journals"), "journals", problems)
    aliases = _profile_str_list(out.get("journal_aliases"), "journal_aliases", problems)
    patterns = _profile_str_list(out.get("journal_patterns"), "journal_patterns", problems)
    for pat in patterns:
        try:
            re.compile(pat)
        except re.error as e:
            problems.append(f"journal_patterns entry {pat!r} is not a regular expression: {e}")
    prompt = out.get("prompt") or {}
    if not isinstance(prompt, dict):
        problems.append("'prompt' must be an object")
        prompt = {}
    submission = out.get("submission") or {}
    if not isinstance(submission, dict):
        problems.append("'submission' must be an object")
        submission = {}
    pdf_accepted = submission.get("pdf_accepted")
    if pdf_accepted is not None and not isinstance(pdf_accepted, bool):
        problems.append(f"submission.pdf_accepted must be true, false or null (got "
                        f"{pdf_accepted!r})")
        pdf_accepted = None
    # Validate `formats` BEFORE the single raise below: this call appends its
    # problems, and after the raise nothing it appends would ever be seen (an
    # invalid string silently became an empty list instead of failing).
    formats = _profile_str_list(submission.get("formats"), "submission.formats",
                                problems) or []
    # Another publisher's block headings ("Lead contact", "Key resources", ...)
    # are DATA a venue declares, never pipeline knowledge: the formatter reads
    # this list through `venue_containers()` and its own default is empty.
    foreign = _profile_str_list(out.get("foreign_container_headings"),
                                "foreign_container_headings", problems) or []
    # Another publisher's boilerplate phrases (FMT-L1): same contract as the
    # foreign container headings -- profile DATA, empty by default, never a
    # phrase list the engine invents.
    leftover = _profile_str_list(out.get("leftover_phrases"),
                                 "leftover_phrases", problems) or []
    # The venue's display-item numbering convention (FMT-O1). "" = the profile
    # states none, which means the scan reports no ordering row.
    numbering = str(out.get("numbering") or "").strip().lower()
    if numbering and numbering not in ("citation", "none"):
        problems.append(f"numbering must be 'citation' or 'none' (got {numbering!r})")
        numbering = ""
    # The reference-entry policy (FMT-R5): only `flag_preprints` today, so a
    # venue that accepts preprints without comment sets it false/absent.
    references_in = out.get("references")
    clean_references = {}
    if references_in is not None and not isinstance(references_in, dict):
        problems.append("references must be an object or null")
    elif isinstance(references_in, dict):
        flag = references_in.get("flag_preprints")
        if flag is not None and not isinstance(flag, bool):
            problems.append("references.flag_preprints must be true, false or null")
        else:
            clean_references["flag_preprints"] = bool(flag)
    clean_tables = _clean_display_rules(out.get("tables"), "tables", problems)
    clean_figures = _clean_display_rules(out.get("figures"), "figures", problems)
    # The profile's own provenance map (C15 preserves it): a non-object value
    # is a malformed field like any other and must be reported, not dropped.
    raw_sources = out.get("sources")
    if raw_sources is not None and not isinstance(raw_sources, dict):
        problems.append("'sources' must be an object of name -> URL/string (the profile's "
                        "provenance map); got " + type(raw_sources).__name__)

    if problems:
        raise VenueProfileError(f"{origin}: " + "; ".join(problems))

    clean_prompt = {
        "subject": str(prompt.get("subject") or f"a {label} manuscript submission").strip(),
        "editor": str(prompt.get("editor") or f"a {label} editor or reviewer").strip(),
        "requirements": str(prompt.get("requirements")
                            or f"the {label} author guidelines and submission requirements").strip(),
        "requirement_authority": str(prompt.get("requirement_authority") or label).strip(),
        "guidelines_source": str(prompt.get("guidelines_source")
                                 or f"the current {label} author guidelines").strip(),
    }
    # The profile's own provenance: SKILL.md points the sessions at it ("the
    # profile's own `sources` field names where its numbers come from"), and
    # the rebuilt return value used to drop the key, so a stage reading the
    # profile through VenueProfile.data could not name the guideline it used.
    clean_sources = ({str(k): str(v) for k, v in raw_sources.items()}
                     if isinstance(raw_sources, dict) else {})
    return {
        "id": venue_id,
        "label": label,
        "short": short,
        "sources": clean_sources,
        "description": str(out.get("description") or "").strip(),
        "article_type": default_entry["label"],
        "article_type_id": default_type_id,
        "default_article_type": default_type_id,
        "article_types": clean_types,
        "journals": journals,
        "journal_aliases": aliases,
        "journal_patterns": patterns,
        "accepts_any_journal": bool(out.get("accepts_any_journal")),
        "default_journal": str(out.get("default_journal") or "").strip(),
        "length_limits": clean_limits,
        "captions": clean_captions,
        "tables": clean_tables or copy.deepcopy(EMPTY_TABLES),
        "figures": clean_figures or copy.deepcopy(EMPTY_FIGURES),
        "foreign_container_headings": foreign,
        "leftover_phrases": leftover,
        "numbering": numbering,
        "references": clean_references,
        "submission": {
            "pdf_accepted": pdf_accepted,
            "formats": formats,
            "pdf_note": str(submission.get("pdf_note") or "").strip(),
        },
        "prompt": clean_prompt,
    }


class VenueProfile:
    """A validated venue profile plus where it came from.

    Every stage reads the venue through this object: the prompt text, the
    length limits and the caption policy are all derived from the profile's own
    fields, so adding a venue means adding a JSON document, not a branch in the
    pipeline.
    """

    def __init__(self, data, origin: str = "<builtin>", path=None,
                 article_type_id: str = None):
        self.data = normalize_venue_profile(data, origin)
        self.origin = origin
        self.path = Path(path) if path is not None else None
        self.article_type_id = self._known_type(article_type_id) or \
            self.data["default_article_type"]

    # ---- article types ----
    def _type_entry(self, type_id: str = None) -> dict:
        wanted = str(type_id if type_id is not None else self.article_type_id).strip().lower()
        for entry in self.data["article_types"]:
            if entry["id"] == wanted:
                return entry
        return self.data["article_types"][0]

    def _default_type_entry(self) -> dict:
        return self._type_entry(self.data["default_article_type"])

    def _known_type(self, type_id) -> str:
        """The slug of `type_id` when the profile has it, else ""."""
        wanted = str(type_id or "").strip().lower()
        return wanted if any(t["id"] == wanted for t in self.data["article_types"]) else ""

    def article_type_ids(self) -> list:
        return [t["id"] for t in self.data["article_types"]]

    def article_types(self) -> list:
        """[(id, label, carries_numbers), ...] in profile order, for --list."""
        return [(entry["id"], entry["label"], self.carries_article_numbers(entry["id"]))
                for entry in self.data["article_types"]]

    def carries_article_numbers(self, type_id: str = None) -> bool:
        """Does the profile state abstract/main-text numbers for `type_id`?

        A type entry that is absent, null, or declares only null bases carries
        NO numbers: the stages then count and name the venue's own limit instead
        of being measured against another type's caps.
        """
        limits = self._type_entry(type_id).get("length_limits") or {}
        return any((limits.get(key) or {}).get("base") is not None
                   or (limits.get(key) or {}).get("relaxation") is not None
                   for key in ("abstract", "main_text"))

    def with_article_type(self, type_id) -> "VenueProfile":
        """The same venue with another article type selected.

        The type's own numbers (or its deliberate absence of numbers) drive the
        M19 caps, the caption policy and the prompt prose from here on; the
        venue-level cover-letter preference and legend policy still apply.
        """
        wanted = self._known_type(type_id) or None
        if wanted is None:
            wanted = str(type_id or "").strip().lower()
            raise VenueProfileError(
                f"unknown article type {type_id!r} for venue {self.id!r} "
                f"(available: {', '.join(self.article_type_ids())})")
        if wanted == self.article_type_id:
            return self
        clone = copy.copy(self)
        clone.article_type_id = wanted
        return clone

    # ---- identity ----
    @property
    def id(self) -> str:
        return self.data["id"]

    @property
    def label(self) -> str:
        return self.data["label"]

    @property
    def short(self) -> str:
        return self.data["short"]

    @property
    def description(self) -> str:
        return self.data["description"]

    @property
    def article_type(self) -> str:
        return self._type_entry()["label"]

    @property
    def article_type_source(self) -> str:
        return self._type_entry().get("source") or ""

    @property
    def default_journal(self) -> str:
        return self.data["default_journal"]

    @property
    def prompt(self) -> dict:
        return self.data["prompt"]

    @property
    def captions(self) -> dict:
        entry = self._type_entry()
        if entry.get("captions") is not None:
            return entry["captions"]
        default = self._default_type_entry()
        return default.get("captions") or EMPTY_CAPTIONS

    @property
    def caption_default(self) -> int:
        return int(self.captions.get("default_cap") or 0)

    @property
    def tables(self) -> dict:
        """The venue's table rule (EMPTY_TABLES when the profile declares none)."""
        return self.data.get("tables") or EMPTY_TABLES

    @property
    def figures(self) -> dict:
        """The venue's figure rule (EMPTY_FIGURES when the profile declares none)."""
        return self.data.get("figures") or EMPTY_FIGURES

    @property
    def declares_table_rule(self) -> bool:
        """Does this profile state where captioned tables belong, and how?"""
        return _declares_display_rule(self.tables)

    @property
    def declares_figure_rule(self) -> bool:
        """Does this profile state where captioned figures belong, and how?"""
        return _declares_display_rule(self.figures)

    @property
    def length_limits_source(self) -> str:
        entry = self._type_entry()
        limits = entry.get("length_limits") or {}
        source = limits.get("source") or entry.get("source")
        if source:
            return source
        if entry["length_limits"] is None:
            return (f"{self.label} submission rules ({entry['label']}: this profile carries no "
                    f"numbers for that article type -- the stage names the venue's own limit)")
        return f"{self.label} submission rules ({entry['label']})"

    def to_dict(self) -> dict:
        return copy.deepcopy(self.data)

    def length_limits(self) -> dict:
        """The M19 caps, in the shape the code-side scan and the prompts use.

        Abstract and main text come from the SELECTED article type (a type the
        profile carries no numbers for has `cap: None`, never another type's
        cap); the cover-letter preference is venue-level, so a type entry that
        does not state one inherits the default type's.
        """
        raw = self._type_entry().get("length_limits") or {}

        def spec(key: str) -> dict:
            base = (raw.get(key) or {}).get("base")
            relaxation = (raw.get(key) or {}).get("relaxation")
            cap = (lenient_word_limit(base, relaxation)
                   if base is not None and relaxation is not None else None)
            return {"base": base, "relaxation": relaxation, "cap": cap}

        # Inherit only when the type does not state a cover-letter block at
        # all; an explicit block with null min/max MEANS "none" (the README's
        # schema), so it must not be replaced by the default type's preference.
        cover = raw.get("cover_letter")
        if cover is None:
            cover = ((self._default_type_entry().get("length_limits") or {})
                     .get("cover_letter") or {})
        return {"abstract": spec("abstract"),
                "main text": spec("main_text"),
                "cover letter": {"min": cover.get("min"), "max": cover.get("max"),
                                 "total_max": cover.get("total_max"),
                                 "source": cover.get("source") or ""}}

    def known_journals(self) -> list:
        return list(self.data["journals"]) + list(self.data["journal_aliases"])

    def journal_matches(self, journal: str) -> bool:
        """Does `journal` name a journal this profile claims to describe?

        A profile that accepts any journal, or declares no journal names and no
        patterns, never fails this test (it makes no claim to check).
        """
        name = str(journal or "").strip()
        if not name or self.data["accepts_any_journal"]:
            return True
        if not self.known_journals() and not self.data["journal_patterns"]:
            return True
        key = _journal_key(name)
        if key and key in {_journal_key(j) for j in self.known_journals()}:
            return True
        for pat in self.data["journal_patterns"]:
            try:
                if re.search(pat, name, re.IGNORECASE):
                    return True
            except re.error:            # pragma: no cover -- validated on load
                continue
        return False

    def describe_origin(self) -> str:
        return f"{self.origin}" + (f" ({self.path})" if self.path is not None else "")


def venue_profile_search_dirs(root=None) -> list:
    """Where venue profiles are looked up, in precedence order.

    A root-local profile (written by `set-venue --profile`, or edited by hand)
    wins over the copy shipped with the script that is running.
    """
    dirs = []
    if root is not None:
        dirs.append(Path(root) / VENUE_PROFILES_DIRNAME)
    try:
        script_dir = Path(__file__).resolve().parent
    except (NameError, OSError):        # pragma: no cover -- __file__ always set here
        script_dir = None
    if script_dir is not None and script_dir / VENUE_PROFILES_DIRNAME not in dirs:
        dirs.append(script_dir / VENUE_PROFILES_DIRNAME)
    return dirs


def available_venue_profiles(root=None) -> dict:
    """Every venue profile this pipeline can see: id -> descriptor.

    Root-local files win over shipped files of the same id, and both win over
    the built-in copies. A file that does not parse or does not validate is
    listed with its `error` instead of being silently ignored, because
    `set-venue --list` is where the operator finds out why an id is missing.
    """
    found: dict = {}
    for d in venue_profile_search_dirs(root):
        if not d.is_dir():
            continue
        for path in sorted(d.glob(f"*{VENUE_PROFILE_SUFFIX}")):
            try:
                data = json.loads(path.read_text(encoding="utf-8"))
            except (OSError, ValueError) as e:
                found.setdefault(path.stem, {"id": path.stem, "label": path.stem,
                                             "error": f"{path}: not readable JSON: {e}",
                                             "origin": str(d), "path": str(path)})
                continue
            origin = f"root: {d}" if root is not None and \
                Path(d) == Path(root) / VENUE_PROFILES_DIRNAME else f"shipped: {d}"
            try:
                profile = VenueProfile(data, origin=origin, path=path)
            except VenueProfileError as e:
                found.setdefault(path.stem, {"id": path.stem, "label": path.stem,
                                             "error": str(e), "origin": origin,
                                             "path": str(path)})
                continue
            if profile.id in found and found[profile.id].get("path") != str(path):
                # Two files claiming one id: the later one is loadable by
                # nothing (load_venue_profile resolves by id) and used to be
                # invisible in `set-venue --list` -- the command whose job is to
                # show why an id is missing. It is listed under its own stem
                # with the reason; the winner keeps the id (root files win over
                # shipped ones, and the first of two same-directory files wins
                # deterministically by filename order).
                found.setdefault(path.stem, {
                    "id": path.stem, "label": path.stem,
                    "error": (f"{path}: the profile id {profile.id!r} is already provided by "
                              f"{found[profile.id].get('path') or 'another file'}; rename one id "
                              f"or remove the duplicate"),
                    "origin": origin, "path": str(path)})
                continue
            found.setdefault(profile.id, {"id": profile.id, "label": profile.label,
                                          "description": profile.description,
                                          "origin": origin, "path": str(path),
                                          "default_journal": profile.default_journal})
    for vid, data in BUILTIN_VENUE_PROFILES.items():
        # NOT setdefault(): its default argument is evaluated EAGERLY, so a
        # shipped profile whose id is already in `found` could still raise
        # KeyError from a missing display field -- on `set-venue --list`, the
        # command whose job is to show the profiles and name the one to repair.
        if vid in found:
            continue
        found[vid] = {"id": vid, "label": data.get("label") or vid,
                      "description": data.get("description") or "",
                      "origin": "built-in", "path": None,
                      "default_journal": data.get("default_journal") or ""}
    return found


def load_venue_profile(venue_id, root=None) -> VenueProfile:
    """Resolve one venue id to a profile, or raise VenueProfileError/Unknown."""
    vid = str(venue_id or "").strip().lower()
    if not vid:
        raise VenueProfileError("no venue id given", unknown=True)
    if not VENUE_ID_RE.match(vid):
        raise VenueProfileError(f"invalid venue id {venue_id!r}: letters, digits, '.', '_', "
                                f"'+', '-' only", unknown=True)
    for d in venue_profile_search_dirs(root):
        path = Path(d) / f"{vid}{VENUE_PROFILE_SUFFIX}"
        if not path.is_file():
            continue
        try:
            data = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, ValueError) as e:
            raise VenueProfileError(f"{path}: not readable JSON: {e}")
        origin = "root-local profile" if root is not None and \
            Path(d) == Path(root) / VENUE_PROFILES_DIRNAME else "shipped profile"
        return VenueProfile(data, origin=origin, path=path)
    if vid in BUILTIN_VENUE_PROFILES:
        return VenueProfile(BUILTIN_VENUE_PROFILES[vid], origin="built-in")
    raise VenueProfileError(f"unknown venue {venue_id!r}", unknown=True)


def unknown_venue_message(venue_id, root=None) -> str:
    """The one message an operator needs when a venue id resolves to nothing."""
    known = ", ".join(sorted(available_venue_profiles(root)))
    try:
        prog = Path(__file__).name
    except NameError:                   # pragma: no cover -- __file__ always set here
        prog = "paper_pipeline.py"
    return (f"unknown venue {venue_id!r}: no venue profile named "
            f"{str(venue_id or '').strip().lower()!r} was found.\n"
            f"       Available venues: {known or '(none)'}\n"
            f"       List them with `{prog} set-venue --list`. For a FRESH root, create the "
            f"profile as a JSON file and run "
            f"`{prog} setup --source <dir> --root <dir> --venue-profile <file>` (no prior root "
            f"needed); on an EXISTING root use `set-venue <id> --profile <file>`, or place the "
            f"file in {VENUE_PROFILES_DIRNAME}/<id>{VENUE_PROFILE_SUFFIX} next to the script.")


def default_venue_profile() -> VenueProfile:
    """The profile a call that has no root at hand uses (the built-in default).

    This returns the GUARDED object, not a fresh
    `VenueProfile(BUILTIN_VENUE_PROFILES[...])`: that construction re-validated
    the raw shipped data and made one bad hand edit of
    `venue_profiles/<default>.json` brick every command at import (the
    module-level LENGTH_RULE/STANDING_EXEMPTIONS constants call this function),
    including the `set-venue` path that exists to repair it. The guard falls
    back to the embedded literal and warns.
    """
    return _DEFAULT_VENUE_OBJ


# =====================================================================
# VENUE EXEMPLARS -> ADVISORY STRUCTURE NORMS (word / latex templates)
# =====================================================================
# A venue MAY ship a shared, pinned exemplar corpus:
#
#   venue_profiles/<venue-id>.manuscripts/   recently published articles
#                                            downloaded from the venue's OWN
#                                            website / OA sources
#   venue_profiles/<venue-id>.templates/     the DERIVED, structure-only pack:
#                                            structure.json, the summary, the
#                                            word/latex skeletons and MANIFEST
#
# The manuscripts are read ONLY for their STRUCTURE (section order, abstract,
# statement placement); no prose is copied, the pack is generated by CODE (so
# it is deterministic and hash-pinned), and the derived norms are ADVISORY in
# the review/rewrite prompts -- never a gate, never a substitute for the
# venue's own author guidelines (which the profile carries).
VENUE_EXEMPLAR_SUFFIX = ".manuscripts"
VENUE_TEMPLATE_SUFFIX = ".templates"
VENUE_NORM_FILE = "venue_architecture.md"
VENUE_STRUCTURE_FILE = "structure.json"
VENUE_PACK_MANIFEST = "MANIFEST.json"
VENUE_WORD_TEMPLATE = "word-template.md"
VENUE_LATEX_TEMPLATE = "latex-template.tex"
VENUE_EXEMPLAR_TEXT_SUFFIXES = (".tex", ".md", ".markdown", ".txt")
VENUE_EXEMPLAR_DOCX_SUFFIXES = (".docx",)
# The journal's OWN template files (Word .dotx/.docx, LaTeX .tex/.cls/.sty),
# unzipped into this sibling dir. They are AUTHORITATIVE: the derived skeleton,
# the mandatory sections and the class file all come from here when present.
VENUE_OFFICIAL_SUFFIX = ".official"
VENUE_OFFICIAL_REQUIREMENTS = "requirements.json"
TEX_DOCCLASS_RE = re.compile(r"\\documentclass(?:\[[^\]]*\])?\{([^{}]+)\}")

TEX_SECTION_RE = re.compile(r"\\(part|chapter|section|subsection|subsubsection)\*?\{([^{}]*)\}")
MD_HEADING_RE = re.compile(r"^(#{1,4})[ \t]+(.+?)[ \t]*$", re.M)
TEX_ABSTRACT_RE = re.compile(r"\\begin\{abstract\}", re.I)
MD_ABSTRACT_RE = re.compile(r"^#{1,3}[ \t]+abstract\b", re.I | re.M)
_TEX_LEVELS = {"part": 1, "chapter": 1, "section": 1, "subsection": 2, "subsubsection": 3}
# Statement placement is what a venue's structure prescribes beyond the body
# sections; the label is the canonical name the templates use.
VENUE_STATEMENT_PATTERNS = (
    ("Data availability", re.compile(r"data\s+availability", re.I)),
    ("Code availability", re.compile(r"code\s+availability", re.I)),
    ("Ethics", re.compile(r"\bethic", re.I)),
    ("Funding", re.compile(r"\bfunding\b", re.I)),
    ("Author contributions", re.compile(r"author\s+contributions?", re.I)),
    ("Competing interests", re.compile(r"competing\s+interests?|conflict\s+of\s+interest", re.I)),
    ("Acknowledgements", re.compile(r"acknowledg", re.I)),
    ("Supplementary material", re.compile(
        r"supplement(?:ary|al)\s+(material|information|data|tables?|figures?|methods?)", re.I)),
)
# Journal template FILES often embed the venue's own GUIDELINES as sections
# ("Article types", "Manuscript Formatting", ...) next to the sample manuscript.
# Those are not manuscript sections: they are filtered from both tiers (the
# operator can still pin extra mandatory sections in requirements.json).
VENUE_GUIDANCE_SECTIONS = {
    "article types", "manuscript formatting", "nomenclature", "additional requirements",
    "reference styles", "reference style", "figure captions", "keywords",
    "permission to reuse and copyright", "international phonetic alphabet",
    "resource identification initiative", "life science identifiers",
}


def _is_guidance_title(title) -> bool:
    """True when a heading belongs to the template's own instructions."""
    low = str(title or "").strip().strip(":").strip().lower()
    return not low or low in VENUE_GUIDANCE_SECTIONS


def venue_exemplar_dirs(venue_id, root=None) -> list:
    """Existing `<venue-id>.manuscripts/` dirs, precedence order (root first)."""
    vid = str(venue_id or "").strip().lower()
    out = []
    for d in venue_profile_search_dirs(root):
        p = Path(d) / f"{vid}{VENUE_EXEMPLAR_SUFFIX}"
        if p.is_dir():
            out.append(p)
    return out


def venue_pack_dir(venue_id, root=None):
    """The venue's generated template pack dir, or None when it does not exist."""
    vid = str(venue_id or "").strip().lower()
    for d in venue_profile_search_dirs(root):
        p = Path(d) / f"{vid}{VENUE_TEMPLATE_SUFFIX}"
        if (p / VENUE_NORM_FILE).is_file():
            return p
    return None


def venue_official_dirs(venue_id, root=None, profiles_dir=None) -> list:
    """Existing `<venue-id>.official/` dirs (explicit profiles_dir first)."""
    vid = str(venue_id or "").strip().lower()
    out = []
    if profiles_dir:
        p = Path(profiles_dir) / f"{vid}{VENUE_OFFICIAL_SUFFIX}"
        if p.is_dir():
            out.append(p)
    for d in venue_profile_search_dirs(root):
        p = Path(d) / f"{vid}{VENUE_OFFICIAL_SUFFIX}"
        if p.is_dir() and p not in out:
            out.append(p)
    return out


def _normalized_type_spellings(texts) -> list:
    """Article-type names normalized for DOCX-name matching (deduped, ordered)."""
    out = []
    for text in texts:
        norm = re.sub(r"[^a-z0-9]+", " ", str(text or "").lower()).strip()
        if norm and norm not in out:
            out.append(norm)
    return out


def _normalized_article_type_names(profile) -> list:
    """The selected article type's own name spellings (normalized), or [].

    `letter-to-the-editor` normalizes to `letter to the editor`, `editorial`
    to itself: the spellings a run's own documents may legitimately carry.
    """
    if profile is None:
        return []
    label = ""
    for tid, tlabel, _carries in profile.article_types():
        if tid == profile.article_type_id:
            label = tlabel
            break
    return _normalized_type_spellings((profile.article_type_id, label))


def article_type_manuscript_names(ctx=None) -> list:
    """The run's selected article type as DOCX-name spellings ([] when unset)."""
    prof = venue_profile_of(ctx, required=False)
    if prof is not None:
        return _normalized_article_type_names(prof)
    # A root whose venue profile is unavailable still records its article type.
    return _normalized_type_spellings((str(_ctx_cfg(ctx).get("article_type") or ""),))


def _name_is_article_type_manuscript(name, type_names=()) -> bool:
    """True when a DOCX name IS one of the selected article type's spellings.

    `letter-to-the-editor.docx` / `Letter_to_the_Editor.docx` name the
    MANUSCRIPT of a `letter-to-the-editor` run; a trailing version token
    (`-v2`, ` 2`) is ignored. Deliberately a FULL-name match: `main_letter.docx`
    or `letter_to_the_editor_comments.docx` are not the article type's name.
    """
    if not type_names:
        return False
    stem = Path(str(name or "")).stem
    norm = re.sub(r"[^a-z0-9]+", " ", stem.lower()).strip()
    if not norm:
        return False
    for t in type_names:
        t = re.sub(r"[^a-z0-9]+", " ", str(t or "").lower()).strip()
        if not t:
            continue
        if norm == t:
            return True
        if norm.startswith(t + " ") \
                and re.fullmatch(r"(?:v|rev|version|revision|draft)? ?\d{1,3}",
                                 norm[len(t) + 1:]):
            return True
    return False


def docx_document_role(name, manuscript_names=()) -> str:
    """The submission role a package DOCX name advertises: main/supp/cover.

    ONE rule for the whole pipeline: the template resolver (which template a
    DOCX may adopt), the package verifier and the code-side normalizer all read
    the role the same way. A cover letter is a LETTER, not a manuscript: the
    manuscript template must never be applied to one (see
    `template_for_package_file`). `manuscript_names` are the run's OWN
    article-type spellings (`article_type_manuscript_names`): a document named
    for the selected type is that type's MANUSCRIPT, so a `letter-to-the-editor`
    document is a letter ONLY in a run whose article type is not
    `letter-to-the-editor` (a cover letter keeps its `cover` spelling there).
    """
    stem = Path(str(name)).stem.lower()
    if "supp" in stem:
        return "supp"
    if "cover" in stem:
        return "cover"
    if _name_is_article_type_manuscript(stem, manuscript_names):
        return "main"
    if "letter" in stem:
        return "cover"
    return "main"


def official_template_files(venue_id, root=None, profiles_dir=None) -> dict:
    """The venue's OWN deliverable templates, resolved per format.

    Returns `{"official_dir", "word": {"main", "supplementary", "cover"},
    "latex": {"sample", "cls": [...], "bst": [...]}, "sha256": {path: digest}}`;
    an empty dict when the venue ships no `.official` corpus. The ROOT's copy
    wins (setup copies the whole venue_profiles/ tree into the root), so a
    root-local update is what runs.

    Roles are resolved from the file names the journals use (a Word template
    with "template" in its name, a supplementary sibling, and -- when a journal
    publishes one -- a cover-letter template such as `Cover_Letter.docx`; a
    LaTeX sample `.tex` plus the `.cls`/`.bst` it needs). Nothing outside
    `.official` is consulted, and the files are never modified.
    """
    vid = str(venue_id or "").strip().lower()
    dirs = venue_official_dirs(vid, root, profiles_dir)
    if not dirs:
        return {}
    d = Path(dirs[0])
    word, latex = {}, {}
    for p in sorted(d.rglob("*")):
        if not p.is_file():
            continue
        low = p.name.lower()
        if p.suffix.lower() in (".docx", ".dotx"):
            role = docx_document_role(p.name)
            if role == "cover":
                word.setdefault("cover", p)
            elif role == "supp":
                word.setdefault("supplementary", p)
            else:
                word.setdefault("main", p)
        elif p.suffix.lower() in (".tex", ".ltx"):
            if "supp" not in low and "sample" not in latex:
                latex["sample"] = p
            elif "supp" in low and "supplementary" not in latex:
                latex["supplementary"] = p
        elif p.suffix.lower() == ".cls":
            latex.setdefault("cls", []).append(p)
        elif p.suffix.lower() == ".bst":
            latex.setdefault("bst", []).append(p)
    # Prefer a file that literally calls itself the template for the main role.
    if not word.get("main") or "template" not in Path(word["main"]).name.lower():
        cands = [p for p in sorted(d.rglob("*"))
                 if p.is_file() and p.suffix.lower() in (".docx", ".dotx")
                 and "template" in p.name.lower()
                 and docx_document_role(p.name) == "main"]
        if cands:
            word["main"] = cands[0]
    files = {}
    for role, p in list(word.items()) + list(latex.items()):
        for q in (p if isinstance(p, list) else [p]):
            if isinstance(q, Path) and q.is_file():
                files[str(q)] = sha256_file(q)
    return {"official_dir": d, "word": word, "latex": latex, "sha256": files}


def stage_venue_template(ctx: "Ctx", sb: Path) -> dict:
    """Stage the venue's official templates into one sandbox, read-only.

    A prompt that says "use the venue's own template" is not actionable when the
    template lives outside the sandbox: agents are confined to their sandbox
    (plus the skills). Every producing/reviewing sandbox therefore gets a
    `venue_template/` copy (sha256-pinned in its own manifest) when the venue
    ships one. Returns the staged manifest (empty when there is nothing to
    stage), and is idempotent.
    """
    res = official_template_files(venue_id_of(ctx), ctx.root)
    if not res or not venue_templates_enabled():
        return {}
    dst = sb / "venue_template"
    staged = {}
    for role, value in (("word", res.get("word") or {}), ("latex", res.get("latex") or {})):
        for key, p in value.items():
            for q in (p if isinstance(p, list) else [p]):
                if not isinstance(q, Path) or not q.is_file():
                    continue
                target = dst / role / q.name
                if not target.is_file() or sha256_file(target) != sha256_file(q):
                    target.parent.mkdir(parents=True, exist_ok=True)
                    if target.is_file():
                        # the previously staged copy is 0444: an UPDATED venue
                        # template must still be re-stageable (copy2 would raise)
                        make_writable(target)
                    shutil.copy2(q, target)
                with contextlib.suppress(OSError):
                    os.chmod(target, 0o444)
                staged[f"{role}/{q.name}"] = sha256_file(target)
    if staged:
        write_json_atomic(dst / "manifest.json",
                          {"venue": venue_id_of(ctx), "files": staged})
    return staged


def venue_templates_enabled() -> bool:
    """Is the official-template pass on? Default YES; `PAPER_VENUE_TEMPLATES=0` opts out.

    The restyle is default-on because the operator asked for template
    conformance; the escape hatch exists for a venue whose template is wrong or
    for a run that must keep the author's own formatting byte-for-byte.
    """
    v = os.environ.get("PAPER_VENUE_TEMPLATES", "").strip().lower()
    return v not in ("0", "false", "no", "off")


def extract_official_template(path: Path) -> dict:
    """Structure of ONE journal-provided template file (never prose)."""
    suffix = path.suffix.lower()
    out = {"file": path.name, "format": suffix.lstrip("."), "sha256": sha256_file(path),
           "documentclass": "", "sections": [], "abstract": False, "statements": []}
    if suffix in (".cls", ".sty", ".bst"):
        # A class/style file carries no skeleton; its hash pins it and the
        # documentclass is taken from the sample .tex beside it.
        return out
    if suffix in VENUE_EXEMPLAR_TEXT_SUFFIXES:
        try:
            text = path.read_text(encoding="utf-8", errors="replace")
        except OSError:
            return {"skipped": "unreadable"}
        m = TEX_DOCCLASS_RE.search(text)
        out["documentclass"] = m.group(1).strip() if m else ""
        out["sections"] = [{"level": lvl, "title": title}
                           for lvl, title in _sections_from_text(text, suffix)]
        out["abstract"] = bool(TEX_ABSTRACT_RE.search(text) if suffix == ".tex"
                               else MD_ABSTRACT_RE.search(text))
        out["statements"] = [label for label, pat in VENUE_STATEMENT_PATTERNS if pat.search(text)]
        return out
    if suffix in VENUE_EXEMPLAR_DOCX_SUFFIXES:
        parsed = _docx_exemplar_text(path)
        if parsed is None:
            return {"skipped": "docx text could not be extracted (paper_docx_format.py missing "
                               "or not a readable .docx/.dotx)"}
        sections, text = parsed
        out["sections"] = [{"level": lvl, "title": title} for lvl, title in sections]
        out["abstract"] = any(lvl == 1 and t.strip().lower() == "abstract" for lvl, t in sections)
        out["statements"] = [label for label, pat in VENUE_STATEMENT_PATTERNS if pat.search(text)]
        return out
    return {"skipped": f"unsupported suffix {suffix!r}"}


def official_skeleton(records: list, explicit_requirements: dict = None) -> dict:
    """The AUTHORITATIVE skeleton: mandatory sections, class file, statements.

    `mandatory_sections` are the sections present in EVERY parsed official
    sample document, plus any the operator lists explicitly in
    `<venue-id>.official/requirements.json` (`{"mandatory_sections": [...]}`).
    """
    n = len(records)
    positions, spellings, counts = {}, {}, {}
    st_positions, st_spellings = {}, {}
    for rec in records:
        for i, sec in enumerate(rec.get("sections") or []):
            if int(sec.get("level") or 0) != 1:
                continue
            key = str(sec.get("title") or "").strip().lower()
            if not key or _is_guidance_title(sec.get("title")):
                continue
            if _section_is_statement(sec.get("title")):
                # Statement sections are carried by `statements`, not by the
                # body order / mandatory-section list; their SPELLING (the
                # template's own wording) is kept for the skeleton.
                st_positions.setdefault(key, []).append(i)
                st_spellings.setdefault(key, {})
                st_spellings[key][sec["title"].strip()] = \
                    st_spellings[key].get(sec["title"].strip(), 0) + 1
                continue
            counts[key] = counts.get(key, 0) + 1
            positions.setdefault(key, []).append(i)
            spellings.setdefault(key, {})
            spellings[key][sec["title"].strip()] = spellings[key].get(sec["title"].strip(), 0) + 1
    order = sorted(counts, key=lambda k: (sum(positions[k]) / len(positions[k]), k))
    sections = [{"title": max(spellings[k], key=spellings[k].get), "present": counts[k],
                 "n_samples": n,
                 "mean_position": round(sum(positions[k]) / len(positions[k]), 2)}
                for k in order]
    mandatory = [s["title"] for s in sections if n and s["present"] == n]
    classes = [r.get("documentclass") for r in records if r.get("documentclass")]
    statements = []
    for label, _pat in VENUE_STATEMENT_PATTERNS:
        c = sum(1 for r in records if label in (r.get("statements") or []))
        if c:
            statements.append({"label": label, "present": c, "n_samples": n})
    st_order = sorted(st_positions, key=lambda k: (sum(st_positions[k]) / len(st_positions[k]), k))
    statement_sections, seen_st = [], set()
    for k in st_order:
        title = max(st_spellings[k], key=st_spellings[k].get)
        word_key = tuple(sorted(set(re.findall(r"[a-z0-9]+", title.lower()))))
        if word_key in seen_st:
            continue
        seen_st.add(word_key)
        statement_sections.append(title)
    # Mandatory sections are computed over the samples that carry a BODY at all:
    # a supplementary-material template in the same pack must not veto a body
    # section the main samples all share.
    body_samples = 0
    for rec in records:
        if any(int(s.get("level") or 0) == 1 and not _is_guidance_title(s.get("title"))
               and not _section_is_statement(s.get("title")) for s in (rec.get("sections") or [])):
            body_samples += 1
    mandatory = [s["title"] for s in sections
                 if body_samples and s["present"] >= body_samples]
    # The operator's pinned sections must survive the body-samples recompute:
    # requirements.json is authoritative about what this venue ALWAYS requires,
    # even when the sampled official templates do not all carry the section.
    for extra in ((explicit_requirements or {}).get("mandatory_sections") or []):
        if str(extra).strip() and str(extra).strip().lower() not in \
                {m.lower() for m in mandatory}:
            mandatory.append(str(extra).strip())
    return {"n_samples": n, "documentclass": classes[0] if classes else "",
            "sections": sections, "mandatory_sections": mandatory,
            "statements": statements,
            "statement_sections": statement_sections,
            "files": [{"file": r["file"], "format": r.get("format"), "sha256": r["sha256"]}
                      for r in records]}


def official_template_requirements(venue_id, root=None) -> dict:
    """The pinned official-template requirements a session must conform to.

    `advisory_sections` carries the recent-practice order from the same pack:
    some official template packs yield only one parsible official section
    (Frontiers' does), so the architecture-order scan falls back to the
    advisory order -- always labelled as advisory in the row it emits.
    """
    pack = venue_pack_dir(venue_id, root)
    if pack is None:
        return {}
    try:
        data = json.loads((pack / VENUE_STRUCTURE_FILE).read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return {}
    official = (data or {}).get("official") or {}
    if not isinstance(official, dict) or not official.get("sections") \
            and not official.get("mandatory_sections"):
        return {}
    norm = (data or {}).get("norm") or {}
    advisory = [str(s.get("title") or "") for s in (norm.get("sections") or [])
                if isinstance(s, dict) and str(s.get("title") or "").strip()]
    if advisory:
        official = dict(official)
        official["advisory_sections"] = advisory
    return official


_TEMPLATE_HEADING_KEY_RE = re.compile(r"[^a-z0-9]+")
_TEMPLATE_CAPTION_RE = re.compile(r"^\s*(Figure|Fig\.?|Table)\s*(\d{1,3})[A-Za-z]?\b", re.I)


def _heading_key(text) -> str:
    return _TEMPLATE_HEADING_KEY_RE.sub("", str(text or "").lower())


def _docx_style_ids(path: Path) -> list:
    """The style ids a DOCX declares, via the formatter module ([] when absent)."""
    mod = _format_module()
    fn = getattr(mod, "docx_style_ids", None)
    return fn(path) if fn is not None else []


def _docx_front_matter_report(path: Path, template: Path = None, containers=()) -> dict:
    """Front-matter/header/footer facts for one DOCX (see the formatter module)."""
    mod = _format_module()
    fn = getattr(mod, "docx_front_matter_report", None)
    return fn(path, template, containers) if fn is not None else {}


def scan_template_conformance(sources: list, requirements: dict,
                              word_template: Path = None,
                              word_template_supplementary: Path = None,
                              word_template_cover: Path = None,
                              containers=(), manuscript_names=()) -> dict:
    """Code-side official-template conformance rows over a corpus.

    `sources` is the same [(dir, prefix, excluded_top)] shape the other scans
    take. Reports, never gates: a row names the requirement and the file that
    would satisfy it. Detects the LaTeX documentclass when one is required, each
    mandatory section (by heading/title text), the statement sections, the
    ARCHITECTURE order (section sequence and figure/table caption sequence) and,
    when a Word template is given, whether each .docx carries the template's
    style ids. A cover letter is measured against `word_template_cover` only:
    with none, it is skipped -- the manuscript template does not cover a letter.
    """
    req = requirements or {}
    mandatory = [str(s) for s in (req.get("mandatory_sections") or []) if str(s).strip()]
    statements = [str(s.get("label")) for s in (req.get("statements") or [])]
    want_class = str(req.get("documentclass") or "").strip()
    official_titles = [str(s.get("title") or "") for s in (req.get("sections") or [])
                       if isinstance(s, dict) and str(s.get("title") or "").strip()]
    advisory = [str(t) for t in (req.get("advisory_sections") or []) if str(t).strip()]
    # The official pack can yield a single parsable section (Frontiers). Then the
    # recent-practice order is the only usable architecture order; the rows say
    # which basis they used.
    order_basis = "official template"
    order_titles = official_titles
    if len(order_titles) < 2 and len(advisory) >= 2:
        order_titles, order_basis = advisory, "recent practice (advisory)"
    order_index = {}
    for i, t in enumerate(order_titles):
        order_index.setdefault(_heading_key(t), i)

    have_class, texts, docs = "", [], set()
    doc_headings = []           # (doc, title) in document order
    caption_rows = []           # (doc, is_table, number)
    docx_paths = {}             # doc -> Path
    for src, prefix, excluded in sources:
        if not src.is_dir():
            continue
        for p in sorted(src.rglob("*")):
            if not p.is_file() or is_non_document_name(p.name) \
                    or is_bookkeeping_name(p.name):
                continue
            rel = p.relative_to(src).as_posix()
            if excluded and rel.split("/", 1)[0] in excluded:
                continue
            if is_non_manuscript_rel(rel):
                continue
            doc = prefix + rel
            ext = p.suffix.lower()
            if ext in LENGTH_DOCX_EXTS:
                paras = _docx_paragraphs(p)
                if paras is None:
                    continue
                texts.append("\n".join(paras))
                docs.add(doc)
                docx_paths[doc] = p
                seen = set()
                for para in paras:
                    line = para.strip()
                    key = _heading_key(line)
                    if key in order_index and key not in seen:
                        seen.add(key)
                        doc_headings.append((doc, order_titles[order_index[key]]))
                    m = _TEMPLATE_CAPTION_RE.match(line)
                    if m:
                        caption_rows.append((doc, m.group(1).lower().startswith("tab"),
                                             int(m.group(2))))
            elif ext in LENGTH_TEX_EXTS:
                try:
                    text = p.read_text(encoding="utf-8", errors="replace")
                except OSError:
                    continue
                texts.append(text)
                docs.add(doc)
                for m in TEX_SECTION_RE.finditer(text):
                    key = _heading_key(m.group(2))
                    if key in order_index:
                        doc_headings.append((doc, order_titles[order_index[key]]))
                for line in text.splitlines():
                    m = _TEMPLATE_CAPTION_RE.match(line)
                    if m:
                        caption_rows.append((doc, m.group(1).lower().startswith("tab"),
                                             int(m.group(2))))
                m = TEX_DOCCLASS_RE.search(text)
                if m and not have_class:
                    have_class = m.group(1).strip()
            elif ext in LENGTH_TEXT_EXTS:
                try:
                    text = p.read_text(encoding="utf-8", errors="replace")
                except OSError:
                    continue
                texts.append(text)
                docs.add(doc)
                for m in MD_HEADING_RE.finditer(text):
                    key = _heading_key(m.group(2))
                    if key in order_index:
                        doc_headings.append((doc, order_titles[order_index[key]]))
                for line in text.splitlines():
                    m = _TEMPLATE_CAPTION_RE.match(line)
                    if m:
                        caption_rows.append((doc, m.group(1).lower().startswith("tab"),
                                             int(m.group(2))))
    blob = "\n".join(texts)
    low = blob.lower()
    missing_sections = [s for s in mandatory if s.strip().lower() not in low]
    # A statement requirement matches by its PATTERN, not by the canonical
    # label: a template that says "Conflict of Interest" satisfies the
    # "Competing interests" requirement, and one that says "Data Availability
    # Statement" satisfies "Data availability".
    pats = {label: pat for label, pat in VENUE_STATEMENT_PATTERNS}
    missing_statements = [
        s for s in statements
        if not ((pats[s].search(blob) if s in pats else None)
                or s.strip().lower() in low)]
    class_ok = (not want_class or not have_class or have_class == want_class)
    # Architecture order: the first inversion per document, against the official
    # order (or the labelled advisory order when the official pack yields none).
    order_rows = []
    by_doc = {}
    for doc, title in doc_headings:
        by_doc.setdefault(doc, []).append(title)
    for doc, seq in sorted(by_doc.items()):
        for i in range(len(seq)):
            inversion = next((j for j in range(i + 1, len(seq))
                              if order_index.get(_heading_key(seq[j]), -1)
                              < order_index.get(_heading_key(seq[i]), -1)), None)
            if inversion is not None:
                order_rows.append(
                    f"{doc}: section {seq[inversion]!r} appears before {seq[i]!r} "
                    f"(order basis: {order_basis}: {' > '.join(order_titles)})")
                break
    # Figure/table labels: first occurrences must be ascending and gap-free.
    label_rows = []
    for is_table, label in ((False, "Figure"), (True, "Table")):
        nums = [n for _doc, table, n in caption_rows if table is is_table]
        first = []
        for n in nums:
            if n not in first:
                first.append(n)
        if first and first != sorted(first):
            label_rows.append(f"{label} captions are out of order: first occurrences {first}")
        if first:
            gaps = sorted(set(range(1, max(first) + 1)) - set(first))
            if gaps:
                label_rows.append(f"{label} numbering has gaps: {gaps}")
    # Word template styles: every corpus .docx must carry the ids of the
    # template that governs ITS role (main / supplementary / cover letter).
    word_styles_missing = []
    front_rows = []
    if word_template is not None or word_template_supplementary is not None \
            or word_template_cover is not None:
        main_ids = set(_docx_style_ids(Path(word_template))) if word_template else set()
        supp_ids = (set(_docx_style_ids(Path(word_template_supplementary)))
                    if word_template_supplementary is not None else set())
        cover_ids = (set(_docx_style_ids(Path(word_template_cover)))
                     if word_template_cover is not None else set())
        if main_ids or supp_ids or cover_ids:
            for doc, path in sorted(docx_paths.items()):
                role = docx_document_role(doc, manuscript_names)
                if role == "cover":
                    if word_template_cover is None:
                        continue        # no cover-letter template: not a gap
                    want, want_tpl = cover_ids, word_template_cover
                elif role == "supp":
                    want = supp_ids or main_ids
                    want_tpl = (word_template_supplementary
                                if supp_ids else word_template)
                else:
                    want, want_tpl = main_ids, word_template
                if not want or want_tpl is None:
                    continue
                missing = sorted(want - set(_docx_style_ids(path)))
                if missing:
                    word_styles_missing.append({"document": doc, "missing": missing[:12],
                                                "missing_count": len(missing)})
                fm = _docx_front_matter_report(path, want_tpl, containers)
                for row in (fm or {}).get("rows") or []:
                    front_rows.append(f"{doc}: {row}")
    conforms = (bool(req) and not missing_sections and not missing_statements and class_ok
                and not order_rows and not label_rows and not word_styles_missing
                and not front_rows)
    return {"official": bool(req), "required": {"documentclass": want_class,
                                                "mandatory_sections": mandatory,
                                                "statements": statements},
            "found": {"documentclass": have_class, "documents": sorted(docs)},
            "missing_sections": missing_sections, "missing_statements": missing_statements,
            "class_ok": class_ok, "order_basis": order_basis,
            "order_rows": order_rows, "label_rows": label_rows,
            "word_styles_missing": word_styles_missing,
            "word_template_ok": not word_styles_missing,
            "front_matter_rows": front_rows,
            "conforms": conforms,
            "note": ("advisory, code-side: a row names a requirement the official template "
                     "demands and the corpus does not show; the review disposes it"
                     if req else "no official template pack for this venue")}


def venue_profiles_write_dir(root=None) -> Path:
    """Where `add-venue` writes: `<root>/venue_profiles/` when a root is given,
    else the venue_profiles/ directory shipped next to this script."""
    dirs = venue_profile_search_dirs(root)
    return dirs[0] if dirs else Path(VENUE_PROFILES_DIRNAME)


def _exemplar_files(dirp: Path) -> list:
    """Every supported exemplar file under one corpus dir, sorted."""
    out = []
    for p in sorted(dirp.rglob("*")):
        if not p.is_file():
            continue
        suf = p.suffix.lower()
        if suf in VENUE_EXEMPLAR_TEXT_SUFFIXES or suf in VENUE_EXEMPLAR_DOCX_SUFFIXES:
            out.append(p)
    return out


def _sections_from_text(text: str, suffix: str) -> list:
    """[(level, title)] in reading order, from a .tex or markdown/text body."""
    if suffix == ".tex":
        return [(_TEX_LEVELS.get(kind, 1), title.strip())
                for kind, title in TEX_SECTION_RE.findall(text) if title.strip()]
    if suffix in (".md", ".markdown"):
        # Markdown levels are normalized to the LaTeX convention: the first
        # `#` heading is the TITLE (dropped below), `##` is a top-level section
        # (level 1), `###` a subsection (level 2), ...
        raw = [(len(hashes), title.strip())
               for hashes, title in MD_HEADING_RE.findall(text) if title.strip()]
        heads = [(max(1, lvl - 1), title) for lvl, title in raw]
        if raw and raw[0][0] == 1:
            heads = heads[1:]      # the leading `#` heading is the TITLE
        return heads
    return []


def _docx_exemplar_text(path: Path):
    """[(level, title)] + full text from a .docx, or None when unreadable."""
    mod = _format_module()
    if mod is None:
        return None
    try:
        with zipfile.ZipFile(path) as pkg:
            xml = pkg.read("word/document.xml").decode("utf-8", "replace")
    # RuntimeError is what `zipfile` raises for an ENCRYPTED entry and
    # NotImplementedError for an unsupported compression method: neither is an
    # OSError/BadZipFile/KeyError, so a reader that answers "unreadable" must
    # name them (see `paper_docx_format.analyse_package`).
    except (OSError, zipfile.BadZipFile, KeyError, RuntimeError, NotImplementedError):
        return None
    sections, lines = [], []
    for _s, _e, frag in mod.paragraphs(xml):
        text = mod.text_of(frag).strip()
        if not text:
            continue
        lines.append(text)
        style = mod.elem_val(mod.ppr_of(frag), "pStyle") or ""
        m = re.match(r"(?i)^heading\s*([1-4])$", style.replace("-", "").replace(" ", ""))
        if not m:
            m = re.match(r"(?i)^heading([1-4])$", style)
        if m:
            sections.append((int(m.group(1)), text))
    return sections, "\n".join(lines)


def extract_manuscript_structure(path: Path) -> dict:
    """The structure of ONE exemplar: sections, abstract, statements, hash.

    Structure ONLY: the prose is never stored in the pack. An unsupported or
    unreadable file is reported as `skipped` by the caller.
    """
    suffix = path.suffix.lower()
    sections, text = [], ""
    if suffix in VENUE_EXEMPLAR_TEXT_SUFFIXES:
        try:
            text = path.read_text(encoding="utf-8", errors="replace")
        except OSError:
            return {"skipped": "unreadable"}
        sections = _sections_from_text(text, suffix)
        abstract = bool(TEX_ABSTRACT_RE.search(text) if suffix == ".tex"
                        else MD_ABSTRACT_RE.search(text))
    elif suffix in VENUE_EXEMPLAR_DOCX_SUFFIXES:
        parsed = _docx_exemplar_text(path)
        if parsed is None:
            return {"skipped": "docx text could not be extracted (paper_docx_format.py missing "
                               "or not a readable .docx)"}
        sections, text = parsed
        abstract = any(lvl == 1 and t.strip().lower() == "abstract" for lvl, t in sections)
    else:
        return {"skipped": f"unsupported suffix {suffix!r}"}
    statements = [label for label, pat in VENUE_STATEMENT_PATTERNS if pat.search(text)]
    return {"file": path.name, "format": suffix.lstrip("."), "sha256": sha256_file(path),
            "sections": [{"level": lvl, "title": title} for lvl, title in sections],
            "abstract": bool(abstract), "statements": statements}


def structure_norm(records: list) -> dict:
    """The ADVISORY norm: modal section order, presence counts, statements.

    Ordering is by MEAN POSITION (a section's average index across the
    exemplars that carry it), so a section most exemplars put first comes
    first; ties break alphabetically. Presence counts are reported next to the
    order so the reader sees how strong each part of the norm is.
    """
    n = len(records)
    positions, spellings, counts = {}, {}, {}
    for rec in records:
        for i, sec in enumerate(rec.get("sections") or []):
            if int(sec.get("level") or 0) != 1:
                # The modal order is the TOP-LEVEL order; subsections belong to
                # their parent and are reported in structure.json only.
                continue
            key = str(sec.get("title") or "").strip().lower()
            if not key or _is_guidance_title(sec.get("title")):
                continue
            if _section_is_statement(sec.get("title")):
                # Statement sections are reported under "Statement placement",
                # not in the body-section order.
                continue
            counts[key] = counts.get(key, 0) + 1
            positions.setdefault(key, []).append(i)
            spellings.setdefault(key, {})
            spellings[key][sec["title"].strip()] = spellings[key].get(sec["title"].strip(), 0) + 1
    order = sorted(counts, key=lambda k: (sum(positions[k]) / len(positions[k]), k))
    sections = [{"title": max(spellings[k], key=spellings[k].get),
                 "present": counts[k], "n_exemplars": n,
                 "mean_position": round(sum(positions[k]) / len(positions[k]), 2)}
                for k in order]
    statements = []
    for label, _pat in VENUE_STATEMENT_PATTERNS:
        c = sum(1 for r in records if label in (r.get("statements") or []))
        if c:
            statements.append({"label": label, "present": c, "n_exemplars": n})
    return {"n_exemplars": n, "sections": sections, "statements": statements,
            "abstract_present": sum(1 for r in records if r.get("abstract")),
            "formats": sorted({str(r.get("format")) for r in records if r.get("format")}),
            "exemplars": records}


def _norm_section_titles(norm: dict) -> list:
    return [s["title"] for s in (norm.get("sections") or [])]


def _section_is_statement(title) -> bool:
    """True when a section TITLE names one of the template's statement blocks."""
    low = str(title or "").strip().lower()
    return bool(low) and any(pat.search(low) for _label, pat in VENUE_STATEMENT_PATTERNS)


def render_architecture_summary(venue_id: str, norm: dict, official: dict = None) -> str:
    """The structure summary the prompts embed: OFFICIAL first, advisory norm second."""
    off = official or {}
    L = [f"# Venue structure -- {venue_id}", ""]
    if off.get("sections") or off.get("mandatory_sections"):
        L += ["## OFFICIAL journal template (AUTHORITATIVE)", "",
              f"Derived by CODE from {off.get('n_samples') or 0} file(s) of the venue's OWN "
              f"template pack"
              + (f" (class `{off['documentclass']}`)" if off.get("documentclass") else "")
              + ". STRUCTURE ONLY.", "",
              "| # | section | present | mandatory |", "|---|---|---|---|"]
        mandatory = {m.lower() for m in (off.get("mandatory_sections") or [])}
        for i, s in enumerate(off.get("sections") or [], 1):
            L.append(f"| {i} | {s['title']} | {s['present']}/{s['n_samples']} | "
                     + ("YES" if s["title"].lower() in mandatory else "") + " |")
        if off.get("mandatory_sections"):
            L += ["", "Mandatory sections (must exist): "
                  + ", ".join(off["mandatory_sections"]) + "."]
        if off.get("statements"):
            shown = {}
            for title in off.get("statement_sections") or []:
                for label, pat in VENUE_STATEMENT_PATTERNS:
                    if label not in shown and pat.search(title):
                        shown[label] = title
            L += ["", "Statement sections the template carries:", ""]
            for s in off["statements"]:
                L.append(f"- {s['label']} ({s['present']}/{s['n_samples']}"
                         + (f"; template heading: {shown[s['label']]}"
                            if s["label"] in shown else "") + ")")
        L += ["", "Rules: use the journal's template/class and its styles; the mandatory "
              "sections must be present; declaration blocks use the template's own wording; "
              "content the template requires but the manuscript cannot supply becomes a "
              "manual item for the author, never invented text.", ""]
    n = norm.get("n_exemplars") or 0
    if norm.get("sections"):
        L += [f"## Recent-practice structure (ADVISORY, {n} exemplar manuscript(s))", "",
              f"Derived by CODE from {n} exemplar manuscript(s) downloaded from the venue's own "
              f"published articles (formats: {', '.join(norm.get('formats') or []) or 'n/a'}). "
              f"STRUCTURE ONLY: no prose was copied.", "",
              "| # | section | present | mean position |", "|---|---|---|---|"]
        for i, s in enumerate(norm.get("sections") or [], 1):
            L.append(f"| {i} | {s['title']} | {s['present']}/{s['n_exemplars']} | "
                     f"{s['mean_position']:g} |")
        if norm.get("abstract_present"):
            L.append("")
            L.append(f"- Abstract: present in {norm['abstract_present']}/{n} exemplar(s).")
        if norm.get("statements"):
            L += ["", "Statement placement (recent practice):", ""]
            for s in norm["statements"]:
                L.append(f"- {s['label']}: {s['present']}/{s['n_exemplars']}")
        L += ["", "This part is ADVISORY: it fills what the official template leaves open and "
              "never overrides it; no section is added or removed merely to match it."]
    if not L[-1]:
        L.pop()
    return "\n".join(L)


def _skeleton_titles(norm: dict, official: dict = None) -> list:
    """The skeleton order: the OFFICIAL sections as the backbone, completed by
    the advisory norm's sections (inserted at their modal positions)."""
    off = list((official or {}).get("sections") or [])
    adv = list(norm.get("sections") or [])
    if not off:
        return [s["title"] for s in adv] or ["Abstract", "Introduction", "Methods", "Results",
                                             "Discussion"]

    def key(title):
        words = re.findall(r"[a-z0-9]+", str(title).lower())
        return " ".join(w[:-1] if len(w) > 3 and w.endswith("s") else w for w in words)

    merged = [s["title"] for s in off]
    # The insert position must be found in the list that GROWS, never in `off`:
    # once one advisory section was inserted, index `i` of `off` no longer names
    # the same slot of `merged`, so a later advisory section landed BEFORE its
    # predecessor (Ethics 0.5, Data availability 0.6 -> the 0.6 section came
    # first). `merged_pos` carries each merged slot's mean_position in parallel.
    merged_pos = [float(o.get("mean_position", 99)) for o in off]
    seen = {key(t) for t in merged}
    word_sets = [set(key(t).split()) for t in merged]
    for a in adv:
        title = a["title"]
        k = key(title)
        if k in seen:
            continue
        if len(k.split()) == 1 and any(k in ws for ws in word_sets):
            # A one-word variant ("Methods", "Conclusion") is folded into the
            # fuller heading already present.
            continue
        idx = len(merged)
        for i, pos in enumerate(merged_pos):
            if float(a.get("mean_position", 99)) <= pos:
                idx = i
                break
        merged.insert(idx, title)
        merged_pos.insert(idx, float(a.get("mean_position", 99)))
        seen.add(k)
        word_sets.append(set(k.split()))
    return merged


def _skeleton_statements(norm: dict, official: dict = None) -> list:
    off = official or {}
    if off.get("statement_sections"):
        # The template's OWN wording for the declaration blocks wins over the
        # canonical labels.
        return list(off["statement_sections"])
    if off.get("statements"):
        return [s["label"] for s in off["statements"]]
    return [s["label"] for s in (norm.get("statements") or [])]


def render_word_template(venue_id: str, norm: dict, official: dict = None) -> str:
    """A Word-oriented skeleton: heading levels + statement placeholders."""
    off = official or {}
    titles = _skeleton_titles(norm, off)
    mandatory = {m.lower() for m in (off.get("mandatory_sections") or [])}
    L = [f"<!-- Word template skeleton for venue '{venue_id}'. Structure only; replace every "
         f"placeholder. Word styles: use Heading 1 for the title, Heading 2 for top-level "
         f"sections and Heading 3 for subsections, so the generated .docx carries a navigable "
         f"outline."
         + (" The sections marked [MANDATORY] come from the journal's OWN template: they must "
            "exist. Use the styles the journal's .dotx/.docx template provides."
            if off.get("sections") else "")
         + " -->", "",
         "# <Manuscript title>", ""]
    statement_labels = _skeleton_statements(norm, off)
    for title in titles:
        mark = " [MANDATORY]" if title.strip().lower() in mandatory else ""
        if title.strip().lower() in ("abstract",):
            L += [f"## Abstract{mark}", "", "<Abstract: one paragraph, no citations.>", ""]
            continue
        L += [f"## {title}{mark}", "", f"<{title} text.>", ""]
    for label in statement_labels:
        L += [f"## {label}", "", f"<{label} statement.>", ""]
    L += ["<!-- End of template. The section list follows the journal's OWN template when one "
          "is present (otherwise the venue's modal order); adjust only where the manuscript's "
          "content or the venue's guidelines require it. -->"]
    return "\n".join(L)


def render_latex_template(venue_id: str, norm: dict, official: dict = None) -> str:
    """A LaTeX skeleton: the journal's class/section order when one is known."""
    off = official or {}
    titles = _skeleton_titles(norm, off)
    statement_labels = _skeleton_statements(norm, off)
    docclass = str(off.get("documentclass") or "").strip()
    L = ["% LaTeX template skeleton for venue '" + venue_id + "'.",
         "% Structure only: replace the placeholders with the manuscript's own content."]
    if docclass:
        L += [f"% The journal's OWN template uses \\documentclass{{{docclass}}}; keep it (and "
              f"the class file the template ships).",
              f"\\documentclass{{{docclass}}}"]
    else:
        L += ["% No official class file was found: use the journal's template class here.",
              "\\documentclass[11pt]{article}"]
    L += ["\\usepackage[utf8]{inputenc}",
          "\\usepackage{graphicx}",
          "\\usepackage{amsmath}",
          "",
          "\\title{<Manuscript title>}",
          "\\author{<Authors>}",
          "\\date{}",
          "",
          "\\begin{document}",
          "\\maketitle",
          ""]
    for title in titles:
        low = title.strip().lower()
        if low == "abstract":
            L += ["\\begin{abstract}", "<Abstract: one paragraph, no citations.>", "\\end{abstract}",
                  ""]
            continue
        L += [f"\\section{{{title}}}", f"% <{title} text.>", ""]
    for label in statement_labels:
        L += [f"\\section*{{{label}}}", f"% <{label} statement.>", ""]
    L += ["\\end{document}"]
    return "\n".join(L)


def build_venue_templates(venue_id, root=None, profiles_dir=None, exemplar_dir=None,
                          official_dir=None) -> dict:
    """Generate the pinned structure-only pack for one venue.

    Inputs: the venue's OFFICIAL template files
    (`<venue-id>.official/`, AUTHORITATIVE) and/or the exemplar manuscripts
    (`<venue-id>.manuscripts/`, ADVISORY). Deterministic (no timestamps): the
    same inputs produce byte-identical files, and MANIFEST.json pins every input
    and output by sha256, plus the downloaders' source provenance, so a run that
    embedded the summary can be reproduced and audited.
    """
    vid = str(venue_id or "").strip().lower()
    if not vid:
        die("build-venue-templates needs a venue id")
    src_dirs = []
    if exemplar_dir:
        src_dirs = [Path(exemplar_dir)]
    else:
        if profiles_dir:
            local = Path(profiles_dir) / f"{vid}{VENUE_EXEMPLAR_SUFFIX}"
            if local.is_dir():
                src_dirs.append(local)
        src_dirs.extend(d for d in venue_exemplar_dirs(vid, root) if d not in src_dirs)
    write_dir = (Path(profiles_dir) if profiles_dir
                 else (src_dirs[0].parent if src_dirs else venue_profiles_write_dir(root)))
    off_dirs = ([Path(official_dir)] if official_dir
                else venue_official_dirs(vid, root, profiles_dir))
    files = []
    for d in src_dirs:
        files.extend(_exemplar_files(d))
    records, skipped = [], []
    for p in files:
        rec = extract_manuscript_structure(p)
        if rec.get("skipped"):
            skipped.append({"file": p.name, "why": rec["skipped"]})
        else:
            records.append(rec)
    off_files = []
    off_archives = []
    for d in off_dirs:
        off_files.extend(_exemplar_files(d))
        off_archives.extend(p for p in sorted(d.rglob("*.zip")) if p.is_file())
    off_records, off_skipped = [], []
    for p in off_files:
        if p.suffix.lower() in VENUE_EXEMPLAR_DOCX_SUFFIXES \
                and docx_document_role(p.name) == "cover":
            # A cover-letter template is a deliverable, not a manuscript
            # skeleton: parsing its salutation/recipient lines as "mandatory
            # sections" would corrupt the venue's requirements.
            off_skipped.append({"file": p.name,
                                "why": "cover-letter template (not a manuscript skeleton)"})
            continue
        rec = extract_official_template(p)
        if rec.get("skipped"):
            off_skipped.append({"file": p.name, "why": rec["skipped"]})
        else:
            off_records.append(rec)
    explicit = None
    for d in off_dirs:
        p = d / VENUE_OFFICIAL_REQUIREMENTS
        if p.is_file():
            try:
                explicit = json.loads(p.read_text(encoding="utf-8"))
            except (OSError, ValueError):
                explicit = None
            break
    if not records and not off_records:
        looked = [str(d) for d in src_dirs + off_dirs]
        return {"venue": vid, "exemplars": 0, "official": 0, "skipped": skipped + off_skipped,
                "written": [], "looked": looked,
                "note": "no readable official template and no readable exemplar manuscripts "
                        "were found"
                        + (f" under {', '.join(looked)}" if looked else "")}
    norm = structure_norm(records)
    official = official_skeleton(off_records, explicit)
    out_dir = write_dir
    pack = out_dir / f"{vid}{VENUE_TEMPLATE_SUFFIX}"
    pack.mkdir(parents=True, exist_ok=True)
    payload = {
        VENUE_STRUCTURE_FILE: json.dumps({"venue": vid, "official": official, "norm": norm},
                                         indent=2,
                                         sort_keys=True) + "\n",
        VENUE_NORM_FILE: render_architecture_summary(vid, norm, official) + "\n",
        VENUE_WORD_TEMPLATE: render_word_template(vid, norm, official) + "\n",
        VENUE_LATEX_TEMPLATE: render_latex_template(vid, norm, official) + "\n",
    }
    manifest = {"venue": vid, "pipeline_version": VERSION,
                "generated_from": [{"file": r["file"], "sha256": r["sha256"],
                                    "format": r.get("format")} for r in records],
                "official_files": [{"file": r["file"], "sha256": r["sha256"],
                                    "format": r.get("format")} for r in off_records],
                "skipped": skipped + off_skipped,
                "files": {}}
    # The downloader's own provenance (source URL/DOI/license/retrieval date per
    # article) travels into the pack's manifest, so the norm can be audited back
    # to the exact public sources it was derived from.
    prov = None
    for d in src_dirs:
        p = d / "manifest.json"
        if p.is_file():
            try:
                prov = json.loads(p.read_text(encoding="utf-8"))
            except (OSError, ValueError):
                prov = None
            break
    if prov is not None:
        manifest["sources"] = prov
    for d in off_dirs:
        p = d / "manifest.json"
        if p.is_file():
            try:
                manifest["official_sources"] = json.loads(p.read_text(encoding="utf-8"))
            except (OSError, ValueError):
                pass
            break
    for name, text in payload.items():
        p = pack / name
        write_text_atomic(p, text)
        manifest["files"][name] = sha256_file(p)
    write_json_atomic(pack / VENUE_PACK_MANIFEST, manifest)
    return {"venue": vid, "exemplars": len(records), "official": len(off_records),
            "official_archives": [p.name for p in off_archives],
            "skipped": skipped + off_skipped,
            "pack": str(pack), "files": sorted(payload) + [VENUE_PACK_MANIFEST],
            "norm_sections": _skeleton_titles(norm, official),
            "mandatory_sections": official.get("mandatory_sections") or [],
            "documentclass": official.get("documentclass") or "",
            "written": sorted(payload)}


VENUE_NORM_RULES = """\
=== VENUE TEMPLATE / STRUCTURE (read together with the venue profile) ===

The excerpt below was derived by CODE (structure only: section order, the class file, abstract
and statement placement; no prose was copied). Two tiers, with different authority:

  * **The OFFICIAL journal template is AUTHORITATIVE.** When the excerpt names one: use the
    journal's own template/class and its styles, keep every MANDATORY section it lists, keep the
    declaration blocks it provides (use its own wording for them), and do not invent a section
    order that contradicts it. A requirement the template demands but the manuscript cannot
    supply (e.g. an ethics statement that does not apply) becomes a precise MANUAL item for the
    author -- never invented text. The venue's author guidelines (the profile) still come first
    where they state a number or a rule the template does not.
  * **The recent-practice part is ADVISORY.** It fills what the official template leaves open
    (e.g. how the body is usually organised). Follow it only where it serves the content; never
    add empty sections to match it, and never let it override the official template.

  * NEVER copy sentences, headings' phrasing or paragraph text from any published article or
    from a template's sample manuscript: structure and boilerplate declarations only, and the
    manuscript's prose must be its authors' own.
  * Neither tier is a gate or a score by itself: the code-side conformance rows in
    `work/OFFICIAL_TEMPLATE.md` are evidence for the review's J5/M20 disposition, and no
    finding may rest on a descriptive deviation alone. A missing MANDATORY section or a wrong
    class file is a real conformance finding; a deviation from the ADVISORY part is recorded
    under J5 with one sentence and is allowed.
  * ARCHITECTURE AND FORMATTING FOLLOW THE TEMPLATE when the venue ships one: the
    section/subsection set and their ORDER, the declaration blocks, the figure/table labels and
    their order, and the fonts, paragraph spacing, indentation and heading styles all come from
    the template's own file. A read-only copy is staged in `venue_template/` and every produced
    manuscript / supplementary .docx is restyled into the template's styles by the code-side
    normalizer before the postcheck -- keep those styles and never re-copy the previous
    venue's. (The cover letter is the exception: see the next bullet.)
  * THE COVER LETTER IS NOT A MANUSCRIPT DOCUMENT: the manuscript template's front matter and
    styles cover the manuscript. When the venue ships its own cover-letter template the letter is
    built in that file; when it ships none, the letter follows the journal's own cover-letter /
    scope-statement guidance (the profile records the source) and then established academic
    convention for a submission letter (recipient block, date, salutation, body, closing and
    signature) -- the manuscript template is NEVER applied to it, and its styles are never
    demanded of it.
  * THE FIRST PAGE, THE TYPE SCALE AND THE HEADING DEPTH COME FROM THE TEMPLATE: use its title
    style (as centered as the template renders it), its author-list/front-matter style (as bold
    as the template renders it), the affiliation/correspondence block it carries, ONE
    "Keywords: ..." line and the template's UNNUMBERED abstract front matter; section numbering
    starts with the first body section. Do not create heading levels deeper than the template's
    own document uses (never a sub-sub-section such as 2.2.1 when the template stops at 2.2).
    The template's first-page header (logo) and its page-number footer are part of the
    deliverable, not decoration.
  * THE FIRST-PAGE BLOCK IS THE TEMPLATE'S OWN, IN ITS ORDER AND SPACING: one title line, ONE
    author-list line, the affiliation lines the template spaces with before=240/after=0, then ONE
    correspondence block -- the BOLD label "* Correspondence:" followed by a line break, the
    corresponding author ("<Name>, lead contact" when the source marks a lead contact or a
    corresponding author), another line break and the email -- then ONE "Keywords: ..." line and
    the unnumbered "Abstract" heading with its paragraph. Fold a separate "Lead contact" /
    "Corresponding author" line into that block instead of leaving it as its own paragraph, and
    never keep the old publisher's "Highlights"/"Summary"/"Motivation" containers.
  * STYLE AND ARCHITECTURE FALL BACK IN LEVELS -- move to the NEXT level only for what the
    current level leaves UNSPECIFIED: (1) the TEMPLATE files above are the first authority;
    (2) anything they do not pin follows the journal's/venue's OFFICIAL GUIDELINES on its own
    website (the run's profile records the source it was built from -- see the pack's
    `sources`/`guidelines_source` -- and the prompt's guideline note); (3) anything still
    unstated at that level follows ESTABLISHED ACADEMIC CONVENTION -- e.g. table text one step
    smaller than the body text, single-spaced inside the table, the caption in the body font at
    body size, a table that breaks across pages repeating its header row. Record which level
    each such choice came from in the package's report. Never invent a requirement no level
    states, never let level (1) override level (2) for something the template leaves open, and
    never leave a style unset.
  * CONTAINER HEADINGS THAT BELONG TO ANOTHER PUBLISHER'S TEMPLATE (for example "Lead contact",
    "Resource availability", "Materials availability", "Method details", or a bare "Key
    resources" heading) are not part of this venue's structure: fold their content into the
    template's own sections (Methods subsections, Statements, or the tables/figures area) and
    place each table caption immediately before its table.
@@TRANSFER@@

@@NORM@@
"""

VENUE_TRANSFER_RULES = """
  * **TRANSFER MODE (new journal, no response letter):** the target venue's official template
    REPLACES the previous venue's. Treat the old class file/styles, old section names, old
    declaration wording, old reference style and old figure/supplementary conventions as
    findings to remove, and verify the new venue's mandatory sections and statements exist.
    Answer the review concerns from `human_review_feedback/` (and from
    `llm_review_feedback/` when the corpus carries the pre-filtered LLM review) where they still
    apply; never depend on a response letter. The human area's child `original_submission/`,
    when present, is the manuscript version those reviewers actually saw -- evidence for
    understanding a concern, never the current submission and never a source of text to copy.
    Every remaining LLM-review finding is a real concern (its false positives were filtered out
    upstream), never noise to dismiss."""


def venue_norm_block(venue_id, root=None, transfer: bool = False) -> str:
    """The template/norm prompt block for one venue, or "" when it has no pack."""
    pack = venue_pack_dir(venue_id, root)
    if pack is None:
        return ""
    try:
        summary = (pack / VENUE_NORM_FILE).read_text(encoding="utf-8").strip()
    except OSError:
        return ""
    digest = sha256_file(pack / VENUE_NORM_FILE)
    text = (VENUE_NORM_RULES.replace("@@NORM@@", summary)
            .replace("@@TRANSFER@@", VENUE_TRANSFER_RULES if transfer else ""))
    files = official_template_files(venue_id, root) if venue_templates_enabled() else {}
    word = files.get("word") or {}
    latex = files.get("latex") or {}
    if word or latex:
        lines = ["", "TEMPLATE FILES FOR THIS RUN (the producing/reviewing sandboxes carry a "
                     "read-only `venue_template/` copy of the venue's own files, and their render "
                     "-- when this machine could make one -- is staged for the visual pass under "
                     "`visual_template/`):",
                     "  * READ THE TEMPLATE FILES YOURSELF -- they are this run's authority for "
                     "architecture and formatting, whatever your role: the REVIEW and the AUDIT "
                     "dispose every template-conformance row (OFFICIAL_TEMPLATE.md) against "
                     "these files and never invent a rule they do not state; the REWRITE, "
                     "REVISE and INTEGRATE agents keep the template's styles, numbering, "
                     "bullets/indentation and furniture while they edit content; the JUDGE "
                     "compares the package's own render with `visual_template/` side by side "
                     "(title page, running head/logo, footers, heading depth, caption placement) "
                     "in its visual record. Every decision must be checkable against these "
                     "files: a claim about a \"journal rule\" that neither the template nor the "
                     "venue's official guidelines states is a defect of the claim."]
        if word.get("main"):
            lines.append(f"  * Word (.docx): venue_template/word/{Path(word['main']).name}"
                         + (f"; supplementary: venue_template/word/"
                            f"{Path(word['supplementary']).name}" if word.get("supplementary")
                            else "")
                         + (f"; cover letter: venue_template/word/"
                            f"{Path(word['cover']).name}" if word.get("cover") else ""))
        lines.append(
            "  * THE MANUSCRIPT TEMPLATES DO NOT COVER THE COVER LETTER. When the "
            "venue ships a cover-letter template it is restyled into it; otherwise the "
            "letter follows the journal's own cover-letter / scope-statement guidance "
            "(the profile records it) and then established academic convention for a "
            "submission letter -- never the manuscript template's Title/Author/Abstract "
            "front matter.")
        if latex.get("sample"):
            lines.append(f"  * LaTeX: venue_template/latex/{Path(latex['sample']).name}"
                         + ("; class: " + ", ".join(Path(p).name for p in latex.get("cls") or [])
                            if latex.get("cls") else "")
                         + ("; bibliography style: "
                            + ", ".join(Path(p).name for p in latex.get("bst") or [])
                            if latex.get("bst") else ""))
        try:
            _prof = load_venue_profile(venue_id, root=root)
            _source = str((_prof.data.get("prompt") or {}).get("guidelines_source") or "").strip()
            _cguide = cover_letter_guidance_clause(cover_letter_guidance(_prof))
        except VenueProfileError:
            _source, _cguide = "", ""
        if _source:
            lines.append(f"  * The venue's official guidance this run records: {_source}")
        if _cguide:
            lines.append(f"  * The cover letter's recorded guideline basis: {_cguide}")
        lines.append("  * Every produced MANUSCRIPT / SUPPLEMENTARY .docx is restyled into its "
                     "Word template's styles and theme by the code-side normalizer before the "
                     "postcheck -- the cover letter is NOT, unless this venue ships a cover-letter "
                     "template. Keep the template's heading styles, statement names, and figure/"
                     "table label order; do not reintroduce the previous venue's styles.")
        if word.get("main"):
            lines.append("  * `visual_template/<role>/` holds the templates' own PDF and page "
                         "images (`manifest.json` names the renderer and each document's page "
                         "count): compare your render side by side with them and name each "
                         "template document and its page count in the visual-inspection record.")
        text += "\n" + "\n".join(lines)
    return text + f"\n\n(pack: {pack} -- {VENUE_NORM_FILE} sha256 {digest[:16]})"


def venue_norm_for(ctx: "Ctx") -> str:
    """The template/structure block for ONE root, with the mode's transfer rules."""
    if getattr(ctx, "root", None) is None:
        return ""                      # a stub/partial context carries no root-local profiles
    return venue_norm_block(venue_id_of(ctx), ctx.root,
                            transfer=(journal_mode_of(ctx) == JOURNAL_MODE_TRANSFER))


def venue_word_templates(ctx: "Ctx") -> dict:
    """The venue's official Word templates: {"main", "supplementary", "cover"}.

    Empty when the venue ships no `.official` Word template; passed to the
    formatter so every produced .docx is restyled into the journal's own
    template instead of merely being described to the agents. A venue that
    ships no cover-letter template simply has no "cover" entry: the normalizer
    then leaves the letter to the guideline/academic-convention chain and never
    applies the manuscript template to it.
    """
    root = getattr(ctx, "root", None)
    if root is None:
        return {}                      # a stub/partial context carries no root-local profiles
    if not venue_templates_enabled():
        return {}                      # operator opt-out (PAPER_VENUE_TEMPLATES=0)
    res = official_template_files(venue_id_of(ctx), root)
    word = res.get("word") or {}
    out = {}
    for key in ("main", "supplementary", "cover"):
        if word.get(key):
            out[key] = Path(word[key])
    return out


def _ctx_cfg(ctx) -> dict:
    cfg = getattr(ctx, "cfg", None)
    return cfg if isinstance(cfg, dict) else {}


def venue_containers(ctx: "Ctx") -> tuple:
    """The foreign-publisher block headings THIS venue declares (may be empty).

    A profile lists the other publisher's blocks its own submission must not
    keep ("Lead contact", "Key resources", ...). The formatter stays agnostic:
    it only ever sees this tuple, and a venue that declares none gets no
    container rule at all.
    """
    prof = venue_profile_of(ctx, required=False)
    if prof is None:
        return ()
    return tuple(str(c) for c in (prof.data.get("foreign_container_headings") or ()) if str(c))


def venue_id_of(ctx=None) -> str:
    """The venue id a root (or a config dict) records, or the default venue."""
    cfg = _ctx_cfg(ctx)
    vid = str(cfg.get("venue") or "").strip().lower()
    return vid or DEFAULT_VENUE


# The display-rule inheritance (`_snapshot_profile`) reads the venue's profile
# file when a snapshot predates the `tables`/`figures` fields. That lookup runs
# ONCE per (root, venue, missing fields) per process: `format_policy_of` is on
# every scan and every stage postcheck, and re-reading + re-parsing the profile
# JSON on each call measurably slowed whole rounds down. A profile file edited
# in the MIDDLE of one command is therefore not picked up by an already-cached
# lookup -- re-run the command, as with every other recorded-rule change.
_DISPLAY_RULE_INHERIT_CACHE: dict = {}


def _inherited_display_rules(venue_id: str, root, missing: tuple) -> dict:
    """The shipped profile's display rules a pre-schema snapshot may inherit."""
    key = (str(root), venue_id, missing)
    if key in _DISPLAY_RULE_INHERIT_CACHE:
        return _DISPLAY_RULE_INHERIT_CACHE[key]
    inherited: dict = {}
    try:
        fresh = load_venue_profile(venue_id, root=root)
    except VenueProfileError:
        fresh = None          # no readable file: the snapshot keeps running rule-free
    if fresh is not None:
        if "tables" in missing and fresh.declares_table_rule:
            inherited["tables"] = copy.deepcopy(fresh.tables)
        if "figures" in missing and fresh.declares_figure_rule:
            inherited["figures"] = copy.deepcopy(fresh.figures)
        # The reference-entry preference, the numbering convention and the
        # leftover-phrase list are the same kind of field: they did not exist
        # when a pre-2026-10-09 snapshot was recorded, and a root that carries
        # none of them would scan with fewer rules than the postcheck does.
        # Inherit each one ONLY when the snapshot does not carry its key.
        if "references" in missing and (fresh.data.get("references") or {}):
            inherited["references"] = copy.deepcopy(fresh.data["references"])
        if "numbering" in missing and str(fresh.data.get("numbering") or ""):
            inherited["numbering"] = str(fresh.data["numbering"])
        if "leftover_phrases" in missing and (fresh.data.get("leftover_phrases") or ()):
            inherited["leftover_phrases"] = copy.deepcopy(
                list(fresh.data["leftover_phrases"]))
    _DISPLAY_RULE_INHERIT_CACHE[key] = inherited
    return inherited


def _snapshot_profile(cfg: dict, venue_id: str, root=None):
    """The profile snapshot recorded in the config, when it matches the id.

    A snapshot recorded BEFORE the `tables`/`figures` schema existed carries no
    display rule at all, and the recorded snapshot normally wins over the files
    on disk. That would leave a root created earlier with no rule forever, so
    those fields -- and only those -- are inherited from the venue's own profile
    file, each one only when the snapshot does not carry its key at all (a
    snapshot that carries an explicit block, including an empty one, is
    authoritative, and re-recording with `set-venue` keeps working as before).
    """
    snapshot = cfg.get("venue_profile")
    if not isinstance(snapshot, dict):
        return None
    missing = tuple(k for k in ("tables", "figures", "references", "numbering",
                                "leftover_phrases") if k not in snapshot)
    if missing:
        inherited = _inherited_display_rules(venue_id, root, missing)
        if inherited:
            snapshot = dict(snapshot)
            snapshot.update(inherited)
    try:
        prof = VenueProfile(snapshot, origin="recorded snapshot")
    except VenueProfileError:
        return None
    return prof if prof.id == venue_id else None


def venue_profile_of(ctx=None, required: bool = True):
    """The root's venue profile.

    The snapshot recorded at setup/set-venue time WINS over the files on disk:
    a root keeps enforcing the rules it was configured with even if the shipped
    profiles are edited or the profile file is deleted later. With `required`
    false the caller gets None instead of an exception, which is what `status`
    needs to report a broken configuration.

    The ARTICLE TYPE the root records is applied on top: the same venue with
    `set-article-type brief-communication` reads the Brief Communication limits,
    not the Article ones. A root that records none keeps the profile's default
    type (the pre-article-type behaviour).
    """
    cfg = _ctx_cfg(ctx)
    venue_id = venue_id_of(ctx)
    root = getattr(ctx, "root", None)
    prof = _snapshot_profile(cfg, venue_id, root=root)
    if prof is None:
        try:
            prof = load_venue_profile(venue_id, root=root)
        except VenueProfileError:
            if required:
                raise
            return None
    wanted = str(cfg.get("article_type") or "").strip().lower()
    if not wanted or wanted == prof.article_type_id:
        return prof
    try:
        return prof.with_article_type(wanted)
    except VenueProfileError:
        if required:
            raise
        return None


def article_type_of(ctx=None) -> str:
    """The article-type id a root selects, or the profile's default."""
    prof = venue_profile_of(ctx, required=False)
    if prof is not None:
        return prof.article_type_id
    return str(_ctx_cfg(ctx).get("article_type") or "").strip().lower()


def journal_of(ctx=None) -> str:
    """The configured journal: the config's, else the profile's default, else ""."""
    cfg = _ctx_cfg(ctx)
    name = str(cfg.get("journal") or "").strip()
    if name:
        return name
    prof = venue_profile_of(ctx, required=False)
    return prof.default_journal if prof is not None else ""


def venue_summary(ctx) -> str:
    """One line naming the venue, the journal and where the profile came from."""
    prof = venue_profile_of(ctx, required=False)
    venue = venue_id_of(ctx)
    journal = journal_of(ctx) or "(not set)"
    if prof is None:
        return (f"venue={venue or '(missing)'} (UNRESOLVED), "
                f"journal={journal}")
    return (f"venue={prof.id} (\"{prof.label}\", {prof.describe_origin()}), "
            f"article type={prof.article_type} (`{prof.article_type_id}`), "
            f"journal={journal}")


def venue_status_lines(ctx) -> list:
    """The venue/journal lines `status`, `setup` and the decision report print."""
    prof = venue_profile_of(ctx, required=False)
    venue = venue_id_of(ctx)
    journal = journal_of(ctx)
    lines = []
    if prof is None:
        lines.append(f"venue:         {venue or '(missing)'}  -- UNRESOLVED "
                     f"(run `set-venue <id>`; `set-venue --list` shows the ids)")
    else:
        lines.append(f"venue:         {prof.id} (\"{prof.label}\", {prof.describe_origin()})")
        lines.append(f"article type:  {prof.article_type} (`{prof.article_type_id}`"
                     + ("" if prof.carries_article_numbers()
                        else "; the profile carries no word limits for it, so the stages "
                             "count and name the venue's own numbers")
                     + ")")
        limits = prof.length_limits()
        if limits["abstract"].get("cap") is None and limits["main text"].get("cap") is None:
            lines.append("limits (M19):  no abstract/main-text cap in this venue profile "
                         "(counts are recorded; the target journal's own guidelines are the bar)")
        else:
            lines.append(f"limits (M19):  abstract <= {limits['abstract'].get('cap')}, "
                         f"main text <= {limits['main text'].get('cap')} "
                         f"({prof.length_limits_source})")
        for key, label, rules in (("tables", "tables", "FMT-TB"), ("figures", "figures",
                                                                   "FMT-FG")):
            block = prof.data.get(key) or {}
            if not _declares_display_rule(block):
                lines.append(f"{label} ({rules}): this venue profile declares no {label} rule "
                             f"(counts are reported; no placement/caption is gated)")
                continue
            bits = []
            if block.get("placement") == "end":
                bits.append(f"{label}: together at the end of the manuscript")
            elif block.get("placement") == "inline":
                bits.append(f"{label}: in the body, where cited")
            if block.get("caption") in ("before", "after"):
                bits.append(f"caption {block['caption']} the {label[:-1]}")
            elif block.get("caption") == "any":
                bits.append(f"caption side not pinned ({label[:-1]})")
            n_special = len(block.get("special") or [])
            if n_special:
                bits.append(f"{n_special} special {label[:-1]}(s) this venue exempts")
            if not bits:
                bits.append("no placement/caption pinned")
            lines.append(f"{label} ({rules}): " + "; ".join(bits)
                         + f"  ({block.get('source') or 'venue profile'})")
    missing = 'not set -- the prompts say "the target journal"; run `set-journal <name>`'
    lines.append(f"journal:       {journal or '(' + missing + ')'}")
    return lines


def venue_block(ctx) -> dict:
    """The venue/journal block decision.json and the report carry."""
    prof = venue_profile_of(ctx, required=False)
    return {"venue": venue_id_of(ctx),
            "journal": journal_of(ctx),
            "article_type": (prof.article_type if prof is not None else None),
            "article_type_id": (prof.article_type_id if prof is not None else None),
            "article_carries_numbers": (prof.carries_article_numbers()
                                        if prof is not None else None),
            "label": prof.label if prof is not None else None,
            "origin": prof.describe_origin() if prof is not None else None,
            "length_limits": prof.length_limits() if prof is not None else None,
            "caption_limit": caption_limit_of(ctx),
            "notes": list(getattr(ctx, "venue_notes", []) or []),
            "problems": list(getattr(ctx, "venue_problems", []) or []),
            "profile": prof.to_dict() if prof is not None else None}


def venue_config_findings(ctx) -> tuple:
    """(notes, problems) for a root's venue/journal configuration.

    Notes are informational and always printed; problems are fatal only under
    `--strict-venue`, except for an unresolvable venue, which the commands that
    must render a prompt refuse outright (see venue_profile_of).
    """
    notes, problems = [], []
    cfg = _ctx_cfg(ctx)
    recorded = str(cfg.get("venue") or "").strip().lower()
    if not recorded:
        notes.append(f"no venue recorded in {Path(getattr(ctx, 'cfg_path', 'pipeline_config.json')).name}: "
                     f"using the default venue {DEFAULT_VENUE!r} (the pipeline's pre-venue "
                     f"behaviour). Run `set-venue <venue>` to make it explicit.")
    prof = venue_profile_of(ctx, required=False)
    if prof is None:
        # Distinguish "no profile by that name" from "the file is there but it
        # cannot be used": the operator's next step is different.
        try:
            venue_profile_of(ctx, required=True)
        except VenueProfileError as e:
            if e.unknown:
                problems.append(unknown_venue_message(recorded or DEFAULT_VENUE,
                                                      getattr(ctx, "root", None)))
            else:
                problems.append(f"the venue profile selected by this root cannot be used: {e}\n"
                                f"       Fix the file, or select another venue with "
                                f"`set-venue <id>` (`set-venue --list` shows the ids).")
        else:                           # pragma: no cover -- prof is None above
            problems.append(unknown_venue_message(recorded or DEFAULT_VENUE,
                                                  getattr(ctx, "root", None)))
        return notes, problems
    snapshot = cfg.get("venue_profile")
    if isinstance(snapshot, dict) and str(snapshot.get("id") or "").strip().lower() != prof.id:
        problems.append(f"the recorded profile snapshot names venue "
                        f"{str(snapshot.get('id'))!r} but the config selects {prof.id!r}; "
                        f"re-run `set-venue {prof.id}` to re-record it.")
    # ---- the article type ------------------------------------------------
    recorded_type = str(cfg.get("article_type") or "").strip().lower()
    type_ids = prof.article_type_ids()
    if not recorded_type:
        notes.append(f"no article type recorded: using the venue profile's default type "
                     f"{prof.article_type!r} (`{prof.article_type_id}`). Run "
                     f"`set-article-type <id>` to make it explicit.")
    elif recorded_type not in type_ids:
        problems.append(f"unknown article type {recorded_type!r} for venue {prof.id!r}: the "
                        f"profile carries {', '.join(type_ids)}. Run "
                        f"`set-article-type <id>` (`set-article-type --list` shows the "
                        f"labels).")
    else:
        if not prof.carries_article_numbers(recorded_type):
            notes.append(f"the venue profile carries no word limits for the "
                         f"{prof._type_entry(recorded_type)['label']!r} type: every stage "
                         f"counts and names the venue's own numbers instead of borrowing "
                         f"another type's caps.")
    journal = str(cfg.get("journal") or "").strip()
    if not journal:
        journal = prof.default_journal
    if not journal:
        problems.append("no journal configured: the prompts say \"the target journal\" and the "
                        "venue's rule set still applies. Run `set-journal <name>` to name it.")
    elif not prof.journal_matches(journal):
        known = ", ".join(prof.known_journals()) or "no names, but a pattern is declared"
        problems.append(f"the journal {journal!r} is not one of the journals venue profile "
                        f"{prof.id!r} describes ({known}). Set the venue that matches the journal "
                        f"(`set-venue <id>`) or the journal the venue describes "
                        f"(`set-journal <name>`).")
    state_cfg = ((getattr(ctx, "state", None) or {}).get("config") or {})
    mirrored = str(state_cfg.get("venue") or "").strip().lower()
    if mirrored and mirrored != recorded:
        notes.append(f"state.json records venue {mirrored!r} but pipeline_config.json selects "
                     f"{recorded!r}: the config file wins (`set-venue` re-mirrors it).")
    return notes, problems

AGENT_PRESETS = {
    "claude": ["claude", "--permission-mode", "bypassPermissions", "--print"],
    # `codex exec -` is only the BASE argv: resolve_agent_cmd() splices the MCP
    # approval overrides of codex_mcp_overrides() in after the subcommand,
    # because an MCP tool call the operator is never asked about is denied
    # outright in a non-interactive session (see MCP_APPROVALS).
    "codex": ["codex", "exec", "-"],
    # The cross-judge conflict audit is a small, bounded task: its default
    # backend is the same CLI at the cheapest reasoning effort, so the audit is
    # lightweight without needing a second model configuration.
    "codex-lite": ["codex", "exec", "-c", 'model_reasoning_effort="low"', "-"],
    # The DeepSeek Harness CLI (`dsh`): `headless` is its one-shot driver, so a
    # session is non-interactive and the stage ends with the process. The task
    # is read from stdin (`-`, the delivery codex gets; `dsh` also accepts the
    # task as a positional, but PROMPT.md is far too large for argv), and
    # `--json` replaces the printed final message with a newline-delimited
    # event stream whose opening `session` line carries the persisted session
    # id a continuation adopts (`--session-id`, see resume_argv_for). The
    # harness's own home ($DSH_HOME, default ~/.dsh) owns the model, the
    # DEEPSEEK_API_KEY credential and its MCP servers, exactly as the codex
    # profile owns the codex CLI's, so this preset carries no overrides the way
    # the codex one does.
    "deepseek": ["dsh", "--profile", "headless", "--json", "-"],
}
# The backends an operator may select BY NAME (each maps to a shipped argv;
# `manual` is the no-CLI mode) -- one list, so every --agent/--judge-agent
# parser accepts the same set. A custom `--agent-cmd`/PAPER_AGENT_CMD stays the
# last route and is never named here.
AGENT_CHOICES = ("codex", "claude", "deepseek", "manual")
# The CLI each preset launches (`codex`, `claude`, `dsh`). Derived from the
# preset table itself, so the checks that ask "is this the operator's real
# agent CLI, or a test stub / foreign tool?" (see `_looks_like_preset_cmd`) and
# that ask "was this preset's binary not installed?" (see `agent_install_hint`)
# recognise a preset added above without a second list to keep in step.
AGENT_PRESET_BINARIES = frozenset(os.path.basename(str(argv[0])).lower()
                                  for argv in AGENT_PRESETS.values() if argv)
# Choices for --conflict-agent (the audit is lightweight by default).
CONFLICT_AGENT_CHOICES = ("codex-lite", *AGENT_CHOICES)

MARKER_FILE = "_pipeline_done.json"
SCORES_FILE = "scores.json"
PROMPT_FILE = "PROMPT.md"
PIN_DIRNAME = "pinned"
LOCK_FILE = "_pipeline.lock"
LOGS_DIRNAME = "_logs"
# EVERY attempt is kept, not just the last one. The run record's `postcheck`
# and `last_error` always describe the FINAL attempt (a retry overwrites them),
# so a run that failed twice used to leave the operator with one failure and no
# way back to the first one's diagnostics or artifacts -- the 2026-09-22 root
# showed "attempt 2" failing on the M1b gate while attempt 1's real problems
# (101 OUTLINE rows with no summary) existed only inside attempt 2's PROMPT.md.
# `attempts_log` in state.json is the machine-readable history;
# `runs/<run>_try<N>_failed/` keeps that attempt's own sandbox (renamed before the
# retry builds a fresh one -- deliverables, transcript and a record.json).
# A failed attempt's WHOLE sandbox is renamed to `runs/<run>_try<N>_failed/` before
# the retry builds a fresh one at `runs/<run>/` -- the operator asked for exactly
# that shape, and it keeps everything (deliverables as the postcheck judged them,
# the transcript, the seeded tables, the corpus copies and a record.json) without
# a second copy of the artifacts.
FAILED_SUFFIX_FMT = "_try{n}_failed"
# A pathological retry loop must not grow state.json without bound: the log keeps
# the last N attempts, each with its messages capped. The archived sandbox keeps
# the full evidence, and `prune` reclaims it with the round it belongs to.
ATTEMPTS_LOG_LIMIT = 25
ATTEMPT_MESSAGE_LIMIT = 4000
# EVERY message of an attempt is kept: the operator asked for the complete
# errors/warnings of the first attempt, the first retry, the second retry, ...
# and a capped list is exactly how attempt 1's two other problems disappeared on
# the 2026-09-22 root. The only guard left is a total BYTES cap per attempt (a
# runaway postcheck could otherwise write megabytes into state.json): when it
# triggers, the note says how many messages were left out, and the attempt's
# archived `record.json`, its transcript and the run log still carry them.
ATTEMPT_LIST_BYTES_LIMIT = 512 * 1024

# ---- the two INPUT areas, under their canonical names -----------------------
# Both were renamed to this repo's snake_case convention, for meaning as much as
# for style:
#   * `non_revised/` is the root's pristine copy of `--source` (the old spelling
#     `non-revised/` reads like a pipeline OUTPUT -- it is not, it is the
#     untouched original);
#   * `raw_data/` is the corpus's raw-data directory: figure/table sources, data
#     tables and the analysis snapshot that the author's own build scripts
#     regenerate (the old spelling `raw_figs/` suggested figures only).
# Only the canonical name is ever CREATED; the legacy spellings stay RESOLVED
# (manifest keys are normalised, so a root or a corpus set up before the rename
# keeps working, and a plain rename of either directory is invisible to every
# hash comparison).
PRISTINE_DIR = "non_revised"
PRISTINE_DIR_LEGACY = "non-revised"
PRISTINE_DIRNAMES = (PRISTINE_DIR, PRISTINE_DIR_LEGACY)
RAW_DATA_DIR = "raw_data"
RAW_DATA_DIR_LEGACY = "raw_figs"
RAW_DATA_DIRNAMES = (RAW_DATA_DIR, RAW_DATA_DIR_LEGACY)
# The human editors'/reviewers' feedback of a REAL submission lives in its own
# top-level area, a sibling of raw_data/: it is the authors' INPUT (never
# submitted, never manuscript text), it drives the concern reconciliation and
# the response letter, and a judge may read it to score how well a version
# ADDRESSES the human-raised concerns. Both areas together are the corpus's
# EVIDENCE areas (see is_evidence_rel / the judge-view layout).
HUMAN_FEEDBACK_DIR = "human_review_feedback"
# A corpus may ALSO carry a machine-generated review of the previous submission
# in its own top-level area (a sibling of human_review_feedback/). It follows
# the SAME evidence contract -- read-only, never submission text, staged into
# the journal feedback/concerns sessions and shown to judges under evidence/ --
# with one semantic difference: its false-positive findings were filtered out
# upstream, so every remaining finding is a real concern the stages must answer
# (never dismissed merely because a model wrote it, and never silently dropped).
LLM_FEEDBACK_DIR = "llm_review_feedback"
REVIEW_FEEDBACK_DIRS = (HUMAN_FEEDBACK_DIR, LLM_FEEDBACK_DIR)
# A corpus may keep the manuscript version the PREVIOUS journal's editors/
# reviewers actually saw inside the feedback area, under this fixed child name.
# It is EVIDENCE, not the current submission: it never feeds feedback discovery,
# sweeps, counts or corpus identity, and the stages may only use it to
# understand what a raised concern refers to and whether the CURRENT base
# already answers it.
ORIGINAL_SUBMISSION_DIRNAME = "original_submission"
EVIDENCE_DIRNAMES = RAW_DATA_DIRNAMES + REVIEW_FEEDBACK_DIRS
# An evidence area the operator renamed to `<area>.disabled` (or `.off`) is
# INERT: it is not read as evidence or feedback and it is not part of the
# submission either -- the rename is the documented off-switch, so its files
# must never leak into the corpus, a judge view or a published package.
DISABLED_EVIDENCE_SUFFIXES = ("disabled", "off")
# The stable root the judge view uses to expose the evidence areas (their files
# stay anonymized inside it; see _view_layout).
EVIDENCE_VIEW_ROOT = "evidence"


def existing_dirname(parent: Path, canonical: str, legacy: str) -> str:
    """`canonical` when it exists (or when neither does), else the legacy name."""
    if (parent / canonical).is_dir() or not (parent / legacy).is_dir():
        return canonical
    return legacy


def pristine_dirname(dirp: Path) -> str:
    """The name `dirp` uses for its pristine copy of the original submission."""
    return existing_dirname(dirp, PRISTINE_DIR, PRISTINE_DIR_LEGACY)


def raw_data_dirname(dirp: Path) -> str:
    """The name `dirp` uses for the corpus's read-only raw-data directory."""
    return existing_dirname(dirp, RAW_DATA_DIR, RAW_DATA_DIR_LEGACY)


def area_dir(sb: Path, area: str) -> Path:
    """The directory a recorded input-area key names inside a sandbox.

    Older records name an area by its legacy spelling (`non-revised/`); a
    sandbox rebuilt since the rename has the canonical one. Resolving both here
    keeps every already-recorded manifest valid.
    """
    if area in PRISTINE_DIRNAMES and not (sb / area).is_dir():
        other = PRISTINE_DIR if area == PRISTINE_DIR_LEGACY else PRISTINE_DIR_LEGACY
        if (sb / other).is_dir():
            return sb / other
    return sb / area


def norm_raw_data_name(rel: str) -> str:
    """A corpus-relative path with the raw-data directory's name canonicalised."""
    return "/".join(RAW_DATA_DIR if part == RAW_DATA_DIR_LEGACY else part
                    for part in rel.replace("\\", "/").split("/"))


def norm_manifest(m: dict) -> dict:
    """A manifest with the renamed input directories canonicalised.

    The two spellings of each input area mean the same directory, so a rename
    must never look like a modification of the corpus.
    """
    files = {norm_raw_data_name(k): v for k, v in (m or {}).get("files", {}).items()}
    return {"files": files, "count": len(files)}


def without_raw_data(m: dict) -> dict:
    """A corpus manifest with the READ-ONLY raw-data area left out.

    Used to compare a published winner with its pin: the raw-data area is an
    INPUT (byte-verified against the pristine copy), not content the stage wrote,
    so a normalised copy of it must not read as "the champion changed".
    """
    files = {k: v for k, v in (m or {}).get("files", {}).items() if not is_evidence_rel(k)}
    return {"files": files, "count": len(files)}


# =====================================================================
# JOURNAL REVISION MODES (options 1-4)
#
# A root can be driven against a REAL journal decision letter instead of the
# pipeline's own from-scratch review. Four modes, one per operator workflow:
#
#   1 transfer  revise for a NEW journal (e.g. read iScience, submit to
#               Frontiers in Immunology). NO response to reviewers. Rewrites
#               allowed (a new journal is a new submission).
#   2 resubmit  revise for a NEW submission to the SAME journal. Response to
#               reviewers REQUIRED. Rewrites allowed.
#   3 major     complete a MAJOR revision at the same journal. Response to
#               reviewers REQUIRED. Rewrites NOT allowed and the manuscript is
#               revised ONLY to address the raised concerns: every change must
#               be traceable to a concern, so the general review-audit-revise
#               workflow does not run.
#   4 minor     as 3, for a MINOR revision.
#
# The default mode is "none" and the historical pipeline is byte-for-byte
# unchanged there: every journal-specific code path below is entered only when
# `journal_mode_of(ctx) != "none"`.
# =====================================================================

JOURNAL_MODE_TRANSFER = "transfer"
JOURNAL_MODE_RESUBMIT = "resubmit"
JOURNAL_MODE_MAJOR = "major"
JOURNAL_MODE_MINOR = "minor"
# The LLM-review mode: the round is revised against the false-positive-filtered
# `llm_review_feedback/` area ONLY (no journal decision letter). It is
# auto-detected from the directory's presence when the config records no
# explicit mode, and the directory can be turned off by renaming it to
# `llm_review_feedback.disabled` (an inert, never-submitted name).
JOURNAL_MODE_LLM = "llm"
JOURNAL_MODE_CONTINUE = "continue"
# The pre-rename spelling of `continue`: kept so existing roots (a config with
# `"revision_mode": "none"`), scripts and `set-revision-mode none` keep working.
JOURNAL_MODE_NONE = "none"
JOURNAL_MODE_INIT = "init"
JOURNAL_MODE_ALIASES = {JOURNAL_MODE_NONE: JOURNAL_MODE_CONTINUE}

JOURNAL_MODES = {
    JOURNAL_MODE_CONTINUE: {
        "option": 0,
        "label": "the pipeline's own review/revise rounds (no journal feedback)",
        "feedback": False, "response": False, "rewrites": True, "scoped": False,
        "streams": (),
    },
    JOURNAL_MODE_INIT: {
        # `init` starts a NEW submission: the conform (template-first) stage runs
        # before round 1 exactly like transfer's, but there is no decision letter
        # anywhere in the chain -- no feedback/concerns stage, no response letter,
        # no journal submission package. Everything after the conform stage is the
        # historical `continue` workflow.
        "option": 0,
        "label": "init: conform the submission first -- inside the venue's own Word template "
                 "when one ships, else to the journal's author guidelines and academic "
                 "convention -- then run the pipeline's own review/revise rounds; no journal "
                 "feedback",
        "feedback": False, "response": False, "rewrites": True, "scoped": False,
        "streams": (),
    },
    JOURNAL_MODE_TRANSFER: {
        "option": 1,
        "label": "transfer: revise for a NEW journal from another journal's feedback; "
                 "no response to reviewers",
        "feedback": True, "response": False, "rewrites": True, "scoped": False,
        "streams": ("human", "llm"),
    },
    JOURNAL_MODE_RESUBMIT: {
        "option": 2,
        "label": "resubmit: revise for a new submission to the SAME journal; "
                 "response to reviewers required",
        "feedback": True, "response": True, "rewrites": True, "scoped": False,
        "streams": ("human", "llm"),
    },
    JOURNAL_MODE_MAJOR: {
        "option": 3,
        "label": "major revision: concern-scoped edits only at the same journal; "
                 "response to reviewers required; no rewrites",
        "feedback": True, "response": True, "rewrites": False, "scoped": True,
        "streams": ("human", "llm"),
    },
    JOURNAL_MODE_MINOR: {
        "option": 4,
        "label": "minor revision: concern-scoped edits only at the same journal; "
                 "response to reviewers required; no rewrites",
        "feedback": True, "response": True, "rewrites": False, "scoped": True,
        "streams": ("human", "llm"),
    },
    JOURNAL_MODE_LLM: {
        "option": 5,
        "label": "llm: revise against the false-positive-filtered LLM review only "
                 "(llm_review_feedback/); no journal decision letter and no response letter",
        "feedback": True, "response": False, "rewrites": True, "scoped": False,
        "streams": ("llm",),
    },
}

JOURNAL_FEEDBACK_NAME_RE = re.compile(
    r"feedback|referee|reviewers?|editors?|editorial|decision[_ \-]*(?:letter|notice|email)",
    re.I)
# ... but the venue's OWN article-type vocabulary collides with those words: the
# shipped example profile's `letter-to-the-editor` and the Frontiers profile's
# `editorial` are MANUSCRIPTS the authors wrote. A name that IS such a type
# (optionally with a version token) is never the journal's feedback, wherever
# it sits -- the same reason a "cover"-spelled letter is carved out below.
ARTICLE_TYPE_MANUSCRIPT_NAME_RE = re.compile(
    r"^(?:letter[\s_-]+(?:to|for)[\s_-]+the[\s_-]+editor|editorial)"
    r"(?:[\s_-]+(?:v|rev|version|revision|draft)?[\s_-]*\d{1,3})?$", re.I)


def is_journal_feedback_name(name) -> bool:
    """Does this file NAME advertise the journal's own feedback/decision letter?

    A name that IS one of the venue article types the authors write
    (`letter-to-the-editor`, `editorial`) is their MANUSCRIPT, never the
    editors' letter, wherever it sits.
    """
    base = str(name or "").replace("\\", "/").rsplit("/", 1)[-1]
    if ARTICLE_TYPE_MANUSCRIPT_NAME_RE.match(Path(base).stem):
        return False
    return bool(JOURNAL_FEEDBACK_NAME_RE.search(base))


# A file the AUTHORS wrote ("response_to_reviewers.docx", "rebuttal.md",
# "point-by-point.docx", or a "cover_letter_to_editor.docx") is a submission
# document, not the journal's feedback: the auto-detection must never read one
# as the letter (the cover letter is the common trap -- "editor" is in its name).
JOURNAL_AUTHORED_REPLY_RE = re.compile(
    r"response|repl(?:y|ies)|rebuttal|point[-_ ]?by[-_ ]?point"
    r"|(?-i:(?:(?<![A-Za-z])|(?<=[a-z])(?=[A-Z]))(?:[Cc]over|COVER)(?![a-z]))", re.I)
# The WORD "cover" (or the camelCase "coverLetter"/"plainLetter"), never the
# substring: a bare `cover` also matched `discovery.md`, `coverage_table.txt`
# and `recovered_notes.tex`, which then read as the letter (or hid a reply whose
# name merely contains the substring). A word starts at the string's start,
# after a non-letter, or at a lower->UPPER camelCase boundary, and ends at a
# non-lowercase character.
_COVER_WORD_RE = re.compile(
    r"(?:(?<![A-Za-z])|(?<=[a-z])(?=[A-Z]))(?:[Cc]over|COVER)(?![a-z])")
# The reply-only spelling for the written-surface scans: a cover letter IS a
# submission document (M19 counts it as one), a response-to-reviewers is not
# manuscript prose.
AUTHORED_REPLY_NAME_RE = re.compile(
    r"response|repl(?:y|ies)|rebuttal|point[-_ ]?by[-_ ]?point", re.I)
JOURNAL_CONCERN_ACTIONS = ("text", "analysis", "new-experiment", "clarification",
                           "formatting", "policy", "disagree")
JOURNAL_CONCERN_DISPOSITIONS = ("to-fix", "already-addressed", "manual", "not-applicable")
JOURNAL_CONCERNS_MD_REL = "concerns/JF_concerns.md"
JOURNAL_CONCERNS_JSON_REL = "concerns/JF_concerns.json"
JOURNAL_RESPONSE_MD_REL = "response/RESPONSE_TO_REVIEWERS.md"
JOURNAL_RESPONSE_MAP_REL = "response/response_map.json"
JOURNAL_SUBMISSION_DIR = "journal_submission"

# The analysis-code area (`code/`) is revision CONTENT, like the documents: a
# stage may revise it (rule C), the judges evaluate it, and a corpus, a pin and
# a winner carry it. It is NOT part of the SUBMISSION by default -- the
# submission copy strips it exactly like the evidence areas, and no
# to-be-submitted file may refer into it. `setup --submit-code on` (or
# `set-submit-code on` on an existing root) submits it instead: the copy then
# carries `code/`, and a response letter may cite a code file like any other.
SUBMIT_CODE_MODES = ("on", "off")
DEFAULT_SUBMIT_CODE = "off"


def normalize_revision_mode(value=None) -> str:
    """The canonical revision-mode name for a configured/passed value.

    The default is `continue` (the pipeline's own review/revise rounds). The
    pre-rename spelling `none` is accepted as an alias of `continue` so existing
    roots, scripts and habits keep working.
    """
    mode = str(value or JOURNAL_MODE_CONTINUE).strip().lower()
    return JOURNAL_MODE_ALIASES.get(mode, mode)


def journal_mode_of(ctx=None) -> str:
    """The configured journal revision mode ('continue' when unset).

    Reads `revision_mode` from pipeline_config.json (mirrored into state.json
    as `config`). An unknown value is an error, not a silent 'continue': a typo
    in the mode would otherwise silently run the wrong workflow.

    When NO mode is recorded, a non-empty `llm_review_feedback/` area in the
    corpus's pristine copy turns the effective mode into `llm` automatically
    (the operator's directory-driven switch; rename it to
    `llm_review_feedback.disabled` or record an explicit mode to turn it off).
    An EXPLICIT recorded mode always wins -- auto-detection never overrides it.
    """
    cfg = (getattr(ctx, "cfg", None) if ctx is not None else None) or {}
    raw = str(cfg.get("revision_mode") or "").strip()
    if not raw:
        return auto_revision_mode_for(ctx) or JOURNAL_MODE_CONTINUE
    mode = normalize_revision_mode(raw)
    if mode not in JOURNAL_MODES:
        die(f"pipeline_config.json records revision_mode {mode!r}, which is not one of "
            f"{', '.join(JOURNAL_MODES)}. Fix it with `set-revision-mode <mode>` or start a "
            f"fresh root.")
    return mode


def llm_feedback_present_in(dirp) -> bool:
    """True when `dirp` carries a NON-EMPTY llm_review_feedback/ area.

    A directory with no file anywhere inside it does not trigger the mode; a
    renamed (`llm_review_feedback.disabled`) or moved area never does either --
    only the canonical name counts.
    """
    if dirp is None:
        return False
    try:
        area = Path(dirp) / LLM_FEEDBACK_DIR
        if not area.is_dir():
            return False
        return any(p.is_file() and not is_bookkeeping_name(p.name) for p in area.rglob("*"))
    except OSError:
        return False


def auto_revision_mode_for(ctx=None) -> str:
    """The directory-driven mode (`llm`) or `""` when auto-detection is off.

    Auto-detection is OFF whenever an explicit revision_mode is recorded (there
    is no such value in a default root: `setup` writes no key for `continue`),
    and when the LLM review area is absent, empty or renamed to its inert
    `.disabled` spelling. The result is cached on the context: the pristine copy
    cannot change during one invocation.
    """
    cfg = (getattr(ctx, "cfg", None) if ctx is not None else None) or {}
    if str(cfg.get("revision_mode") or "").strip():
        return ""
    pristine = getattr(ctx, "pristine", None)
    if pristine is None:
        return ""
    cached = getattr(ctx, "_auto_revision_mode", None)
    if cached is None:
        cached = JOURNAL_MODE_LLM if llm_feedback_present_in(pristine) else ""
        try:
            setattr(ctx, "_auto_revision_mode", cached)
        except Exception:                                         # noqa: BLE001
            pass
    return cached


def revision_mode_origin(ctx=None) -> str:
    """`explicit` / `auto` / `default` for the effective revision mode."""
    cfg = (getattr(ctx, "cfg", None) if ctx is not None else None) or {}
    if str(cfg.get("revision_mode") or "").strip():
        return "explicit"
    return "auto" if auto_revision_mode_for(ctx) else "default"


def revision_mode_note(ctx=None) -> str:
    """One line to print when the mode came from the directory, not the config."""
    if revision_mode_origin(ctx) != "auto":
        return ""
    return (f"revision mode auto-detected: {JOURNAL_MODE_LLM} "
            f"({LLM_FEEDBACK_DIR}/ is present and non-empty; only that area is read). "
            f"Rename it to {LLM_FEEDBACK_DIR}.disabled, or record an explicit mode "
            f"(`--revision-mode continue`), to turn the auto-detection off.")


def journal_feedback_streams(ctx=None) -> tuple:
    """Which review-feedback streams the effective mode consumes."""
    return tuple(JOURNAL_MODES.get(journal_mode_of(ctx), {}).get("streams") or ())


def journal_mode_info(ctx=None) -> dict:
    return JOURNAL_MODES[journal_mode_of(ctx)]


def journal_is_scoped(ctx=None) -> bool:
    """True for the major/minor modes: concern-scoped edits only."""
    return bool(journal_mode_info(ctx).get("scoped"))


def journal_needs_response(ctx=None) -> bool:
    """True when a response-to-reviewers document is a required deliverable."""
    return bool(journal_mode_info(ctx).get("response"))


def submit_code_of(ctx=None) -> bool:
    """Whether the analysis-code area is part of the submission.

    `submit_code` is recorded at setup (`on`/`off`) and flipped on an existing
    root with `set-submit-code`. A root without the key -- every root created
    before this policy existed -- behaves as `off`: `code/` is revision content
    whose files a stage may revise and the judges evaluate, but the submission
    copy strips it, and a to-be-submitted file may not refer into it.
    """
    raw = ((getattr(ctx, "cfg", None) if ctx is not None else None) or {}).get("submit_code")
    if isinstance(raw, bool):
        # A hand-edited config that carries the JSON boolean, not the string.
        return raw
    return str(raw or "").strip().lower() in ("on", "true", "yes", "1")


def submission_not_carried_areas(ctx) -> list:
    """The area names a submission built from this root does NOT carry (PKG-2).

    ONE definition of "what a submission leaves out", shared by the journal
    assembly (which derives it from the copy it just stripped), the published
    package's own scan and the code-side evidence pack, so the three can never
    disagree about whether a `code/` pointer dangles: the evidence areas never
    ship, and the analysis code ships only under `submit_code: on`.
    """
    areas = [str(n) for n in EVIDENCE_DIRNAMES]
    if not submit_code_of(ctx):
        areas.append(CODE_DIR)
    return areas


def journal_has_feedback(ctx=None) -> bool:
    """True when the mode consumes an editors'/reviewers' decision letter.

    `continue` (the pre-rename `none`) and `init` do not: no feedback/concerns
    stage, no journal block in any prompt, no response letter. The conform stage
    of `init` runs regardless -- it fills the venue's template, it does not read
    a letter.
    """
    return bool(journal_mode_info(ctx).get("feedback"))


def journal_rewrites_allowed(ctx=None) -> bool:
    """False for the major/minor modes: the manuscript may not be rewritten."""
    return bool(journal_mode_info(ctx).get("rewrites"))


def journal_feedback_paths(ctx: Ctx) -> list:
    """The operator-named feedback files, resolved (absolute paths)."""
    out = []
    raw = (ctx.cfg or {}).get("journal_feedback") or []
    if isinstance(raw, str):
        raw = [raw]
    for item in raw:
        s = str(item or "").strip()
        if not s:
            continue
        p = Path(s)
        if not p.is_absolute():
            # Root-relative first (the documented spelling), then CWD-relative:
            # an operator who typed the path from their shell should not have to
            # discover the difference.
            root_rel = ctx.root / p
            p = root_rel if root_rel.exists() else (Path.cwd() / p)
        out.append(p)
    return out


def journal_feedback_files(ctx: Ctx) -> list:
    """[(absolute path, label)] of the feedback this root revises against.

    Precedence:
      1. operator-named files (`setup --journal-feedback`), which win outright;
      2. every file in the corpus's `human_review_feedback/` area that is not an
         authored reply (the area exists for exactly this content, so it needs
         no name heuristic -- a Chinese-named or generically named report works);
      3. the legacy name heuristic over the whole corpus (`feedback`/`referee`/
         `reviewer`/`editor`/`decision` in the file name), which keeps the
         earlier design working when the letter lives in `raw_data/`.
    A file the AUTHORS wrote (`response_to_reviewers.docx`, `cover_letter_to_
    editor.docx`, `point-by-point.md`) is never read as the journal's letter.

    This is the HUMAN/decision-letter stream only. A sibling
    `llm_review_feedback/` area (false positives pre-filtered) is resolved by
    `journal_llm_feedback_files` and merged with this one by the feedback/
    concerns sessions, which keeps each finding's provenance explicit.
    """
    streams = journal_feedback_streams(ctx)
    if streams and "human" not in streams:
        # `llm` mode reads ONLY the LLM review: a human letter in the corpus is
        # not a concern source here (it stays evidence for the judges).
        return []
    named = journal_feedback_paths(ctx)
    if named:
        out = []
        for p in named:
            if not p.is_file():
                die(f"--journal-feedback {p} does not exist (or is not a file). Give the "
                    f"decision letter / reviewer report(s) explicitly, or drop the flag and let "
                    f"the pipeline find them in the corpus's human_review_feedback/ area.")
            out.append((p, p.name))
        return out
    if not ctx.pristine.is_dir():
        return []
    area = human_feedback_files_in(ctx.pristine)
    feedback = [(p, label) for p, label in area
                if not JOURNAL_AUTHORED_REPLY_RE.search(p.name)]
    if feedback:
        return feedback
    found = []
    for p in sorted(ctx.pristine.rglob("*")):
        if not p.is_file() or is_bookkeeping_name(p.name):
            continue
        rel = p.relative_to(ctx.pristine).as_posix()
        if is_original_submission_rel(rel):
            continue
        if evidence_area_of(rel) == LLM_FEEDBACK_DIR:
            # The LLM review is its own stream (`journal_llm_feedback_files`),
            # never swept up by the decision-letter name heuristic: a
            # "reviewer_report.md" inside llm_review_feedback/ must not be
            # relabelled as a human letter.
            continue
        if is_journal_feedback_name(p.name) \
                and not JOURNAL_AUTHORED_REPLY_RE.search(p.name):
            found.append((p, rel))
    return found


def is_original_submission_rel(rel: str) -> bool:
    """True for a corpus-relative path inside `human_review_feedback/original_submission/`.

    The child directory holds the manuscript version the previous journal's
    editors/reviewers saw. It is EVIDENCE: it must never be enumerated as a
    feedback document (the area's files otherwise need no name heuristic), never
    seeded as a concern and never counted as the current submission's text.
    """
    parts = str(rel or "").replace("\\", "/").lstrip("/").split("/")
    return (len(parts) >= 2 and parts[0] == HUMAN_FEEDBACK_DIR
            and parts[1] == ORIGINAL_SUBMISSION_DIRNAME)


def human_original_submission_dirs(dirp: Path) -> list:
    """[(path, label)] of the reviewer-visible submission copies in `dirp`.

    The layout is fixed: `<corpus>/human_review_feedback/original_submission/`.
    More than one corpus can contribute to one root only for named feedback
    files, so at most one entry exists in practice; returning a list keeps the
    staging code honest when a future layout nests several.
    """
    area = Path(dirp) / HUMAN_FEEDBACK_DIR
    out = []
    if not area.is_dir():
        return out
    for child in sorted(area.iterdir()):
        if child.is_dir() and child.name == ORIGINAL_SUBMISSION_DIRNAME:
            out.append((child, f"{HUMAN_FEEDBACK_DIR}/{ORIGINAL_SUBMISSION_DIRNAME}"))
    return out


def review_feedback_files_in(dirp: Path, area_name: str) -> list:
    """[(path, corpus-relative label)] of every FEEDBACK FILE in one area.

    `human_review_feedback/original_submission/` is deliberately excluded: it is
    a manuscript, not a letter or a response. Treating its files as feedback
    would seed the concern ledger from the manuscript itself. The LLM area has
    no such child.
    """
    area = Path(dirp) / area_name
    out = []
    if not area.is_dir():
        return out
    for p in sorted(area.rglob("*")):
        if not p.is_file() or is_bookkeeping_name(p.name):
            continue
        label = p.relative_to(Path(dirp)).as_posix()
        if area_name == HUMAN_FEEDBACK_DIR and is_original_submission_rel(label):
            continue
        out.append((p, label))
    return out


def human_feedback_files_in(dirp: Path) -> list:
    """[(path, label)] of the human editors'/reviewers' feedback files."""
    return review_feedback_files_in(dirp, HUMAN_FEEDBACK_DIR)


def llm_feedback_files_in(dirp: Path) -> list:
    """[(path, label)] of the (false-positive-filtered) LLM review files."""
    return review_feedback_files_in(dirp, LLM_FEEDBACK_DIR)


def journal_llm_feedback_files(ctx: Ctx) -> list:
    """[(absolute path, label)] of the LLM review feedback of this root.

    The LLM stream is kept SEPARATE from `journal_feedback_files` (the human
    decision letter / referee reports): the journal stages consume both, but the
    provenance, the prompt wording and the ledger's `author` column must never
    blur them. Unlike the human area there is no name heuristic and no
    previous-response or `original_submission/` machinery: the area IS the
    feedback.
    """
    streams = journal_feedback_streams(ctx)
    if streams and "llm" not in streams:
        return []
    if not ctx.pristine.is_dir():
        return []
    return llm_feedback_files_in(ctx.pristine)


def journal_previous_responses(ctx: Ctx) -> list:
    """[(path, label)] of authored replies found beside the human feedback.

    A previous response-to-reviewers document is CONTEXT (what was promised),
    never a concern source and never the journal's letter. It is listed to the
    session so it can keep the new response consistent with the old one.
    """
    if not ctx.pristine.is_dir():
        return []
    return [(p, label) for p, label in human_feedback_files_in(ctx.pristine)
            if JOURNAL_AUTHORED_REPLY_RE.search(p.name)]


def feedback_text_of(path: Path) -> tuple:
    """(text, note) for one feedback file -- the reviewable rendering."""
    ext = path.suffix.lower()
    if ext in (".txt", ".md", ".markdown", ".rst", ".tex", ".bib", ".csv", ".tsv"):
        try:
            return path.read_text(encoding="utf-8", errors="replace"), ""
        except OSError as e:
            return "", f"unreadable: {e}"
    if ext == ".docx":
        paras = _docx_paragraphs(path)
        if paras is None:
            return "", "docx-unreadable"
        return "\n".join(paras), ""
    if ext == ".pdf":
        if shutil.which("pdftotext"):
            try:
                proc = subprocess.run(["pdftotext", "-layout", str(path), "-"],
                                      capture_output=True, timeout=60)
                text = proc.stdout.decode("utf-8", errors="replace")
                if text.strip():
                    return text, ""
                return "", "pdftotext produced no text (scanned/image PDF?)"
            except Exception as e:                                   # noqa: BLE001
                return "", f"pdftotext failed: {e}"
        return "", "pdf-unconvertible: pdftotext not available"
    return "", f"unparseable extension {ext!r} (the original is still copied for the session)"


def seed_concern_candidates(text: str) -> list:
    """Code-side candidate split of a decision letter / reviewer report.

    Not the deliverable: a SEED the session refines. Splits at reviewer/editor
    headings and numbered-point markers; a document with none falls back to
    blank-line paragraphs. Bounded (200 rows, 400 chars each) so a runaway
    letter cannot flood the prompt.
    """
    lines = [ln.rstrip() for ln in (text or "").splitlines()]
    starts = []
    # The word alternatives keep their trailing `\b` (so "editorial" does not
    # start a block); the marker alternatives must NOT carry it: `\b` can never
    # match after "." / ")" / "-" when a space follows, so "1. Comment" and
    # "- Item" never split (only the unusual "1.Comment" did), and the
    # docstring's "numbered-point markers" were dead.
    head_re = re.compile(
        r"^\s*(?:(?:reviewer|referee|editor|comments?|major|minor|point|query)\b|"
        r"\d+\s*[.)]|[-*•]\s+)", re.I)
    for i, ln in enumerate(lines):
        if head_re.match(ln):
            starts.append(i)
    rows = []
    if starts:
        bounds = starts + [len(lines)]
        for a, b in zip(bounds, bounds[1:]):
            block = " ".join(x.strip() for x in lines[a:b] if x.strip())
            if block:
                rows.append({"heading": lines[a].strip()[:160], "excerpt": block[:400]})
    else:
        for para in re.split(r"\n\s*\n", "\n".join(lines)):
            block = " ".join(para.split())
            if block:
                rows.append({"heading": block[:80], "excerpt": block[:400]})
    return rows[:200]


def journal_concern_ledger(sandbox: Path) -> dict:
    """The concern ledger a feedback/concerns run wrote ({} when absent)."""
    data = read_json(sandbox / JOURNAL_CONCERNS_JSON_REL, revive=False, lenient=True)
    return data if isinstance(data, dict) else {}


def journal_concern_rows(sandbox: Path) -> list:
    rows = (journal_concern_ledger(sandbox) or {}).get("concerns")
    return [r for r in rows if isinstance(r, dict)] if isinstance(rows, list) else []


# The archive excludes the re-derivable INPUT corpora: every materialization
# rewrites them from hash-verified sources, and copying them would multiply a
# 180 MB sandbox by every retry. What is preserved is what the ATTEMPT produced,
# plus the prompt it answered and the bookkeeping the postcheck read.
ATTEMPT_ARCHIVE_SKIP_DIRS = ("base", "self", "others", "target", "field", "original",
                             *PRISTINE_DIRNAMES)
ATTEMPT_ARCHIVE_SKIP_SUBTREES = (("work", "corpus"),)
SUPERSEDED_DIRNAME = "_superseded"
# Python bytecode caches (`__pycache__/*.pyc`) are a side effect of RUNNING the
# helper scripts the pipeline seeds into a sandbox -- never a deliverable. The
# repair-scope guard reads them as "the session wrote outside its scope" unless
# they are filtered out (r1_i3, 2026-09-22: a repair that had cleared every
# problem it was given was failed for `__pycache__/paper_docx_format.*.pyc`).
BYTECODE_DIRNAME = "__pycache__"
BYTECODE_SUFFIXES = (".pyc", ".pyo")


def is_bytecode_cache(rel) -> bool:
    """Is this sandbox-relative path a Python bytecode cache (never a deliverable)?"""
    parts = tuple(x for x in Path(str(rel)).parts if x and x != ".")
    return BYTECODE_DIRNAME in parts or str(rel).endswith(BYTECODE_SUFFIXES)
# `setup` writes this into the root it is building and removes it once
# state.json exists, so a setup that died part-way (a transient I/O error while
# hashing or scanning the fresh copy) can be re-run on the SAME root instead of
# leaving a half-built directory the operator must delete by hand.
SETUP_MARKER = "_setup_in_progress"

# The winner of every round is published, in addition to the content-addressed
# pin, into its own directory directly under --root: <root>/round<R>_winner/.
WINNER_DIR_FMT = "round{r}_winner"
# `decide` also publishes the final champion as a clean, self-contained corpus
# that can seed a NEW pipeline run, named after the root directory that hosts
# it: <root>/final_clean_version_<root directory name>/. It is the winner
# corpus byte-for-byte (no process scratch, no auxiliaries, no self-written
# reports), so `setup --source <root>/final_clean_version_<root directory
# name>` starts from exactly the content the judges scored. It is generated on
# EVERY decide, certified or not; the verdict and the package's provenance live
# in the SIBLING <root>/final_clean_version.readme.md. Nothing is written
# INSIDE it: an added README/manifest would become manuscript content for the
# next round. The same tree is also compressed into the SIBLING
# <root>/final_clean_version_<root directory name>.zip; the directory is KEPT.
FINAL_CLEAN_DIRNAME = "final_clean_version"
# The SIBLING status file: the directory itself stays a byte-clean manuscript
# corpus (anything inside it would become manuscript content in the next run),
# so the certification verdict and the package's provenance live beside it.
FINAL_CLEAN_README_NAME = FINAL_CLEAN_DIRNAME + ".readme.md"


def final_clean_dirname(root: Path) -> str:
    """The published package's directory name: `final_clean_version_<root name>`."""
    return f"{FINAL_CLEAN_DIRNAME}_{Path(root).resolve().name}"


# Companion module for the code-side OOXML style/formatting scan (see
# scan_format_in_sources). `setup` copies it next to the pipeline script so the
# root stays self-contained; when it is absent the scan reports "unavailable"
# instead of failing the run.
DOCX_FORMAT_MODULE = "paper_docx_format.py"
# `setup --format-fix`: normalize the mechanical OOXML formatting defects of the
# pristine copy (and, later, of every stage package) before anything is
# fingerprinted/judged. `off` keeps the copy byte-identical to --source and the
# scan stays advisory.
FORMAT_FIX_MODES = ("auto", "off")
DEFAULT_FORMAT_FIX = "auto"
# The published copy keeps its LIVE Zotero fields by default. The pipeline
# refreshes them (repairs the numbering) but does NOT unlink them: unlinking is
# the author's own step when the final submission file is prepared (the field
# state stays editable in Zotero). Operators who want the pipeline to flatten
# `final_clean_version/` set
# `format_policy.unlink_zotero_fields_at_publish: true`.
DEFAULT_PUBLISH_FLATTEN_ZOTERO = False
# `run --only`: run a subset of the round's stages. `merge` is an alias for the
# integration stage (the pipeline's "merge from the other versions" step), and
# `a`/`w`/`i` are the short spellings used in the round plan.
ONLY_STAGES = ("rewrite", "review", "probe", "audit", "revise", "integrate", "judge",
               "feedback", "concerns", "response", "conform")
ONLY_ALIASES = {"w": "rewrite", "rewrites": "rewrite", "r": "review", "reviews": "review",
                "pr": "probe", "prob": "probe", "probes": "probe", "probe-review": "probe",
                "aud": "audit", "audits": "audit", "auditor": "audit", "verify": "audit",
                "a": "revise", "a2": "revise", "revises": "revise", "revision": "revise",
                "i": "integrate", "integrations": "integrate", "integration": "integrate",
                "merge": "integrate", "merges": "integrate", "j": "judge", "judges": "judge",
                "fb": "feedback", "feedbacks": "feedback",
                "concern": "concerns",
                "resp": "response", "responses": "response", "response-to-reviewers": "response"}
# The auditor sits between the reviewer and the reviser: it disposes the frozen
# review's findings (confirm / drop-with-evidence) and attacks the reviewer's
# boilerplate dispositions, and the reviser consumes the AUDITED list. `off`
# keeps the previous plan shape (review -> revise) for comparability.
# The auditor is ON by default: the review's disposition layer was the pipeline's
# single largest source of shipped leftovers, and one extra session per round is
# cheaper than a second round. `setup --audit off` (or `--no-audit`) restores the
# two-step plan; a root created before this default keeps the policy recorded in
# its own pipeline_config.json.
AUDIT_MODES = ("off", "on")
DEFAULT_AUDIT = "on"
# `setup --placeholder-lookup`: resolve a `searchable` hand-off marker
# ([AUTHOR TO COMPLETE: state whether this work has been posted to a preprint
# server ...]) with the orchestrator's own public-API lookups BEFORE the session
# starts. The sessions may not search the network (their sandbox is closed), so
# without this the pipeline can only carry the question forward -- which is how
# a question whose answer is "not posted" reached the submitted cover letter.
PLACEHOLDER_LOOKUP_MODES = ("off", "online")
DEFAULT_PLACEHOLDER_LOOKUP = "online"
# `--strict-artifacts` is ON by default and `--residual-gate` is ON by default:
# a decision artifact that is empty or boilerplate, a language pass without its
# coverage rows, and a delivered package that still carries a marker the lookup
# engine answered are all failures now, not warnings. The `--non-…` flags exist
# for operators who want the older advisory behaviour (and for the pipeline's
# own regression fixtures).
DEFAULT_STRICT_ARTIFACTS = True
# `--strict-artifacts` takes three values (bare = `on`):
#   on   an unfilled/boilerplate decision artifact FAILS the attempt (default)
#   fix  ... but first spend ONE scoped repair session on that attempt's decision
#        tables (see `artifact_policy_of`); the same postcheck judges the repair
#   off  record the detector's report as a warning, never fail on it
# VARIANT B (operator decision, 2026-09-23): a repair finishes the paperwork of
# work that HAPPENED; it never substitutes for the work. So a repair may only
# CHANGE files the stage itself wrote (fill cells, complete a ledger/report it
# left behind). A deliverable the stage never wrote -- a missing ledger, report,
# language pass, visual record or completion marker -- is NOT repairable: the
# stage stopped before finishing, the attempt fails, and the stage is re-run.
# The guard enforces it mechanically (any file created inside the writable scope
# is out of scope), so not even a well-meaning repair can author one.
# `fix` exists because the alternative -- re-running the whole review for a
# disposition column -- costs a full re-sample of the stage (the 2026-09-22 root
# paid 26 minutes and produced a different finding set to fix one column), while
# the repair is bounded: fill cells, never touch findings, never touch a row's
# identity, then pass the identical postcheck or fail like any other attempt.
ARTIFACT_POLICY_FIX = "fix"
ARTIFACT_POLICIES = ("on", ARTIFACT_POLICY_FIX, "off")
DEFAULT_ARTIFACT_POLICY = "on"
DEFAULT_RESIDUAL_GATE = True
# How many identifier lookups one stage may spend. Each is a single request to a
# public API with a 20-second cap, cached for LOOKUP_CACHE_TTL_DAYS across the
# root's sandboxes; `off`/an unreachable network degrades to recorded `error`
# rows, never to a failed stage. The cap is spent in the reserved order below,
# and the reference-list DOIs now sit first in that order: a manuscript's
# reference list is the largest class by far (one entry each) and the only place
# a one-character DOI corruption can be caught at all -- no format check and no
# re-reading sees it (see M2_references.md).
LOOKUP_MAX_TARGETS = 48
LOOKUP_TIMEOUT = 10
# One cheap probe per process decides whether the lookup engine runs at all;
# without it every sandbox would pay a DNS/connect timeout per query (the
# scheduling tests measure a round in seconds), and an offline operator would
# see a slow pipeline instead of `skipped` rows. The probe asks the works
# ENDPOINT (no specific record): a record is not a reachability test -- the old
# probe named a DOI that answers HTTP 404, `urlopen` raised on the 404, and the
# whole lookup engine (identifiers, availability locators, gene symbols,
# placeholders, and the reference-integrity seed) then recorded `skipped`
# everywhere while blaming the operator's network. Any HTTP ANSWER means the
# API is reachable; only a connect/DNS/TLS failure is "not available".
LOOKUP_PROBE_URL = ("https://api.crossref.org/works?rows=0"
                    "&mailto=paper-pipeline@example.org")
LOOKUP_PROBE_TIMEOUT = 2.5
LOOKUP_CACHE_REL = "reports/LOOKUP_CACHE.json"
LOOKUP_CACHE_TTL_DAYS = 14
_LOOKUP_PROBE = {}

# A candidate's corpus is its revised/ documents (plus code/), NOT the revision
# skill's WORK directory: revised/work/ holds the A1-A9 process artifacts,
# corpus conversions and scripts, which are not part of the submission. Without
# this exclusion every round's winner would carry its own scratch tree into the
# next round's base, and the frozen-sweep reviewers would inventory converted
# copies of the manuscript as if they were extra submission files.
CORPUS_EXCLUDE_TOP = ("work",)

# ---- code-side caption checking (M18) -------------------------------------
# When the operator opts into the pipeline's caption suggestion, the prompts ask
# every agent to count caption words. These lists/knobs let the orchestrator
# check the lengths mechanically where the text is extractable, and to say so
# honestly where it is not. The check is a REPORT: caption length never gates,
# ranks or fails anything (see caption_gate() and CAPTION_RULE).
# One source of truth for "which files does each code-side scan read?".
CAPTION_DOCX_EXTS = (".docx",)
CAPTION_TEX_EXTS = (".tex", ".ltx")
# The same editable text formats the length scan reads (LENGTH_TEXT_EXTS): a
# manuscript whose legends are counted as main text must also have them
# enumerated, or M18 reports nothing for a document M19 measures.
CAPTION_TEXT_EXTS = (".md", ".txt", ".markdown", ".rst")
CAPTION_SOURCE_EXTS = CAPTION_DOCX_EXTS + CAPTION_TEX_EXTS + CAPTION_TEXT_EXTS
# The placeholder diagnostic also looks at bibliography/data/prose tables.
PLACEHOLDER_SOURCE_EXTS = CAPTION_SOURCE_EXTS + (".bib", ".csv", ".rtf")
CAPTION_UNPARSED_EXTS = (".doc", ".pdf", ".ppt", ".pptx")

# Files the pipeline itself (or the revision skill it drives) mandates inside the
# submission directory. They are pipeline bookkeeping, not submission content:
# they are excluded from the caption scan and from the document-set comparison so
# that a changelog quoting a caption, or a report that is regenerated under a
# different name, is never judged as manuscript text. They are excluded from the
# corpus DIGEST (hash/pin/next-round base) -- and from the materialized pin and
# judge target -- by this same name rule, so the two sides remain byte-identical.
BOOKKEEPING_FILES = ("changelog.md", "manual_steps.md", "revision_report.md",
                     "revision_report.json", "diff_ledger.md", "rewrite_report.md",
                     "visual_check.md",
                     # The pipeline's own completion signals. They belong at the
                     # sandbox ROOT (see SIGNAL_ALT_DIRS); this list is the second
                     # fence: a signal that ends up INSIDE a package directory
                     # (a misplaced `_pipeline_done.json`, a judge sheet dropped
                     # into `revised/`) must never travel into the judged corpus,
                     # the champion pin or the content fingerprint -- a stray
                     # bookkeeping file would otherwise date a package or make
                     # two copies of the same content look different.
                     "_pipeline_done.json", "scores.json")

# Bookkeeping the pipeline (or the skills it drives) mandates inside the
# submission directory. The agent that writes a version also writes these files,
# so they must never be handed to a judge as package content: a self-written
# report is not evidence, its presence/absence between two labels is a
# provenance signal, and a polished CHANGELOG is exactly the kind of claim a
# relative judge must not read. They stay in the run's own sandbox, where the
# postchecks, the manual-item count and the decision report read them.
# (BOOKKEEPING_FILES already carries visual_check.md: the visual record is a
# stage report, so the judged/pinned corpus and the content FINGERPRINT must
# skip exactly the same names -- otherwise a champion's recorded fingerprint
# never matches the pinned copy built from it, and the next round's base stops
# deduplicating against the pin it was copied from.)
CORPORA_STRIP_BOOKKEEPING = BOOKKEEPING_FILES


# The pipeline's own by-products can carry a VERSION TOKEN between their name
# and their extension (`REPLACEMENT_LEDGER-c27c42e.md` is what the published
# package actually carries after the filename counter runs). The exact-name
# test above therefore misses them, which is how a stage's internal re-authoring
# ledger shipped to the journal. The pattern below matches the family with or
# without a token, so the strip/fingerprint/bookkeeping paths all agree.
BOOKKEEPING_NAME_RE = re.compile(
    r"^(?:replacement_ledger|diff_ledger|revision_report|rewrite_report|manual_steps|"
    r"visual_check|changelog|agent_log|worklog)"
    r"(?:[-_.][A-Za-z0-9._\-]+)?\.(?:md|txt|json)$"
    # The pipeline's own MEASUREMENT artifacts (written next to a run, never
    # into a delivered package): a scan/repair report, the code-side evidence
    # pack, the PKG-2 record. They are skipped by every corpus walk AND by the
    # PKG-2 scan itself -- an evidence JSON that names the areas ("raw_data/",
    # "code/") is not a submitted document, and reporting it as a dangling
    # reference would drown the real rows (2026-10-15).
    r"|^(?:code_scans|format_scan|format_fix|pkg2)(?:[-_.][A-Za-z0-9._\-]+)?"
    r"\.(?:md|txt|json)$", re.I)


def is_bookkeeping_name(name: str) -> bool:
    base = str(name or "").strip()
    if base.lower() in BOOKKEEPING_FILES:
        return True
    return bool(BOOKKEEPING_NAME_RE.match(base))


# Caption start patterns: "Figure 1 |", "Fig. 2.", "Supplementary Figure 3:", ...
_CAPTION_LABEL_RE = (r"^\s*(?:(?:supplementary|extended\s+data|supp)\s+)?fig(?:ure)?s?\.?\s*"
                     r"\|?\s*")
_CAPTION_NUM_RE = r"(S?\d+[A-Za-z]?|[IVXivx]+)"
# The panel group "(a)", "(a,b)" or "(a-b)" sits between the number and the
# separator: "Figure 2(a) |" is a caption, "Figure 2 is a schematic" is not.
_CAPTION_PANEL_RE = r"(?:\s*\([A-Za-z0-9][A-Za-z0-9,.\u2013\-]*\))?"
CAPTION_START_RE = re.compile(
    _CAPTION_LABEL_RE + _CAPTION_NUM_RE + _CAPTION_PANEL_RE +
    r"\s*(?:\||:|\u2014|\u2013|-|\.)\s*",
    re.IGNORECASE)
# Caption-LOOKING lines the strict pattern above does not recognise (a bare
# "Figure 3" line, a text-box label, an unusual separator). They are reported as
# suspected captions instead of being dropped silently.
CAPTION_SUSPECT_RE = re.compile(
    _CAPTION_LABEL_RE + _CAPTION_NUM_RE +
    r"\s*(?:\([^)]*\)|$|[|:\u2014\u2013\-])",
    re.IGNORECASE)

# ---- code-side document-set checking --------------------------------------
# Editable submission documents that must survive a rewrite/revision/integration
# round. Auxiliary files the revision skill emits on purpose are never required
# and never counted as duplicates. The auxiliary is a difference-tracking copy
# named for the BASELINE it was compared against (see TRACK_TOKEN_RE):
#
#   <name>.tracking-<token>.<ext>    real tracked copy (word/latexdiff)
#   <name>.tracking-<token>.pdf      compiled marked-up PDF of a latexdiff copy
#   <name>.logging-<token>.<ext>     the fallback log when the tool failed
#
# where <token> is `original` (the pre-conformed submission in non_revised/) or
# the id of the version the copy was compared against -- the round base `a1`,
# a rewrite `w<k>`, a revision `a<k>`, or `winner<r>` for the published winner
# of round r.
EDITABLE_DOC_EXTS = (".doc", ".docx", ".tex", ".ltx", ".bib", ".md", ".txt", ".xlsx",
                     ".rtf", ".csv")
# The extensions a difference-tracking copy is built for.
TRACKING_EXTS = (".docx", ".tex", ".bib")
# A latexdiff `.tex` copy is COMPILED as well, and the marked-up PDF is part of
# the same auxiliary family ("<name>.tracking-<token>.pdf"): a reader can open
# the tracked changes without a LaTeX toolchain, and the file can never leak
# into a corpus/pin/judge view (see TRACKING_AUX_NAME_RE).
TRACKING_PDF_EXT = ".pdf"
# The baseline token of a copy: the pre-conformed original, or the id of the
# version it was compared against (`a1`, `w2`, `a3`, ... -- the pipeline's own
# version vocabulary) or a published round winner (`winner1`, `winner2`, ...).
# The token is INFORMATIVE on purpose: "<name>.tracking-a1.docx" says exactly
# which version the difference was taken against.
TRACK_TOKEN_ORIGINAL = "original"
TRACK_TOKEN_RE = re.compile(r"^(?:original|winner[0-9]+|[awi][0-9]+)$", re.IGNORECASE)
# The full-file rule: `<anything>.tracking-<token>.<ext>` or
# `<anything>.logging-<token>.<ext>`. A file matching it is an auxiliary
# EVERYWHERE in the pipeline (corpus digest, pin, judge view, fingerprint,
# revision token, recovery backfill), which is what lets the pipeline write the
# copies next to a document without changing any version's identity.
TRACKING_AUX_NAME_RE = re.compile(
    r"\.(?:tracking|logging)-(?:original|winner[0-9]+|[awi][0-9]+)"
    r"\.(?:docx|tex|bib|pdf)$", re.IGNORECASE)
# Trailing version token on a basename stem: the CURRENT content-hash token
# ("-4f3a9c1"/"_4f3a9c1", 7 lowercase hex characters) or the LEGACY version
# tokens ("-b", "_v2", "-v10", case-insensitive) that older packages carry.
# A PLAIN trailing number ("-1", "-3") is NOT a version token: SI-Table-1.csv
# and Figure-3.xlsx are distinct documents and must never be merged.
DOC_TOKEN_RE = re.compile(r"(?:[-_][0-9a-f]{7}|[-_][vV]\d+|[-_][A-Za-z])$")

# Extensions that only ever hold a BUILD BY-PRODUCT of an editable source
# (.aux/.log/.synctex.gz/...). The prompts prescribe leaving these out of
# revised/, so the recovery backfill must never copy them back in.
DERIVED_BUILD_SUFFIXES = (".aux", ".blg", ".bcf", ".log", ".out", ".fls", ".fdb_latexmk",
                          ".synctex.gz", ".run.xml", ".toc", ".lof", ".lot", ".nav",
                          ".snm", ".vrb", ".bbl", ".idx", ".ilg", ".ind")


def _is_derived_name(name: str) -> bool:
    low = name.strip().lower()
    return any(low.endswith(s) for s in DERIVED_BUILD_SUFFIXES)


# The build by-products a JUDGE VIEW never carries: DERIVED_BUILD_SUFFIXES minus
# the one derived file the prompts let a package ship on purpose -- a compiled
# ".bbl" (with no editable ".bib" beside it, the ".bbl" is the only copy of the
# reference list, and unlike the others it carries no build date, tool path or
# machine name). Used by _is_view_excluded_file().
VIEW_STRIP_DERIVED_SUFFIXES = tuple(s for s in DERIVED_BUILD_SUFFIXES if s != ".bbl")

# Editable sources that turn a same-stem ".pdf" into a DERIVED output of the
# package: a judge is handed the source, not the rendering (see
# _is_view_excluded_file). ".txt" is deliberately absent -- a text file sitting
# beside a figure PDF is not a source/derived pair.
VIEW_DERIVED_SOURCE_EXTS = (".doc", ".docx", ".tex", ".ltx", ".rtf", ".md")


def _doc_stem_key(name: str) -> str:
    """A basename's stem without its version token (see DOC_TOKEN_RE)."""
    return DOC_TOKEN_RE.sub("", Path(name).stem).lower()


def _is_view_excluded_file(name: str, siblings=()) -> bool:
    """True for a file a JUDGE VIEW never carries (submission content only).

    Beyond the revision auxiliaries `_is_aux_doc()` already drops, a view drops
    the build by-products of an editable source (".aux", ".log", ".toc", ...)
    and Word's "~$name.docx" owner/lock files. Three reasons:

      * they are not submission content -- a compile regenerates every one of
        them, and the stage prompts already order them left out of a version;
      * their CONTENT is provenance: a LaTeX ".log"/".fls"/".synctex.gz" names
        the build machine's absolute paths and the exact build date, and a
        "~$" file names its author -- the metadata pass cannot touch what is
        inside a build log;
      * their PRESENCE is provenance: a version an agent went over loses them
        (the prompts order that) while the untouched original keeps them, so
        the file SET alone would tell a judge which package was worked on.

    A view is also given the SOURCES rather than what can be compiled from them,
    so a derived output whose editable source ships in the same directory is
    dropped too: a compiled ".bbl" beside its ".bib", and a ".pdf" beside the
    ".docx"/".doc"/".tex"/".ltx"/".rtf"/".md" it was rendered from (see
    VIEW_DERIVED_SOURCE_EXTS). `siblings` is that directory's file-name list.
    A derived file with NO source in the package stays: when it is the only copy
    of the content, it IS the content -- with no ".bib" shipped, a ".bbl" is the
    only copy of the reference list.
    """
    low = name.strip().lower()
    if _is_aux_doc(name) or low.startswith("~$"):
        return True
    if low.endswith((".pdf", ".bbl")):
        sources = VIEW_DERIVED_SOURCE_EXTS if low.endswith(".pdf") else (".bib",)
        stem = _doc_stem_key(name)
        return any(s.strip().lower().endswith(sources) and _doc_stem_key(s) == stem
                   for s in siblings)
    return low.endswith(VIEW_STRIP_DERIVED_SUFFIXES)


# ---- opaque judge session identity ----------------------------------------
# A judge must not be able to infer provenance from its own target: the sandbox
# run id and the sheet's target_id are opaque tokens derived from
# (round, version id); the version id itself lives only in the run record.
JUDGE_TOKEN_PREFIX = "t"

# Version ids. Fresh ids are local to one round; a pinned version carries its
# round prefix so ids stay unique inside a field (e.g. "r1_a2").
ORIGINAL_ID = "orig"
A1_ID = "a1"

# ---- THE ROUND'S CANDIDATE POOL (M rewrites, N revisions, then integration) --
# Every round is planned with two per-round counts (both are command-line
# parameters, see --rewrites / --revises):
#   M = the number of REWRITTEN candidates the round creates from its base
#       (independent rewrite sessions, staged BEFORE the review), and
#   N = the number of REVIEWED-AND-THEN-REVISED candidates the round creates
#       (the round's single $paper-review pass is consumed by N independent
#       $paper-revise sessions).
# The round's POOL is, in this fixed order:
#   "a1"                       the round's base A1_r        (not an agent run)
#   "w1" .. "wM"               the M rewritten candidates
#   "a2" .. "a{1+N}"           the N reviewed-and-revised candidates
# and EVERY pool member is then reworked ONCE by an INTEGRATION run that takes
# that member as its base and ALL the OTHER pool members as donors (this is the
# stage formerly mis-named "cross-pollination" -- there are no pairwise arms):
#   "i1" .. "iK"   with K = 1 + M + N, i{k} integrating the k-th pool member,
#                  so with M=2, N=1:
#                    i1 = a1 <- (w1, w2, a2)     i3 = w2 <- (a1, w1, a2)
#                    i2 = w1 <- (a1, w2, a2)     i4 = a2 <- (a1, w1, w2)
# A1_r is the round's incumbent (its row is the field member it deduplicates
# into) and is not itself a candidate to crown; everything else, the integrated
# candidates included, competes on the published ranking key.
FRESH_VID_RE = re.compile(r"^(?:w(\d+)|a(\d+)|i(\d+))$")


def rewrite_vid(k) -> str:
    """Version id of the k-th rewritten candidate of a round ("w1", "w2", ...)."""
    return f"w{int(k)}"


# The LEVEL a rewrite arm works at. The round deliberately contains BOTH levels
# when it has more than one rewrite: the pool then carries large (organization)
# and small (sentence) differences, the integration stage's DIFF_LEDGER has both
# kinds of rows to weigh, and the panel can see whether a difference is a
# reorganization or a prose improvement.
REWRITE_LEVELS = ("structural", "sentence")


def rewrite_level_of(k: int, m: int) -> str:
    """`structural` for odd arms, `sentence` for even ones (M >= 2).

    With a single rewrite arm the level is `structural`: organization is what a
    rewrite exists for, and the sentence level is covered by every revision arm
    and by the language pass.
    """
    if int(m) <= 1:
        return "structural"
    return "structural" if int(k) % 2 == 1 else "sentence"


def revise_vid(j) -> str:
    """Version id of the j-th reviewed-and-revised candidate ("a2", "a3", ...)."""
    return f"a{int(j) + 1}"


def integrate_vid(k) -> str:
    """Version id of the k-th integrated candidate ("i1", "i2", ...)."""
    return f"i{int(k)}"


def is_fresh_vid(vid) -> bool:
    """True for a round-local version id (a1/w*/a>=2/i*), False for pins/orig."""
    return bool(isinstance(vid, str) and FRESH_VID_RE.match(vid))


def is_integrated_vid(vid) -> bool:
    return bool(isinstance(vid, str) and vid.startswith("i") and
                FRESH_VID_RE.match(vid))


def arm_of_vid(vid) -> str:
    """"rewrite" | "revise" | "integrate" | "base" for a round-local version id."""
    if vid == A1_ID:
        return "base"
    m = FRESH_VID_RE.match(str(vid))
    if not m:
        return "pinned"
    if m.group(1):
        return "rewrite"
    if m.group(2):
        return "revise"
    return "integrate"


def parse_round_counts(values, rounds: int, flag: str) -> list:
    """Normalize a per-round count list to exactly `rounds` entries.

    The CLI accepts either a single integer ("--rewrites 3") or a comma/space
    separated list of length n = --rounds ("--rewrites 2,1"). A list shorter
    than n is EXTENDED BY REPEATING ITS LAST ELEMENT; a longer one is truncated
    to the first n entries (the extra entries would never be reached).
    """
    vals = []
    for v in (values if isinstance(values, (list, tuple)) else [values]):
        if v is None:
            continue
        # A command-line value arrives as ONE string ("3", "2,1", "2, 1"); a
        # config value may already be a list of ints. Both shapes are accepted.
        parts = re.split(r"[,;\s]+", str(v).strip()) if isinstance(v, str) else [v]
        vals.extend(p for p in parts if str(p).strip() != "")
    counts = []
    for v in vals:
        try:
            counts.append(int(str(v).strip()))
        except (TypeError, ValueError):
            die(f"{flag} takes an integer or a comma-separated list of integers "
                f"(e.g. '{flag} 3' or '{flag} 2,1'), got {v!r}")
    if not counts:
        die(f"{flag} needs at least one integer")
    if any(c < 0 for c in counts):
        die(f"{flag} values must be >= 0, got {counts}")
    rounds = max(1, int(rounds))
    if len(counts) < rounds:
        counts = counts + [counts[-1]] * (rounds - len(counts))
    return counts[:rounds]


def normalize_round_indices(values, schedule_len: int = ROUND_SCHEDULE_LEN) -> list:
    """Normalize `--round-indices` to ascending 1-based schedule positions.

    Positive values count from the start of the built-in schedule (1 = the
    first round), negative values from its end (-1 = the last round). The
    ORDER is the pipeline's run order: the first index maps to pipeline
    round 1. Duplicates, an out-of-range index, a zero and a descending
    sequence are errors, because each silently changes which plan a round
    adopts.
    """
    if not values:
        die("--round-indices needs at least one round index")
    out = []
    for v in values:
        try:
            i = int(v)
        except (TypeError, ValueError):
            die(f"--round-indices takes integers (1-based, or negative from the end), got {v!r}")
        if i == 0:
            die("--round-indices is 1-based (or negative from the end); 0 is not a round")
        pos = i if i > 0 else schedule_len + 1 + i
        if pos < 1 or pos > schedule_len:
            die(f"--round-indices {i} is outside the built-in schedule 1..{schedule_len} "
                f"(negative values count from the end, -1 = {schedule_len})")
        out.append(pos)
    if len(set(out)) != len(out):
        die(f"--round-indices carries a repeated round: {out} "
            f"(one selected round runs once)")
    if out != sorted(out):
        die(f"--round-indices must be listed in ascending run order, got {values} -- "
            f"the FIRST index maps to the pipeline's round 1")
    return out


def parse_round_masks(values, rounds: int, flag: str) -> list:
    """Normalize a per-round integrator bitmask list to exactly `rounds` entries.

    Same shape rules as parse_round_counts (one value or a comma-separated list;
    a shorter list is extended by repeating its last element, a longer one is
    truncated), but each entry is an unsigned 32-bit mask written in any Python
    integer literal form: decimal ("5"), hexadecimal ("0xFFFFFFFF", the default),
    octal or binary. The mask addresses the round's pool in canonical order
    [a1, w1..wM, a2..a{1+N}]: bit (k-1) selects the integration arm i<k> of the
    k-th member (see INTEGRATOR_ALL).
    """
    vals = []
    for v in (values if isinstance(values, (list, tuple)) else [values]):
        if v is None:
            continue
        # A command-line value arrives as ONE string ("5", "0xFF,3"); a config
        # value may already be a list of ints. Both shapes are accepted.
        parts = re.split(r"[,;\s]+", str(v).strip()) if isinstance(v, str) else [v]
        vals.extend(p for p in parts if str(p).strip() != "")
    masks = []
    for v in vals:
        try:
            mask = int(str(v).strip(), 0)
        except (TypeError, ValueError):
            die(f"{flag} takes an integer bitmask or a comma-separated list of them "
                f"(e.g. '{flag} 0xFFFFFFFF' or '{flag} 0x5,3'), got {v!r}")
        if mask < 0 or mask > INTEGRATOR_ALL:
            die(f"{flag} values must be unsigned {INTEGRATOR_BITS}-bit masks in "
                f"0..0x{INTEGRATOR_ALL:X}, got {v!r}")
        masks.append(mask)
    if not masks:
        die(f"{flag} needs at least one bitmask")
    rounds = max(1, int(rounds))
    if len(masks) < rounds:
        masks = masks + [masks[-1]] * (rounds - len(masks))
    return masks[:rounds]


def counts_of(cfg, key: str, rounds: int) -> list:
    """The configured per-round counts, falling back to the documented defaults."""
    raw = (cfg or {}).get(key)
    if raw is None:
        raw = list(DEFAULTS[key])
    elif not isinstance(raw, (list, tuple)):
        raw = [raw]
    return parse_round_counts(raw, rounds, "--" + key)


def masks_of(cfg, key: str, rounds: int) -> list:
    """The configured per-round masks, falling back to the documented defaults.

    Accepts both the list written by a current `setup` and the plain integer an
    older root (or a hand-built test context) carries, so per-round integrator
    masks degrade to "the same mask every round" instead of crashing.
    """
    raw = (cfg or {}).get(key)
    if raw is None:
        raw = list(DEFAULTS[key])
    elif not isinstance(raw, (list, tuple)):
        raw = [raw]
    return parse_round_masks(raw, rounds, "--" + key)


def config_rounds(ctx=None, cfg=None) -> int:
    """The configured round count (never 0, so a hand-built test context works)."""
    cfg = (cfg if cfg is not None else getattr(ctx, "cfg", None)) or {}
    try:
        rounds = int(cfg.get("rounds") or 0)
    except (TypeError, ValueError):
        rounds = 0
    return max(1, rounds or len(DEFAULTS["rewrites"]))


def round_index(r: int, rounds: int) -> int:
    """The 0-based list index of round `r`, clamped into the configured range."""
    return max(0, min(int(r) - 1, max(1, int(rounds)) - 1))


def brief_list(values, fmt=str) -> str:
    """'3,3' / '0xffffffff,0x1' -- a one-line rendering of a per-round list."""
    return ",".join(fmt(v) for v in (values or []))


def judges_config_note(ctx) -> str:
    """The configured judges-per-round list, for config summary lines."""
    return brief_list(counts_of(getattr(ctx, "cfg", None), "judges", ctx.rounds_count()))


def integrators_config_note(ctx) -> str:
    """The configured integrators-per-round list, in hex."""
    return brief_list(masks_of(getattr(ctx, "cfg", None), "integrators", ctx.rounds_count()),
                      lambda v: f"0x{int(v):X}")


def round_counts(ctx, r: int) -> tuple:
    """(M, N) for round `r`: rewrites and reviewed-and-revised candidates.

    A round that has already been DECIDED carries its plan on the round record,
    and that recorded plan wins. Re-deriving the candidate set from the mutable
    config made `decide` non-reproducible: editing `pipeline_config.json`
    (or restoring it from a backup with different --rewrites/--revises values)
    silently changed which arms were considered, so the recomputed champion no
    longer matched the stored one and `decide` reported a bogus integrity
    problem about judge sheets that were perfectly fine.
    """
    try:
        plan = (ctx.round_get(int(r)) or {}).get("plan") or {}
    except Exception:                                        # noqa: BLE001
        plan = {}
    if isinstance(plan.get("rewrites"), int) and isinstance(plan.get("revises"), int):
        return max(0, int(plan["rewrites"])), max(0, int(plan["revises"]))
    rounds = config_rounds(ctx)
    idx = round_index(r, rounds)
    m = counts_of(getattr(ctx, "cfg", None), "rewrites", rounds)[idx]
    n = counts_of(getattr(ctx, "cfg", None), "revises", rounds)[idx]
    return int(m), int(n)


# --- WHICH JUDGE SESSIONS RUN (`run --only r1_judge_w2_j1`) -----------------
# `--judges` sets HOW MANY judges a version gets; `run --only` can select WHICH
# of those sessions run in that invocation (a pilot lever: one cheap judge session
# instead of a panel). No selector = every configured session (the default); the
# selector is a WHITELIST, e.g. `--only r1_judge_w2_j1,r2_judge_i1_j1`
# (`r<round>[_judge_<version>[_j<index>]]`, also `2:judge_i1_j1` or a roundless
# `w2_j1`) -- see `OnlySpec` and `validate_only_judge_selectors`, which refuse an
# unknown round, version or judge index before anything starts.
JUDGES_ENABLED_ALL = "all"


def judgeable_ids(ctx, r: int) -> list:
    """The version ids a judge session in round `r` may target, in field order.

    The judge field is the pristine original, every EARLIER ROUND's pin (its id is
    the pinned run id, e.g. `r1_w2` -- in round 2 the base member IS that pin; the
    fresh `a1` copy of it is always content-identical and dropped by the field's
    deduplication), the round's pool (a1, w1.., a2..) and the integration arms the
    round's `--integrators` mask selected -- not just the pool, which is why
    `r2_judge_i1_j1` is a valid selector.
    """
    m, n = round_counts(ctx, r)
    return [ORIGINAL_ID] + round_pin_ids(ctx, r) + list(round_pool_ids(m, n)) \
        + [integrate_vid(k) for k in integrator_arms(m, n, round_integrators(ctx, r))]


def round_pin_ids(ctx, r: int) -> list:
    """The ids of the pins earlier rounds contributed to round `r`'s field.

    A pin's id is the run id of the version that won its round (`r1_w2`), and the
    field's deduplication keeps it as the round's base member: the fresh `a1` copy
    of that same content is dropped. So `r1_w2` -- not `a1` -- is the version a
    round-2 judge session on the base actually targets.
    """
    out = []
    for pin in sorted(ctx.state.get("pinned") or [], key=lambda p: int(p.get("round") or 0)):
        if int(pin.get("round") or 0) < int(r) and pin.get("id"):
            out.append(str(pin["id"]))
    return out


def judges_enabled_spec(ctx, r: int) -> str:
    """The selector string in force for round `r` ("" when every judge runs).

    A DECIDED round's recorded plan wins, exactly like round_judges(): `decide`
    must recompute the stored panel's expectation from the plan that produced it.
    """
    try:
        plan = (ctx.round_get(int(r)) or {}).get("plan") or {}
    except Exception:                                        # noqa: BLE001
        plan = {}
    rrec = {}
    try:
        rrec = ctx.round_get(int(r)) or {}
    except Exception:                                        # noqa: BLE001
        rrec = {}
    if plan.get("judges_enabled") is not None:
        spec = str(plan["judges_enabled"])
    elif rrec.get("judges_enabled") is not None:
        # A `run --only r1_judge_w2_j1` invocation records its selection here, so
        # a LATER invocation of the same (still pending) round keeps the smaller
        # panel instead of reading a full-panel gap out of the sheets it finds.
        spec = str(rrec["judges_enabled"])
    else:
        spec = ""
    spec = spec.strip()
    return "" if spec.lower() in ("", JUDGES_ENABLED_ALL) else spec


def judge_item_parts(item: str):
    """(round|None, version|None, judge index|None) for ONE judge-selector item.

    Every spelling the operator or `agents` can produce is accepted:

        r1_judge_w2_j1 / 2:judge_i1_j1   the keyword form (and the oldest spelling)
        r1_w2_j1 / 2:i1_j1               `agents`-friendly: ROUND_version_index
        w2_j1 / orig_j2 / a2_j1          no round: every round that has the version
        w2 / r1_judge_w2                 that version's whole panel
        j1 / judge_1 / r1_j1 / r1_judge  one judge index, of every version (of a round)
        r2_r1_w2_j1                      a PIN id as the version: the base of round 2 is
                                         the pin `r1_w2` (its fresh `a1` copy is
                                         content-identical and dropped by the field)

    A version may itself start with `r<digits>_`, which is why the leading round is
    read ONCE, from the front (a last-token-wins scan would read `r2_r1_w2_j1` as
    round 1 and silently drop the selector).
    """
    tok = str(item).strip().lower().replace(" ", "")
    r = None
    m = re.fullmatch(r"r?(\d+)(?:[_:/.-](.*))?", tok)
    if m:
        r, tok = int(m.group(1)), (m.group(2) or "")
    tok = re.sub(r"^judge[_:/.-]?", "", tok)
    if not tok or tok in ("judge", "j"):
        return r, None, None
    if re.fullmatch(r"\d+", tok):            # `judge_1` -> index 1
        return r, None, int(tok)
    k = None
    m = re.fullmatch(r"(.+?)[_:/.-]?j(\d+)", tok)
    if m:
        tok, k = m.group(1), int(m.group(2))
    elif re.fullmatch(r"j[_:/.-]?\d+", tok):  # a bare `j1`
        return r, None, int(re.sub(r"\D", "", tok))
    return r, (tok or None), k


def parse_judges_enabled(spec: str, rounds: int, pool_of, judges_of) -> set:
    """Expand a selector into {(round, version, judge index)}; empty set = all.

    `pool_of(r)` and `judges_of(r)` describe the plan the selector is validated
    against (see `setup`, which builds it from --rewrites/--revises/--judges).
    Raises ValueError with an actionable message on an unknown round/version/index.
    The grammar is documented on judge_item_parts().
    """
    spec = str(spec or "").strip()
    if not spec or spec.lower() == JUDGES_ENABLED_ALL:
        return set()
    out = set()
    for item in [i for i in re.split(r"[,\s]+", spec) if i]:
        r, vid, k = judge_item_parts(item)
        rs = [r] if r else list(range(1, int(rounds) + 1))
        matched = False
        for rr in rs:
            if not (1 <= rr <= int(rounds)):
                raise ValueError(f"{item!r}: round {rr} is outside 1..{int(rounds)}")
            pool = list(pool_of(rr))
            js = int(judges_of(rr))
            if vid is not None and vid not in pool:
                if r:                       # an EXPLICIT round must have the version
                    raise ValueError(f"{item!r}: version {vid!r} is not in round {rr}'s judge "
                                     f"field ({', '.join(pool)})")
                continue                    # no round named: it applies where it exists
            if k is not None and not (1 <= k <= js):
                raise ValueError(f"{item!r}: judge index {k} is outside 1..{js} for round {rr} "
                                 f"(--judges)")
            matched = True
            for v in ([vid] if vid else pool):
                for j in ([k] if k else range(1, js + 1)):
                    out.add((rr, v, j))
        if not matched:
            raise ValueError(f"{item!r}: no round of this plan has version {vid!r} "
                             f"(round 1: {', '.join(pool_of(1))})")
    return out


def judge_selection(ctx, r: int) -> set:
    """{(version, judge index)} enabled in round `r`; an empty set = every session."""
    spec = judges_enabled_spec(ctx, r)
    if not spec:
        return set()
    try:
        triples = parse_judges_enabled(spec, config_rounds(ctx),
                                       lambda rr: judgeable_ids(ctx, rr),
                                       lambda rr: round_judges(ctx, rr))
    except ValueError as e:                                     # a hand-edited config
        print(f"[--only judge selection] WARNING: ignoring the selector for round {r} ({e}); every "
              f"configured judge session will run")
        return set()
    return {(str(v), int(k)) for rr, v, k in triples if int(rr) == int(r)}


def judge_enabled(ctx, r: int, vid: str, judge_index: int) -> bool:
    """Does judge session (round, version, index) run under the `--only` selector?"""
    sel = judge_selection(ctx, r)
    return not sel or (str(vid), int(judge_index)) in sel


def enabled_judges(ctx, r: int, vid: str) -> int:
    """How many judge sessions are enabled for one version (an int, never < 0)."""
    sel = judge_selection(ctx, r)
    if not sel:
        return int(round_judges(ctx, r))
    return len({k for v, k in sel if v == str(vid)})


def judges_enabled_note(ctx, r: int) -> str:
    """A short, printable description of the selector in force for round `r`."""
    spec = judges_enabled_spec(ctx, r)
    if not spec:
        return JUDGES_ENABLED_ALL
    sel = judge_selection(ctx, r)
    return f"{spec} ({len(sel)} session(s) enabled)" if sel else spec


def round_judges(ctx, r: int) -> int:
    """Judge sessions per version for round `r` (`--judges` is a per-round list).

    A decided round's RECORDED plan wins, exactly like round_counts(): `decide`
    must recompute the stored panel's expectation from the plan that produced it,
    so a later edit of the config can never turn a complete panel into a
    "stale --judges value" gap.
    """
    try:
        plan = (ctx.round_get(int(r)) or {}).get("plan") or {}
    except Exception:                                        # noqa: BLE001
        plan = {}
    if is_int(plan.get("judges")):
        return max(0, int(plan["judges"]))
    rounds = config_rounds(ctx)
    return int(counts_of(getattr(ctx, "cfg", None), "judges",
                         rounds)[round_index(r, rounds)])


def round_integrators(ctx, r: int) -> int:
    """The integrator bitmask of round `r` (the recorded plan wins; see INTEGRATOR_ALL)."""
    try:
        plan = (ctx.round_get(int(r)) or {}).get("plan") or {}
    except Exception:                                        # noqa: BLE001
        plan = {}
    if is_int(plan.get("integrators")):
        return max(0, int(plan["integrators"]))
    rounds = config_rounds(ctx)
    return int(masks_of(getattr(ctx, "cfg", None), "integrators",
                        rounds)[round_index(r, rounds)])


def round_review_scope(ctx, r: int) -> str:
    """The review's scope for round `r` (`full` or `formatting-writing`).

    The recorded plan wins (a decided round must re-derive the same review
    contract); otherwise the per-round `review_scope` list from the config,
    extended by repeating its last element exactly like `--rewrites`/`--judges`.
    """
    try:
        plan = (ctx.round_get(int(r)) or {}).get("plan") or {}
    except Exception:                                        # noqa: BLE001
        plan = {}
    scope = str(plan.get("review_scope") or "").strip().lower()
    if scope in REVIEW_SCOPE_VALUES:
        return scope
    rounds = config_rounds(ctx)
    raw = (getattr(ctx, "cfg", None) or {}).get("review_scope")
    if raw is None:
        raw = list(DEFAULTS["review_scope"])
    elif not isinstance(raw, (list, tuple)):
        raw = [raw]
    seq = [str(x).strip().lower() for x in raw if str(x).strip()]
    if not seq:
        seq = ["full"]
    while len(seq) < rounds:
        seq.append(seq[-1])
    value = seq[round_index(r, rounds)]
    if value not in REVIEW_SCOPE_VALUES:
        die(f"pipeline_config.json review_scope entry {value!r} is not one of "
            f"{'|'.join(REVIEW_SCOPE_VALUES)}")
    return value


def scoped_review_checks(scope: str) -> tuple:
    """The check ids a review of this scope must DISPOSE ITSELF (formatting pass)."""
    return FORMATTING_WRITING_CHECKS if scope == "formatting-writing" else ()


def round_pool_ids(m: int, n: int) -> list:
    """The round's pool in canonical order: [a1, w1..wM, a2..a{1+N}]."""
    return ([A1_ID] + [rewrite_vid(k) for k in range(1, int(m) + 1)]
            + [revise_vid(j) for j in range(1, int(n) + 1)])


def round_candidate_ids(m: int, n: int) -> list:
    """Every fresh arm that is eligible to win: the pool minus the base A1,
    plus the integrated candidates."""
    return round_pool_ids(m, n)[1:] + round_integrated_ids(m, n)


def round_integrated_ids(m: int, n: int) -> list:
    """EVERY integrated candidate the pool could produce: i1..iK (K = 1 + M + N).

    This is the full-arm list (used where the pool's shape alone matters, e.g.
    validating a version id). Which of those arms a round actually RUNS is
    decided by its integrator mask -- see round_integrated_run_ids().
    """
    return [integrate_vid(k) for k in range(1, len(round_pool_ids(m, n)) + 1)]


def integrator_arms(m: int, n: int, mask: int) -> list:
    """The 1-based pool positions whose integration arm the mask selects.

    Bit (k-1) of `mask` belongs to the k-th pool member; bits beyond the pool
    size are ignored (so the default 0xFFFFFFFF always means "every applicable
    agent", whatever the round's M and N are).
    """
    pool = round_pool_ids(m, n)
    return [k for k in range(1, len(pool) + 1) if (int(mask) >> (k - 1)) & 1]


def round_integrated_run_ids(ctx, r: int, m: int = None, n: int = None) -> list:
    """The integrated candidates round `r` really produces, in pool order.

    A decided round's own plan wins ("integrated" was frozen when the round was
    decided); otherwise the configured per-round integrator mask decides. An
    empty list means the round runs no integration at all (mask 0, or every
    applicable bit clear).
    """
    try:
        plan = (ctx.round_get(int(r)) or {}).get("plan") or {}
    except Exception:                                        # noqa: BLE001
        plan = {}
    recorded = plan.get("integrated")
    if isinstance(recorded, (list, tuple)):
        # An EMPTY recorded list is meaningful: the round ran no integration at
        # all (integrators 0x0), and a later config edit must not resurrect arms
        # the round never produced.
        return [str(v) for v in recorded]
    if m is None or n is None:
        m, n = round_counts(ctx, r)
    return [integrate_vid(k) for k in integrator_arms(m, n, round_integrators(ctx, r))]


def round_produced_ids(ctx, r: int) -> list:
    """Every round-local version round `r` produces: pool + selected integrations."""
    m, n = round_counts(ctx, r)
    return round_pool_ids(m, n) + round_integrated_run_ids(ctx, r, m, n)


def round_candidate_ids_run(ctx, r: int) -> list:
    """Every fresh arm of round `r` that can WIN: the pool minus the base, plus
    the integrated candidates the round actually ran."""
    m, n = round_counts(ctx, r)
    return round_pool_ids(m, n)[1:] + round_integrated_run_ids(ctx, r, m, n)


def round_fresh_ids(m: int, n: int) -> list:
    """Every round-local version the pool can produce: pool + every integration."""
    return round_pool_ids(m, n) + round_integrated_ids(m, n)

SCORE_MIN = -4
SCORE_MAX = 4

# --- judge contracts v2-v4: the GRADED BASIS of every comparison ------------
# The integer score is a claim about a DEFECT CLASS, not a mood. Judges are
# therefore asked for a small, machine-checkable ledger per comparison:
# `basis` names the tier that DECIDES the comparison (the first tier, in
# priority order, whose net is not zero; for a net-zero comparison with rows,
# the highest-priority tier in which the two versions differ), and
# `resolved`/`introduced` list the concrete items on each side (tier, severity,
# one-line evidence). Contract v2 (this constant) makes the orchestrator
# enforce the claim, so a number cannot be written without something to check
# it against. The scale itself stays -4..+4: the production panel (294 directed
# scores, 2026-09-17) used -3..3 and never once used +-4, so widening the range
# would add rungs nobody uses instead of making the existing ones mean
# something; the tier ledger is what fixes the calibration problem.
# v4 (2026-09-30): the tier ORDER is the score. Every tier carries the same FOUR
# severity rungs (minor 1 / major 2 / critical 3 / fatal 4, a distance from
# correct), the tiers are compared LEXICOGRAPHICALLY in
# correctness > preservation > completeness > consistency > writing > formatting
# order, and the first tier whose net is not zero decides the comparison -- a
# lower-priority gain can never offset a higher-priority loss. (v3 summed the
# tiers additively with differentiated caps and made formatting/writing
# MINOR-only; both are superseded.)
# v5 (2026-10-10): the judge runs its OWN DISCOVERY PASS. A judge is completely
# blind to provenance and is handed NO discovery list, so the defect classes the
# frozen checklist does not own are RE-DERIVED by the judge: one bounded pass
# over every side (target + every opponent, same candidates and depth), recorded
# as one disposed file per side under `judge_review/discovery/` and scored as
# normal ledger rows (the finding's own category decides the tier) wherever the
# sides differ. A pass that never ran is indistinguishable from one that found
# nothing, so a missing or empty pass FAILS the run -- otherwise the panel could
# silently ignore that class of findings again, and a version that resolved one
# would not be ranked ahead of the version that still carried it. (v4 and
# earlier: no discovery pass.)
JUDGE_CONTRACT_VERSION = 5
# The scoring classes, in priority order (2026-10-01 calibration):
#   correctness  -- the truth of what is asserted (wrong claim, strength mismatch)
#   preservation -- content lost or invented between the two versions
#   completeness -- an item the artifact promises / the venue requires, missing
#   consistency  -- the same thing said/spelled/numbered two ways; uneven conventions
#   writing      -- prose quality whose meaning survives (Q2-Q12 of the rubric)
#   formatting   -- purely mechanical layout; pre-normalized before the judge sees it
# Rationale: a minor convention drift must not outrank lost content or a missing
# deliverable, and a prose defect whose meaning survives must not outrank (or be
# outranked by) mechanical layout. Meaning-changing rows are refiled to
# correctness by the class rule, so `consistency` here is the residual class.
BASIS_TIERS = ("correctness", "preservation", "completeness", "consistency", "writing",
               "formatting")
BASIS_VALUES = BASIS_TIERS + ("none",)
# FOUR severity rungs, weakest first, and EVERY tier carries all four: minor 1 /
# major 2 / critical 3 / fatal 4. The rungs are a DISTANCE FROM CORRECT (a
# detail / a reported fact / a conclusion / an unusable artifact-or-claim), not
# a factual-only scale, and each tier can reach the whole -4..+4 range.
SEVERITIES = ("minor", "major", "critical", "fatal")
SEVERITY_WEIGHTS = {"minor": 1, "major": 2, "critical": 3, "fatal": 4}
TIER_ROW_WEIGHTS = {tier: dict(SEVERITY_WEIGHTS) for tier in BASIS_TIERS}
# The per-tier net is capped at +-4: the scale's own bound. What keeps
# correctness ahead of consistency is the LEXICOGRAPHIC tier order, not a
# differentiated cap (see derived_comparison_score).
TIER_CAPS = {tier: 4 for tier in BASIS_TIERS}
# The venue LENGTH checks keep their own single-rung policy: a length/caption
# row is a formatting-tier MINOR row, and length can only ever move a comparison
# by at most +-1 (the length rule is a standing exemption, not a scoring tier).
LENGTH_GUARD_CHECKS = ("M18", "M19")
EVIDENCE_MAX_WORDS = 25

# Caption cap for the pipeline's OWN extra check (id M18).
#
# Provenance, stated honestly: this cap is NOT part of the master revision
# prompt and NOT part of either skill (in the skills, M18 is the first number
# reserved for discovery proposals). It is a pipeline SUGGESTION, and it is
# exactly that -- a suggestion: an over-limit caption is REPORTED (as an M18
# formatting item) and never enforced. It can never make a version ineligible,
# can never be the reason a round falls back to its base, and never fails a
# decision. That is why the default is 0 (no caption cap at all): an operator
# who never asked for this pipeline-imposed rule gets no part of it, exactly as
# the master prompt's cover-letter 300-500 word rule is carried as a flaggable
# formatting item and never as a gate.
#
# FIGURE_CAPTION_WORD_LIMIT is the conventional suggested value an operator can
# opt into with `setup --caption-limit 300`; DEFAULT_CAPTION_LIMIT is what the
# pipeline uses when nothing was configured (no suggestion, nothing reported).
FIGURE_CAPTION_WORD_LIMIT = 300
DEFAULT_CAPTION_LIMIT = 0


# ---- The venue's own length limits, relaxed by this pipeline (check id M19)
#
# The numbers come from the configured venue profile (`length_limits` in
# venue_profiles/<id>.json), not from this file. The shipped
# `nature-biotechnology` profile carries the limits this pipeline originally
# hard-coded -- its content-types table states, for an ARTICLE:
#   * abstract  -- up to 150 words, unreferenced;
#   * main text -- up to 3,000 words, EXCLUDING abstract, Methods, references
#                  and figure legends.
# They are applied RELAXED by the operator's margins (NBT: +10% on the
# abstract, +25% on the main text). The cap is the largest INTEGER word count
# that stays inside the relaxation (floor of base*factor): 150*1.10 = 165 and
# 3000*1.25 -> exactly 3,750. A submission of another content type
# (Resource, Brief Communication, ...) takes THAT type's numbers from the same
# venue table with the same two margins; the prompts require the base and its
# source to be named in the artifact.
#
# A profile may also set NO limits (base and relaxation null, as the shipped
# `generic` profile does): the counts are still enumerated and the stage names
# the limit the target journal's own guidelines state, but this pipeline has no
# cap to compare against, so nothing can be "over the cap" here.
#
# The constants below are the shipped nature-biotechnology profile in its old
# module-level spelling, kept for tools and tests that import them; every stage
# reads `length_limits(venue_profile)` instead.


def lenient_word_limit(base: int, factor: float) -> int:
    """The largest integer word count within `base` words relaxed by `factor`."""
    # floor(base*factor), tolerant of the float representation error that made
    # "100 words +15%" 114.99999999999999 -> 114 instead of 115.
    return math.floor(float(base) * float(factor) + 1e-9)


def _builtin_default_venue_object() -> VenueProfile:
    """The module-level default profile, constructed without ever bricking the CLI.

    An invalid SHIPPED default profile -- e.g. one an `add-venue` run wrote
    before this guard existed -- must not make every command, including
    `set-venue`/`status`, die at import. Fall back to the embedded literal and
    say why so the operator can repair the file.
    """
    try:
        return VenueProfile(BUILTIN_VENUE_PROFILES[DEFAULT_VENUE], origin="built-in")
    except (VenueProfileError, ValueError, KeyError, TypeError) as e:
        print(f"[venue] WARNING: the default profile does not validate ({e}); using the "
              f"built-in fallback rules. Repair {VENUE_PROFILES_DIRNAME}/"
              f"{DEFAULT_VENUE}{VENUE_PROFILE_SUFFIX} (or the venue store copy).",
              file=sys.stderr)
        return VenueProfile(copy.deepcopy(_DEFAULT_VENUE_PROFILE), origin="built-in")


_DEFAULT_VENUE_OBJ = _builtin_default_venue_object()
_DEFAULT_LIMITS = _DEFAULT_VENUE_OBJ.length_limits()
DEFAULT_ARTICLE_ABSTRACT_WORDS = _DEFAULT_LIMITS["abstract"]["base"]
DEFAULT_ARTICLE_MAIN_TEXT_WORDS = _DEFAULT_LIMITS["main text"]["base"]
ABSTRACT_RELAXATION = _DEFAULT_LIMITS["abstract"]["relaxation"]
MAIN_TEXT_RELAXATION = _DEFAULT_LIMITS["main text"]["relaxation"]
DEFAULT_ARTICLE_ABSTRACT_CAP = _DEFAULT_LIMITS["abstract"]["cap"]
DEFAULT_ARTICLE_MAIN_TEXT_CAP = _DEFAULT_LIMITS["main text"]["cap"]
DEFAULT_LENGTH_LIMITS_SOURCE = _DEFAULT_VENUE_OBJ.length_limits_source
COVER_LETTER_MIN_WORDS = _DEFAULT_LIMITS["cover letter"]["min"]
COVER_LETTER_MAX_WORDS = _DEFAULT_LIMITS["cover letter"]["max"]
COVER_LETTER_SOURCE = _DEFAULT_LIMITS["cover letter"]["source"]
# The operator's TOTAL-content budget for the letter (salutation, body,
# disclosures and signature): a cap, unlike the 300-500 persuading-part
# preference. 650 words by default; a profile may override it.
COVER_LETTER_TOTAL_MAX_WORDS = _DEFAULT_LIMITS["cover letter"].get("total_max")


def length_limits(profile=None) -> dict:
    """The pipeline's lenient caps for the abstract and the main text.

    Without an argument this is the DEFAULT venue's rule set (the behaviour of
    every call site written before venues existed); a stage passes its root's
    `VenueProfile` instead, so a venue change moves the numbers with it.
    """
    prof = profile if isinstance(profile, VenueProfile) else default_venue_profile()
    return prof.length_limits()


def length_limits_source(profile=None) -> str:
    """The provenance string the M19 artifact and the scans carry."""
    prof = profile if isinstance(profile, VenueProfile) else default_venue_profile()
    return prof.length_limits_source


def relaxation_note(profile=None) -> str:
    """One clause describing how the venue's own limits are relaxed here."""
    limits = length_limits(profile)
    parts = []
    for key, label in (("abstract", "abstract"), ("main text", "main text")):
        spec = limits[key]
        if spec.get("base") is None:
            continue
        margin = int(round((float(spec["relaxation"]) - 1.0) * 100))
        parts.append(f"+{margin}% on the {label} (<= {spec['cap']} words)")
    if not parts:
        return ("This venue profile sets no abstract/main-text cap: the counts are recorded "
                "for the author to compare with the target journal's own guidelines")
    return "The venue's own limits are relaxed by this pipeline (" + "; ".join(parts) + ")"


def caption_limit_of(ctx) -> int:
    """The configured (suggested) caption cap; 0 = no caption rule at all.

    A cap the OPERATOR chose (`setup --caption-limit N`, recorded with
    `caption_limit_source: "operator"`) wins; otherwise the VENUE PROFILE's own
    default applies, so a venue that publishes a legend limit carries it into
    the run and a venue change moves the cap with it.
    """
    cfg = getattr(ctx, "cfg", None) or {}
    raw = cfg.get("caption_limit", None)
    source = str(cfg.get("caption_limit_source") or "operator").strip().lower()
    if raw is None or source != "operator":
        prof = venue_profile_of(ctx, required=False)
        return prof.caption_default if prof is not None else DEFAULT_CAPTION_LIMIT
    try:
        v = int(raw)
    except (TypeError, ValueError):
        return DEFAULT_CAPTION_LIMIT
    return max(0, v)


def zotero_mode_of(ctx) -> str:
    """The configured Zotero tooling policy (off|read|edit|apply).

    An unknown value falls back to the DEFAULT mode, never to the most
    permissive one: a hand-edited pipeline_config.json must not be able to
    widen what the agent sessions may do to the operator's library.
    """
    v = str((getattr(ctx, "cfg", None) or {}).get("zotero", DEFAULT_ZOTERO_MODE)
            or "").strip().lower()
    return v if v in ZOTERO_MODES else DEFAULT_ZOTERO_MODE


def placeholder_lookup_of(ctx) -> str:
    """`off` | `online`: may the orchestrator resolve searchable markers itself?"""
    v = str((getattr(ctx, "cfg", None) or {}).get("placeholder_lookup",
                                                  DEFAULT_PLACEHOLDER_LOOKUP)
            or "").strip().lower()
    return v if v in PLACEHOLDER_LOOKUP_MODES else DEFAULT_PLACEHOLDER_LOOKUP


def audit_enabled(ctx) -> bool:
    """Is the round's auditor stage part of the plan?"""
    v = str((getattr(ctx, "cfg", None) or {}).get("audit", DEFAULT_AUDIT)
            or "").strip().lower()
    return (v if v in AUDIT_MODES else DEFAULT_AUDIT) == "on"


def artifact_policy_of(ctx) -> str:
    """`on` | `fix` | `off` -- what a decision-artifact problem does to an attempt.

      on  (default) the attempt FAILS: a decision table closed with one blanket
          sentence, or left with empty cells, is an unfilled artifact (the
          pipeline lost 96 rows to exactly that in a real run).
      fix the orchestrator spends ONE scoped repair session on the failed
          attempt's decision tables -- it may only fill cells, from evidence
          already in the rows -- and then re-runs the SAME postcheck. A repair
          that does not clear the problem is still a failed attempt and the
          normal retry policy takes over. Nothing outside `review/artifacts/`
          and `review/work/` may change, and no row may be added, removed,
          reordered or re-worded (verified byte-for-byte afterwards).
      off recorded as a warning (advisory), never a failure.

    Roots written before the three-valued policy carry the boolean
    `strict_artifacts`/`strict_dispositions` only, and are read as on/off.
    """
    cfg = getattr(ctx, "cfg", None) or {}
    raw = str(cfg.get("artifact_policy") or "").strip().lower()
    if raw in ARTIFACT_POLICIES:
        return raw
    if raw in ("fail", "strict", "true", "yes"):
        return "on"
    if raw in ("repair", "auto"):
        return ARTIFACT_POLICY_FIX
    if raw in ("warn", "advisory", "false", "no", "non-strict"):
        return "off"
    for key in ("strict_artifacts", "strict_dispositions"):
        if key in cfg:
            return "on" if cfg.get(key) else "off"
    return DEFAULT_ARTIFACT_POLICY


def strict_dispositions(ctx) -> bool:
    """Does a decision-artifact problem FAIL the attempt (unless repaired)?

    Both `on` and `fix` fail an attempt that leaves the tables unfilled -- under
    `fix` the failure first goes to one scoped repair session, whose own
    postcheck is judged by this same rule, so a repair cannot wave a table
    through. `off` records the detector's report as a warning instead (the
    report is recorded either way, and `decide --residual-gate` can still refuse
    to certify the result).
    """
    return artifact_policy_of(ctx) != "off"


def artifact_repair_enabled(ctx) -> bool:
    """May a repairable artifact-quality failure go to a scoped repair session?"""
    return artifact_policy_of(ctx) == ARTIFACT_POLICY_FIX

# The user replaced the master prompt's blanket abstract/main-text exemption
# with the journal's own limits relaxed by fixed margins (see the constants
# above). The rule travels with every prompt through STANDING_EXEMPTIONS, and
# the M19 mandates below give each stage its concrete job (sweep, compress,
# port, surface, judge). Like the caption suggestion and the cover-letter rule
# it is a flaggable FORMATTING item, never a gate.
def _as_profile(profile=None) -> VenueProfile:
    """Accept a VenueProfile, a pipeline root context, or nothing (the default)."""
    if isinstance(profile, VenueProfile):
        return profile
    if profile is not None and hasattr(profile, "cfg"):
        prof = venue_profile_of(profile, required=False)
        if prof is not None:
            return prof
    return default_venue_profile()


def _indefinite(noun: str) -> str:
    """"a X" / "an X" for the venue short names the prompts interpolate."""
    text = str(noun or "venue").strip()
    # An initialism takes the article its SPOKEN letters start with ("an NBT",
    # "an F1000", but "a GET"), a word takes the ordinary vowel test.
    initialism = len(text) > 1 and text[0].isupper() and text[1:].isupper()
    vowel = (text[0] in "AEFHILMNORSX") if initialism else (text[:1].lower() in "aeiou")
    return ("an " if vowel else "a ") + text


def _article_phrase(profile: VenueProfile) -> str:
    """`an NBT Article`-style phrase: the profile's label + its article type."""
    prof = _as_profile(profile)
    art = str(prof.article_type or "Article").strip()
    label = prof.label
    return f"{'an' if label[:1].lower() in 'aeiou' else 'a'} {label} {art}"


def _caps_clause(profile: VenueProfile, *, article: bool = False) -> str:
    """The M19 mandate's cap clause, from the venue profile's own numbers.

    A profile without limits (the shipped `generic` one) gets a sentence that
    says so and hands the comparison to the target journal's own guidelines --
    never a number this pipeline invented.
    """
    limits = _as_profile(profile).length_limits()
    abstract, main = limits["abstract"], limits["main text"]
    if abstract["cap"] is None and main["cap"] is None:
        return ("this venue profile sets no abstract or main-text cap, so state the limit the "
                "target journal's own guidelines give and its source in the artifact")
    parts = []
    if abstract["cap"] is not None:
        parts.append(f"abstract <= {abstract['cap']} words")
    if main["cap"] is not None:
        parts.append(f"main text <= {main['cap']} words")
    clause = "; ".join(parts)
    if article:
        clause += (f" for {_article_phrase(profile)}, excluding abstract, Methods, references "
                   f"and figure legends")
    return clause


def _cover_preference_clause(profile: VenueProfile) -> str:
    """The cover-letter preference as words (`300-500`, `at most 200`, `at least 300`).

    A venue may state only one side (Frontiers states a 200-word maximum for the
    submission system's scope statement); the clause then carries that side alone.
    """
    cover = _as_profile(profile).length_limits()["cover letter"]
    lo, hi = cover.get("min"), cover.get("max")
    if lo is None and hi is None:
        return ""
    if lo is None:
        return f"at most {hi} words"
    if hi is None:
        return f"at least {lo} words"
    return f"{lo}-{hi} words"


def cover_letter_guidance(profile=None) -> dict:
    """The venue's RECORDED cover-letter guidance, in one shape every prompt reads.

    `preference` is the persuading-part range/one-sided bound ("" when the
    profile states none), `total_max` the operator's total-content cap (None
    when unset), and `source` the profile's own quoted basis -- the guideline
    text a cover letter falls back to when the venue ships no cover-letter
    template. Never invented: every field comes from the resolved profile.
    """
    prof = _as_profile(profile)
    try:
        lim = prof.length_limits().get("cover letter") or {}
    except Exception:                                          # noqa: BLE001 -- never gate
        lim = {}
    return {"preference": _cover_preference_clause(prof),
            "total_max": lim.get("total_max"),
            "source": str(lim.get("source") or "").strip()}


def cover_letter_guidance_clause(guide: dict) -> str:
    """One readable sentence-fragment of `cover_letter_guidance` ("" when empty)."""
    guide = guide or {}
    bits = []
    if guide.get("preference"):
        bits.append(f"the persuading part is {guide['preference']}")
    if guide.get("total_max") is not None:
        bits.append(f"its TOTAL content (salutation, body, disclosures and signature) "
                    f"must stay within {guide['total_max']} words (the operator's cap)")
    if guide.get("source"):
        bits.append(f"the recorded basis: {guide['source']}")
    return "; ".join(bits)


def length_rule_text(profile=None) -> str:
    """The M19 length rule, rendered from the venue profile (see M19 below).

    The pipeline's own rule is venue-agnostic; the NUMBERS and their provenance
    come from the profile, so a venue change moves the caps with it.
    """
    prof = _as_profile(profile)
    limits = prof.length_limits()
    abstract, main = limits["abstract"], limits["main text"]
    source = prof.length_limits_source
    if abstract["cap"] is None and main["cap"] is None:
        limits_para = (
            f"      carries): this venue profile publishes no abstract or main-text number for\n"
            f"      {_article_phrase(prof)}, so there is no relaxed cap to apply here. The limits "
            f"that DO\n"
            f"      apply are the venue's own: every stage COUNTS the abstract and the main text, "
            f"and each\n"
            f"      artifact names the limit it applied and the source it came from ({source}).")
    else:
        base_bits = []
        if abstract["base"] is not None:
            base_bits.append(f"abstract <= {abstract['base']:,} words")
        if main["base"] is not None:
            base_bits.append(f"main text <= {main['base']:,} words")
        relaxed_bits = []
        if abstract["cap"] is not None:
            margin = int(round((float(abstract["relaxation"]) - 1.0) * 100))
            relaxed_bits.append(f"the abstract +{margin}% (<= {abstract['cap']} words)")
        if main["cap"] is not None:
            margin = int(round((float(main["relaxation"]) - 1.0) * 100))
            relaxed_bits.append(f"the main text +{margin}% (<= {main['cap']} words)")
        limits_para = (
            f"      carries): the limits below DO apply, in their relaxed form. For "
            f"{_article_phrase(prof)} the base limits\n"
            f"      are {' and '.join(base_bits)},\n"
            f"      counted with the abstract, Methods, references and figure legends EXCLUDED "
            f"from the main text ({source}). This pipeline allows\n"
            f"      {' and '.join(relaxed_bits)}. This run is submitted as "
            f"{_article_phrase(prof)}:\n"
            f"      the venue profile's article-type table carries every type the venue "
            f"publishes, and\n"
            f"      `set-article-type` selects which one this is. A type the profile carries no "
            f"number for\n"
            f"      is COUNTED and named from the venue's own table, never measured against "
            f"these caps; a\n"
            f"      submission of another content type uses that type's own base numbers and "
            f"margins from\n"
            f"      the same venue table.\n"
            f"      THE MARGIN IS NOT A LICENCE: a section inside the relaxed cap but ABOVE the "
            f"venue's own\n"
            f"      base number is REPORTED with the margin it uses, and the review must either "
            f"trim it to the\n"
            f"      base number or record, in the M19 artifact, why the margin is being spent "
            f"(a counting\n"
            f"      convention, a quoted passage that cannot be cut). A section in that band is "
            f"never reported\n"
            f"      clean, because the venue's published number is the base one.")
    cover_clause = _cover_preference_clause(prof)
    cover_total = limits['cover letter'].get('total_max')
    cover_total_clause = (
        f"is a SEPARATE cap of {cover_total} words (the operator's default): trim the "
        f"non-persuading\n      boilerplate first, never a claim about the work."
        if cover_total is not None else
        "is counted and recorded, but this profile configures no TOTAL-content cap, so "
        "no\n      total-word limit is applied to it.")
    if cover_clause:
        cover_para = (
            f"    * THE COVER LETTER — A USER PREFERENCE, NOT {_indefinite(prof.short).upper()} "
            f"RULE. Provenance, stated honestly:\n"
            f"      {limits['cover letter'].get('source') or 'the venue profile states no official cover-letter limit.'}\n"
            f"      The master prompt's own preference is therefore applied as written: the "
            f"PERSUADING part (the body explaining the\n"
            f"      work's importance and its suitability for the journal -- excluding the "
            f"salutation, the\n"
            f"      signature block, and required disclosures such as related manuscripts, prior "
            f"editor\n"
            f"      discussions, double-anonymized author details and reviewer suggestions) should "
            f"be\n"
            f"      {cover_clause}. A persuading part outside that\n"
            f"      range is a MINOR formatting item (check id M19), reported and never gated; it "
            f"is never\n"
            f"      presented as a journal requirement, and it is never \"fixed\" by deleting "
            f"content. Count it\n"
            f"      with the pipeline's word rule. The letter's TOTAL content -- salutation, "
            f"body, disclosures\n"
            f"      and signature -- {cover_total_clause}")
    else:
        cover_para = (
            f"    * THE COVER LETTER — NO COVER-LETTER PREFERENCE IS CONFIGURED: this venue\n"
            f"      profile states no cover-letter word limit or preference, so the letter's length\n"
            f"      is counted and recorded but never flagged, scored or cut for length. Its TOTAL\n"
            f"      content {cover_total_clause}")
    return f"""ABSTRACT / MAIN-TEXT LENGTH — THE JOURNAL'S LIMITS, RELAXED BY THIS PIPELINE:
    * This REPLACES the blanket "abstract/main-text length is exempt" standing exemption (the same
      exemption the skills inherit, and the wording the attached master-prompt excerpt below still
{limits_para}
    * COUNTING RULE, for every word count in this pipeline: a word is a maximal run of NON-SPACE
      characters, with a newline treated as space. "state-of-the-art" is ONE word, "2026" is ONE
      word, and an abbreviation with an inner space ("et al.") is two. Do not split hyphenated
      compounds and do not normalise anything else away.
    * An over-limit section is a CATEGORY-4 (technical formatting) item, check id M19: it is
      compressed by removing redundancy, repeated statistics and NON-MEANING-BEARING hedging
      ONLY -- never by deleting scientific content, claims, limitations, data, accession numbers
      or needed methodological detail. A hedge that carries the claim's own strength (a
      limitation, an uncertainty the evidence supports, a result reported as uncertain because
      it is) is CONTENT: stripping it would turn an accurate claim into an overclaim, so it
      stays. Never flag UNDER-length text (the pipeline relaxes upper limits only and invents no
      minimum), never make a length-driven cut to text that is within the cap, and never
      strengthen or weaken a claim in either direction to reach one.
{cover_para}
    * LENGTH IS NEVER A GATE: no version is made ineligible, failed, rejected, de-ranked or
      re-ordered as a whole because of a word count, and length may only ever enter a comparison
      through the FORMATTING tier (a version within the cap may be preferred to one that is over it
      by at most +/-1; two versions both over, or both within, are indistinguishable on this check
      and score 0).
    * A section that cannot be brought within the cap without losing content is left as it is and
      handed to the author as a manual item, exactly like an incompressible caption."""


def standing_exemptions_text(profile=None) -> str:
    """The standing exemptions block, with this venue's length and legend rules."""
    prof = _as_profile(profile)
    cover_clause = _cover_preference_clause(prof)
    cover_total = prof.length_limits()["cover letter"].get("total_max")
    total_pref = (
        f"must stay within {cover_total} words (the operator's default cap; a profile may\n"
        f"    override it)"
        if cover_total is not None else
        "is counted and recorded, but this profile configures no TOTAL-content cap, so no\n"
        "    total-word limit is applied")
    total_plain = (
        f"must stay within {cover_total} words (the operator's default cap)"
        if cover_total is not None else
        "is counted and recorded with no total-word cap (this profile configures none)")
    cover_bullet = (
        f"  * The master prompt's COVER-LETTER rule (the persuading part must be {cover_clause})\n"
        f"    stays a flaggable formatting item: report it, never gate on it. The LETTER ITSELF\n"
        f"    must render to at most TWO pages (a third page is a Major formatting defect) AND\n"
        f"    its TOTAL content -- salutation, body, disclosures and signature -- {total_pref}.\n"
        f"    Trim the non-persuading boilerplate first, never a claim about\n"
        f"    the work, and the page count comes from a render, never from the cached document\n"
        f"    property."
        if cover_clause else
        "  * This venue profile states no COVER-LETTER word rule: the letter's length is recorded\n"
        f"    and reported, never gated and never cut. The LETTER itself must still render to at\n"
        f"    most TWO pages (a third page is a Major formatting defect), measured from a render,\n"
        f"    and its TOTAL content {total_plain}.")
    caption_source = (prof.captions.get("source")
                      or "this venue profile states no figure-legend length rule")
    return f"""Standing exemptions and explicit limits (apply to every mode, always):
  * @@LENGTH_RULE@@
{cover_bullet}
  * FIGURE-LEGEND LENGTH (check id M18) is ALWAYS enumerated: {caption_source}.
    Every stage therefore counts every legend's words;
    when the operator configured a cap (`--caption-limit N`) that cap is used as
    the pipeline's proxy for the venue's limit and an over-cap legend is a
    reportable formatting item; without a cap the counts are recorded and the
    comparison with the venue's limit is handed to the author as a manual
    item. Nothing is ever made ineligible, ranked down, failed or rejected
    because of a legend's word count, and length is never "fixed" by deleting
    scientific content.
  * Speculative "possible AI-generated" content may be flagged ONLY with
    concrete evidence, always labeled "possible", never as a definitive
    accusation, and it can never decide a comparison on its own.""".replace(
    "@@LENGTH_RULE@@", length_rule_text(prof))


# Inserted (with the limit substituted) into every prompt that produces or
# judges content, next to the standing exemptions.
def caption_rule_template(profile=None) -> str:
    """The M18 caption rule, with @@CAPTION_LIMIT@@ left for the caller to fill."""
    prof = _as_profile(profile)
    captions = prof.captions
    published = captions.get("published_limit")
    if published:
        origin = (f"Origin, stated honestly: {prof.label} publishes a figure-legend limit of "
                  f"{published} words ({captions.get('source') or 'venue profile'}). "
                  f"@@CAPTION_LIMIT@@ words is therefore the venue's own limit as carried by this "
                  f"pipeline's profile; the master prompt and both skills do not state a number. "
                  f"Apply it exactly as written here and never claim the venue set a number it "
                  f"did not.")
    else:
        origin = (f"Origin, stated honestly: {captions.get('source') or 'this venue profile states no figure-legend length rule'}. "
                  f"@@CAPTION_LIMIT@@ words is therefore the ORCHESTRATION PIPELINE's proxy\n"
                  f"    for the venue's limit, chosen by the operator at setup (`--caption-limit N`); "
                  f"the master\n"
                  f"    prompt and both skills do not state a number. Apply the proxy exactly as "
                  f"written here and\n"
                  f"    never claim the venue itself set it.")
    return f"""FIGURE-LEGEND LENGTH (check id M18; applies in every mode, including judging):
  * {origin}
  * IT IS NEVER A GATE. An over-cap legend is reported (check id M18) and,
    where it can be done by removing redundancy only, compressed -- and that is all. It must
    NEVER make a version ineligible for a round, never lower a ranking, never fail a run or a
    decision, and never be presented as a requirement. Leaving a caption over the suggested
    length is an acceptable outcome; deleting content to satisfy a word count is not.
  * Where it applies: every figure caption / legend. Count the legend text as a reader sees it
    (the leading "Figure N |" label and title words count; the labels drawn inside the artwork
    do not). If a package has no figure captions, record that as a disposition rather than
    inventing one.
  * An over-limit caption is a reportable FORMATTING item, not a length-exemption case: report it
    (check id M18) and, when the redundancy can be removed without losing anything, do so --
    NEVER by deleting scientific content, claims, limitations, or necessary methodological
    detail. A cut that removes content is a preservation defect and is worse than the long
    caption. A length/caption row is a formatting-tier MINOR row -- the venue's relaxed margins
    make slight over-length intended, so it is never Major/Critical/Fatal: FORMATTING is the
    lowest scoring tier, so a length row can decide only when every other tier (including
    writing) is zero; it must never inflate a candidate's critical-finding count.
  * If a caption cannot be brought under @@CAPTION_LIMIT@@ words without losing content, do not
    guess and do not cut: leave the caption as it is and say so explicitly, listing it for manual
    action (revise: MANUAL_STEPS.md; review: the manual-verification list; judge: the comparison
    reason/notes).
  * Precedence, stated so you do not have to guess: the master prompt's blanket "never make
    length-driven cuts in either direction" is narrowed by this pipeline in exactly TWO places:
    the redundancy-only compression of figure captions (this suggestion, check id M18) and the
    redundancy-only compression of an over-cap abstract or main text (the length rule, check id
    M19). The cover letter keeps that blanket rule unchanged.
  * When judging, caption length sits in the FORMATTING tier of the priority order
    (correctness > preservation > completeness > consistency > writing > formatting). A
    caption-length difference alone never justifies a score beyond +/-1, and two versions that are
    BOTH over the limit are indistinguishable on this check (score 0). Word-count arithmetic is never a
    substitute for judging content, and a version over the suggested length is still fully
    eligible to win the round."""

# Used instead of CAPTION_RULE when no cap is configured (`--caption-limit 0`,
# the default for a venue that publishes no number). The venue's requirement
# still holds, so the legends are STILL enumerated; only the proxy cap and any
# length-based compression/scoring are absent.
def caption_report_text(profile=None) -> str:
    """The no-cap M18 rule: enumerate every legend, compress and score none."""
    prof = _as_profile(profile)
    captions = prof.captions
    origin = (captions.get("source")
              or "this venue profile states no figure-legend length rule")
    return f"""FIGURE-LEGEND LENGTH — ENUMERATED, NO CAP CONFIGURED (check id M18):
  * {origin}, and no proxy cap is
    configured (`--caption-limit 0`). Therefore: COUNT every legend's words and
    record them in your own artifact (`judge_review/artifacts/M18_caption_words.md` for a judge
    session), with the disposition
    "recorded — the venue's per-type limit is not published; the author compares it in Word".
    A legend whose length is obviously inconsistent with its display-item budget still gets a
    normal clarity/formatting finding if it is otherwise defective, but its WORD COUNT alone is
    not a defect here.
  * Do NOT compress, reword, score or rank a legend because of its length while no cap is
    configured, and never make a length-driven cut: the master prompt's "never make
    length-driven cuts in either direction" applies in full. Two versions whose legends are
    both long (or both short) are indistinguishable on M18, and a version is never ineligible,
    de-ranked or failed because of a legend's word count."""


# Compatibility constants: the DEFAULT venue's rendering of each block, for the
# skills, tools and tests that import them by name. Every prompt is built with
# the root's own profile (see apply_m19 / apply_m18 / standing_exemptions_text).
LENGTH_RULE = length_rule_text()
STANDING_EXEMPTIONS = standing_exemptions_text()
CAPTION_RULE = caption_rule_template()
CAPTION_RULE_REPORT = caption_report_text()

